    // Fixed display order for the groups above — same order as the section
    // headers in the MODULE INDEX at the top of this file.
    const TOGGLEABLE_MODULE_GROUP_ORDER = [
        'Core & Chrome',
        'Communication & Social',
        'Home & Reference',
        'Training & Battle',
        'Economy & Banking',
        'Quests',
        'Games & Daily Activities',
    ];

    function getDisabledModules() {
        try {
            const raw = localStorage.getItem(MODULE_TOGGLE_KEY);
            return new Set(raw ? JSON.parse(raw) : []);
        } catch (e) { return new Set(); }
    }

    function setDisabledModules(set) {
        try { localStorage.setItem(MODULE_TOGGLE_KEY, JSON.stringify([...set])); } catch (e) {}
    }

    function isModuleEnabled(id) {
        return !getDisabledModules().has(id);
    }

    // Expose to home screen module card so it can render toggles without
    // needing to duplicate the list.
    window.__NUI_TOGGLEABLE_MODULES__ = TOGGLEABLE_MODULES;

    // Each section is {id, title, render(container)}. Theme picker ships
    // built-in; consuming apps can push more via NeoUI.registerSettingsSection.
    const settingsSections = [];

    // Register the Modules settings section — only visible on the home screen.
    // The render() guard checks location.pathname so the section is a no-op
    // (empty container) on every other page, keeping the settings drawer clean.
    registerSettingsSection({
        id: 'module_toggles',
        title: 'Modules',
        render: function (container) {
            // Only show on the home page — hide on all other pages
            if (!/\/home\/(index\.phtml)?$/.test(location.pathname)) return;

            const disabled = getDisabledModules();

            // Bucket modules by group, preserving TOGGLEABLE_MODULE_GROUP_ORDER.
            // Anything with a group not in that list (shouldn't happen, but
            // cheap insurance against a future typo) falls into "Other" at
            // the end rather than silently vanishing from the panel.
            const byGroup = {};
            TOGGLEABLE_MODULES.forEach(function (mod) {
                const g = mod.group || 'Other';
                if (!byGroup[g]) byGroup[g] = [];
                byGroup[g].push(mod);
            });
            const groupOrder = TOGGLEABLE_MODULE_GROUP_ORDER.concat(
                Object.keys(byGroup).filter(function (g) { return TOGGLEABLE_MODULE_GROUP_ORDER.indexOf(g) === -1; })
            );

            function rowHtml(mod) {
                const on = !disabled.has(mod.id);
                return '<div style="display:flex;align-items:center;justify-content:space-between;padding:8px 0;border-bottom:1px solid var(--nui-border);gap:8px;">' +
                    '<div style="min-width:0;">' +
                        '<div style="font-size:13px;font-weight:700;color:var(--nui-text);">' + mod.label + '</div>' +
                        '<div style="font-size:11px;color:var(--nui-text-muted);">' + mod.desc + '</div>' +
                    '</div>' +
                    '<button type="button" data-mod-toggle="' + mod.id + '" style="flex-shrink:0;padding:5px 14px;border-radius:var(--nui-radius-pill);border:1px solid;font-size:12px;font-weight:700;cursor:pointer;transition:all 0.15s;' +
                        'background:' + (on ? 'var(--nui-accent)' : 'var(--nui-surface-2)') + ';' +
                        'color:' + (on ? 'var(--nui-accent-ink)' : 'var(--nui-text-muted)') + ';' +
                        'border-color:' + (on ? 'var(--nui-accent)' : 'var(--nui-border)') + ';">' +
                        (on ? 'On' : 'Off') +
                    '</button>' +
                '</div>';
            }

            // Each group is its own <details> accordion (same pattern used
            // elsewhere for drawer accordions), nested inside the outer
            // "Modules" collapsible. Groups start open so toggling behavior
            // is unchanged from before — collapsing a group is just an
            // option for cutting down scroll, not a default.
            const rows = groupOrder
                .filter(function (g) { return byGroup[g] && byGroup[g].length; })
                .map(function (g) {
                    const mods = byGroup[g];
                    const onCount = mods.filter(function (m) { return !disabled.has(m.id); }).length;
                    return '<details class="nui-mod-group" open style="margin:6px 0;">' +
                        '<summary style="cursor:pointer;list-style:none;display:flex;justify-content:space-between;align-items:center;padding:6px 2px;font-size:11px;font-weight:800;text-transform:uppercase;letter-spacing:0.4px;color:var(--nui-text-muted);">' +
                            '<span>' + g + '</span>' +
                            '<span class="nui-mod-group-count" style="font-weight:700;opacity:0.7;">' + onCount + '/' + mods.length + '</span>' +
                        '</summary>' +
                        mods.map(rowHtml).join('') +
                    '</details>';
                }).join('');

            // JS-driven collapsible — no <details> to fight WebKit animation
            const MOD_COLLAPSED_KEY = 'neoui_home_modules_collapsed';
            let collapsed;
            try { collapsed = localStorage.getItem(MOD_COLLAPSED_KEY) === '1'; } catch (e) { collapsed = false; }

            container.innerHTML =
                '<div class="nui-drawer-section" style="margin:var(--nui-space-3) 0;">' +
                    '<div id="nui-mod-settings-hdr" class="nui-drawer-section-title" style="cursor:pointer;display:flex;justify-content:space-between;align-items:center;">' +
                        'Modules' +
                        '<span id="nui-mod-settings-chev" style="font-size:11px;opacity:0.5;transition:transform 0.2s;display:inline-block;transform:' + (collapsed ? 'rotate(-90deg)' : 'rotate(0deg)') + ';">▾</span>' +
                    '</div>' +
                    '<div id="nui-mod-settings-body" style="overflow:hidden;transition:max-height 0.25s ease;max-height:' + (collapsed ? '0' : '2000px') + ';">' +
                        '<div style="font-size:12px;color:var(--nui-text-muted);margin:10px 0 8px;line-height:1.5;">Changes take effect on next page load.</div>' +
                        rows +
                    '</div>' +
                '</div>';

            const hdr  = container.querySelector('#nui-mod-settings-hdr');
            const body = container.querySelector('#nui-mod-settings-body');
            const chev = container.querySelector('#nui-mod-settings-chev');

            hdr.addEventListener('click', function () {
                collapsed = !collapsed;
                try { localStorage.setItem(MOD_COLLAPSED_KEY, collapsed ? '1' : '0'); } catch (e) {}
                body.style.maxHeight = collapsed ? '0' : '2000px';
                chev.style.transform = collapsed ? 'rotate(-90deg)' : 'rotate(0deg)';
            });

            container.querySelectorAll('[data-mod-toggle]').forEach(function (btn) {
                btn.addEventListener('click', function (e) {
                    e.stopPropagation();
                    const id = btn.getAttribute('data-mod-toggle');
                    const d = getDisabledModules();
                    const nowOn = d.has(id);
                    if (nowOn) d.delete(id); else d.add(id);
                    setDisabledModules(d);
                    btn.textContent = nowOn ? 'On' : 'Off';
                    btn.style.background = nowOn ? 'var(--nui-accent)' : 'var(--nui-surface-2)';
                    btn.style.color = nowOn ? 'var(--nui-accent-ink)' : 'var(--nui-text-muted)';
                    btn.style.borderColor = nowOn ? 'var(--nui-accent)' : 'var(--nui-border)';

                    // Keep the group's "N/total enabled" badge in sync without
                    // re-rendering the whole panel (which would also collapse
                    // any groups the person had closed).
                    const group = btn.closest('details.nui-mod-group');
                    if (group) {
                        const countEl = group.querySelector('.nui-mod-group-count');
                        if (countEl) {
                            const toggles = group.querySelectorAll('[data-mod-toggle]');
                            const on = Array.from(toggles).filter(function (b) { return b.textContent === 'On'; }).length;
                            countEl.textContent = on + '/' + toggles.length;
                        }
                    }
                });
            });
        }
    });


