                '<a href="/inventory.phtml" style="color:var(--nui-danger); text-decoration:none; font-size:18px;">◀</a>' +
                '<span style="font-family:var(--nui-font-display); font-size:22px; font-weight:800; color:var(--nui-text);">Safety Deposit Box</span>' +
            '</div>';

        var bulkSenderBtn = document.createElement('button');
