        npBtn.textContent = '🪙 NP';
        var ncBtn = document.createElement('button');
        ncBtn.className = 'nui-sdb-pill' + (state.viewFilter === 'nc' ? ' active' : '');
        ncBtn.textContent = '💎 NC';
        npBtn.onclick = function () { state.viewFilter = 'np'; state.page = 1; npBtn.className = 'nui-sdb-pill active'; ncBtn.className = 'nui-sdb-pill'; fetchItems(); };
        ncBtn.onclick = function () { state.viewFilter = 'nc'; state.page = 1; ncBtn.className = 'nui-sdb-pill active'; npBtn.className = 'nui-sdb-pill'; fetchItems(); };

