        '.questlog-quest.ql-premium .ql-progress-bar{background:#d99a1c;}',
        '.questlog-quest.ql-tada{border-color:#5A76A5;}',
        '.questlog-quest.ql-tada .ql-reward{border-bottom-color:#5A76A5;background:color-mix(in srgb,#5A76A5 10%,var(--nui-surface));}',
        '.questlog-quest.ql-tada .ql-progress-bar{background:#5A76A5;}',
        '.questlog-quest.ql-ff{border-color:#885AA5;}',
        '.questlog-quest.ql-ff .ql-reward{border-bottom-color:#885AA5;background:color-mix(in srgb,#885AA5 10%,var(--nui-surface));}',
        '.questlog-quest.ql-ff .ql-progress-bar{background:#885AA5;}',

        // Popups — ensure they stack above the topbar
        '.ql-popup{z-index:100002!important;}',
        '#navpopupshade__2020.nav-popup-shade__2020{z-index:100001!important;}',
        '.ql-popup .ql-newbie-items{width:100%;padding:10px 0;display:flex;flex-wrap:wrap;justify-content:center;gap:12px;}',
        '.ql-popup .ql-newbie-items .ql-newbie-item{display:flex;flex-direction:column;align-items:center;gap:6px;}',
        '.ql-popup .ql-newbie-items .ql-newbie-item .ql-item-img{width:56px;height:56px;border-radius:8px;border:1px solid var(--nui-border);}',
        '.ql-popup .ql-newbie-items .ql-newbie-item .ql-item-label{font-size:11.5px;font-weight:700;color:var(--nui-text);}',
        '.ql-popup .ql-reward-np{width:64px;height:64px;margin:auto;}',
        '.ql-popup .ql-reward-np::before{content:"💰";font-size:34px;display:block;text-align:center;line-height:64px;}',
        '.ql-popup .ql-reroll-cost{margin:10px auto;text-align:center;}',
        '.ql-popup .ql-reroll-cost img{max-width:64px;max-height:64px;}',
        '.ql-popup .ql-reroll-cost .ql-reroll-np{font-size:13px;font-weight:800;color:var(--nui-text);}',
        '.ql-popup .ql-error-msg{color:var(--nui-danger,#d42326);font-weight:700;font-size:12.5px;}',
        '.ql-popup-carousel{position:relative;width:100%;margin:auto;box-sizing:border-box;}',
