// ==============================================================================
// MODULE 31: ALLEVENTS
// ==============================================================================
// Compact iframe UI for the sitewide All Events notification drawer.
// ==============================================================================

(function () {
    'use strict';

    if (!/\/allevents\.phtml/.test(location.pathname)) return;
    if (!window.NeoUI || !window.NeoUI.isModuleEnabled('allevents')) return;

    // ── Data source ──────────────────────────────────────────────────────────
    // Neopets v2 page pre-populates window.__allEventsData with:
    //   { events: [{eventId, dateLabel, timeLabel, title, iconUrl, url,
    //               descHtml}], atMax: bool, refCk: string }
    // We read from that instead of scraping the DOM.

    function getPageData() {
        const d = window.__allEventsData || {};
        return {
            events: Array.isArray(d.events) ? d.events.slice() : [],
            atMax:  !!d.atMax,
            refCk:  d.refCk || '',
        };
    }

    async function deleteEvents(refCk, type, ids) {
        const body = Object.assign({ _ref_ck: refCk, type }, type === 'selected' ? { event_ids: ids } : {});
        const resp = await fetch('/np-templates/ajax/allevents/delete.php', {
            method: 'POST',
            headers: { 'Content-Type': 'application/json', 'x-requested-with': 'XMLHttpRequest' },
            body: JSON.stringify(body),
        });
        if (!resp.ok) throw new Error('HTTP ' + resp.status);
        const data = await resp.json();
        if (!data.success) throw new Error(data.error || 'delete_failed');
        return data;
    }

    // ── Render ───────────────────────────────────────────────────────────────

    function buildUI() {
        // Suppress native Vue app and its stylesheet
        const nativeApp = document.getElementById('allevents-vue-app');
        if (nativeApp) nativeApp.style.display = 'none';
        document.querySelectorAll('link[href*="allevents"]').forEach(l => l.disabled = true);

        const { events: initialEvents, atMax, refCk } = getPageData();
        let events = initialEvents.slice();
        let selected = new Set();
        let busy = false;

                   // ── Boot NeoUI shell (same pattern as other SPA modules) ──────────
        const profile = NeoUI.scrapeLegacyProfile();
        document.body.innerHTML = '';
        document.body.className = 'nui-reset nui-spa-active';
        document.documentElement.style.background = 'var(--nui-bg)';
        document.body.style.background = 'var(--nui-bg)';
        if (typeof NeoUI.resetDrawer === 'function') NeoUI.resetDrawer();
        NeoUI.init();
        NeoUI.setProfileInfo(profile);

        // 1. Build the topbar as normal so Sitewide Chrome sees it and backs off
        const topbar = NeoUI.buildTopbar({ stats: { np: profile.np, nc: profile.nc }, hasNotification: profile.hasNotification });

        // 2. Check if we're in the drawer (iframe or hash fallback)
        const inIframe = window.self !== window.top || window.location.hash === '#drawer';

        // 3. Hide it if we're trapped in the drawer
        if (inIframe && topbar) {
            topbar.style.display = 'none';
        }

        // Page + card shell
        const pageWrapper = document.createElement('div');
        // Adjust padding conditionally so there isn't a huge gap
        const paddingTop = inIframe ? 'var(--nui-space-5)' : 'calc(var(--nui-topbar-h) + var(--nui-space-5))';
        pageWrapper.style.cssText = `min-height:100vh;display:flex;flex-direction:column;align-items:center;padding:${paddingTop} var(--nui-space-4) var(--nui-space-5);box-sizing:border-box;`;
        document.body.appendChild(pageWrapper);

        const card = document.createElement('div');
        card.className = 'nui-surface';
        card.style.cssText = 'width:100%;max-width:700px;border-radius:var(--nui-radius-lg);border:1px solid var(--nui-border);overflow:hidden;display:flex;flex-direction:column;';
        pageWrapper.appendChild(card);

        // ── NeoUI Timer Alerts ────────────────────────────────────────────────
        // Read ready items from localStorage (works from iframe context too).
        (function buildTimerAlerts() {
            let timerItems = {};
            try {
                const raw = localStorage.getItem('neoui_timer_ready_v1');
                if (raw) timerItems = JSON.parse(raw);
            } catch (e) {}

            const ids = Object.keys(timerItems);
            if (!ids.length) return;

            const alertsCard = document.createElement('div');
            alertsCard.className = 'nui-surface';
            alertsCard.style.cssText = 'width:100%;max-width:700px;border-radius:var(--nui-radius-lg);border:1px solid #fde68a;overflow:hidden;display:flex;flex-direction:column;margin-bottom:var(--nui-space-3);';

            const alertsHeader = document.createElement('div');
            alertsHeader.style.cssText = 'padding:10px 14px;border-bottom:1px solid #fde68a;background:linear-gradient(135deg,#fffbeb,var(--nui-surface-2));display:flex;align-items:center;gap:8px;';
            alertsHeader.innerHTML = '<span style="font-size:15px;">⏰</span><span style="font-weight:800;font-size:14px;color:var(--nui-text);flex:1;">Timer Alerts</span><span style="font-size:10px;padding:2px 7px;border-radius:var(--nui-radius-pill);background:#f59e0b;color:#fff;font-weight:700;">' + ids.length + ' ready</span>';
            alertsCard.appendChild(alertsHeader);

            function saveAndRedraw() {
                try { localStorage.setItem('neoui_timer_ready_v1', JSON.stringify(timerItems)); } catch (e) {}
                // Update parent window's in-memory state + bell dot if accessible
                try {
                    // Sync parent window's bell dot if accessible (same-origin iframe).
                    // Core reads _timerReadyItems from localStorage on next load;
                    // the timerReady/timerCleared calls here keep the dot live
                    // without requiring a page reload.
                    if (window.parent && window.parent.NeoUI) {
                        const p = window.parent.NeoUI;
                        const remaining = Object.keys(timerItems);
                        const allIds = new Set([
                            ...remaining,
                            ...Object.keys(window.parent._nuiTimerSnapshot || {}),
                        ]);
                        allIds.forEach(id => {
                            if (timerItems[id] && p.timerReady) {
                                p.timerReady(id, timerItems[id].label, timerItems[id].href, timerItems[id].icon);
                            } else if (!timerItems[id] && p.timerCleared) {
                                p.timerCleared(id);
                            }
                        });
                    }
                } catch (e) { /* cross-origin or no parent */ }
                redrawAlertsList();
            }

            const alertsList = document.createElement('div');
            alertsCard.appendChild(alertsList);

            function redrawAlertsList() {
                alertsList.innerHTML = '';
                const remaining = Object.entries(timerItems);
                if (!remaining.length) {
                    alertsCard.remove();
                    return;
                }
                alertsHeader.querySelector('span:last-child').textContent = remaining.length + ' ready';
                remaining.forEach(function ([id, item]) {
                    const row = document.createElement('div');
                    row.style.cssText = 'display:flex;align-items:center;gap:10px;padding:10px 14px;border-bottom:1px solid var(--nui-border);';
                    row.innerHTML = [
                        '<span style="font-size:18px;flex-shrink:0;">' + (item.icon || '🔔') + '</span>',
                        '<div style="flex:1;min-width:0;display:flex;flex-direction:column;gap:1px;">',
                        '  <a href="' + item.href + '" target="_top" style="font-weight:700;font-size:13px;color:var(--nui-text);text-decoration:none;white-space:nowrap;overflow:hidden;text-overflow:ellipsis;">' + item.label + '</a>',
                        '  <span style="font-size:11px;color:var(--nui-text-muted);">Ready — tap to go</span>',
                        '</div>',
                        '<button type="button" data-dismiss="' + id + '" style="flex-shrink:0;width:28px;height:28px;border-radius:50%;border:1px solid var(--nui-border);background:var(--nui-surface-2);color:var(--nui-text-muted);font-size:14px;cursor:pointer;display:flex;align-items:center;justify-content:center;" title="Dismiss">✕</button>',
                    ].join('');
                    row.querySelector('[data-dismiss]').addEventListener('click', function () {
                        delete timerItems[id];
                        saveAndRedraw();
                    });
                    alertsList.appendChild(row);
                });
            }

            redrawAlertsList();
            pageWrapper.insertBefore(alertsCard, card);
        })();

        // Card header (back button + title + subtitle)
        const cardHeader = document.createElement('div');
        cardHeader.style.cssText = 'padding:var(--nui-space-4);border-bottom:1px solid var(--nui-border);display:flex;align-items:center;gap:12px;';
        cardHeader.innerHTML = '<a href="/" style="display:flex;align-items:center;justify-content:center;width:32px;height:32px;border-radius:50%;background:var(--nui-danger);color:#fff;text-decoration:none;font-size:18px;font-weight:900;flex-shrink:0;line-height:1;">‹</a>' +
            '<div><div style="font-family:var(--nui-font-display);font-size:20px;font-weight:800;color:var(--nui-text);">Event Inbox</div>' +
            '<div class="nui-ae-subtitle" style="font-size:12px;color:var(--nui-text-muted);margin-top:1px;">' +
                (events.length ? (atMax ? events.length + ' events (page max)' : events.length + ' event' + (events.length !== 1 ? 's' : '')) : 'All caught up!') +
            '</div></div>';
        card.appendChild(cardHeader);

        // ── Toolbar ───────────────────────────────────────────────────────
        const toolbar = document.createElement('div');
        toolbar.style.cssText = 'display:flex;align-items:center;gap:8px;padding:10px var(--nui-space-4);border-bottom:1px solid var(--nui-border);flex-shrink:0;flex-wrap:wrap;';

        const selectAllLabel = document.createElement('label');
        selectAllLabel.style.cssText = 'display:flex;align-items:center;gap:6px;font-size:13px;font-weight:700;color:var(--nui-text);cursor:pointer;user-select:none;';
        const selectAllCb = document.createElement('input');
        selectAllCb.type = 'checkbox';
        selectAllCb.style.cssText = 'width:16px;height:16px;accent-color:var(--nui-accent);cursor:pointer;';
        selectAllLabel.appendChild(selectAllCb);
        selectAllLabel.appendChild(document.createTextNode('Select all'));

        const selCount = document.createElement('span');
        selCount.style.cssText = 'font-size:12px;color:var(--nui-text-muted);margin-left:2px;';

        const spacer = document.createElement('div');
        spacer.style.flex = '1';

        const deleteSelBtn = document.createElement('button');
        deleteSelBtn.type = 'button';
        deleteSelBtn.textContent = 'Delete selected';
        deleteSelBtn.style.cssText = 'padding:6px 14px;border-radius:var(--nui-radius-pill);border:none;background:var(--nui-accent);color:var(--nui-accent-ink);font-size:12px;font-weight:700;cursor:pointer;opacity:0.4;pointer-events:none;transition:opacity 0.15s;';

        const deleteAllBtn = document.createElement('button');
        deleteAllBtn.type = 'button';
        deleteAllBtn.textContent = 'Delete all';
        deleteAllBtn.style.cssText = 'padding:6px 14px;border-radius:var(--nui-radius-pill);border:1px solid var(--nui-border);background:var(--nui-surface-2);color:var(--nui-danger);font-size:12px;font-weight:700;cursor:pointer;transition:opacity 0.15s;';

        toolbar.append(selectAllLabel, selCount, spacer, deleteSelBtn, deleteAllBtn);
        card.appendChild(toolbar);

        // ── List ──────────────────────────────────────────────────────────
        const list = document.createElement('div');
        list.style.cssText = 'flex:1;overflow-y:auto;-webkit-overflow-scrolling:touch;';
        card.appendChild(list);

        const statusBar = document.createElement('div');
        statusBar.style.cssText = 'padding:10px var(--nui-space-4);font-size:12px;color:var(--nui-accent);font-weight:700;display:none;text-align:center;';
        card.appendChild(statusBar);

        // ── State → DOM ───────────────────────────────────────────────────

        function updateToolbar() {
            const n = selected.size;
            selCount.textContent = n > 0 ? `(${n} selected)` : '';
            selectAllCb.checked = events.length > 0 && n === events.length;
            selectAllCb.indeterminate = n > 0 && n < events.length;
            if (n > 0) {
                deleteSelBtn.style.opacity = '1';
                deleteSelBtn.style.pointerEvents = '';
            } else {
                deleteSelBtn.style.opacity = '0.4';
                deleteSelBtn.style.pointerEvents = 'none';
            }
            const noEvents = events.length === 0;
            deleteAllBtn.style.opacity = noEvents ? '0.4' : '1';
            deleteAllBtn.style.pointerEvents = noEvents ? 'none' : '';
        }

        function updateSubtitle() {
            const sub = card.querySelector('.nui-ae-subtitle');
            if (!sub) return;
            sub.textContent = events.length
                ? (atMax ? events.length + ' events (page max)' : events.length + ' event' + (events.length !== 1 ? 's' : ''))
                : 'All caught up!';
        }

        function renderList() {
            list.innerHTML = '';

            if (events.length === 0) {
                const empty = document.createElement('div');
                empty.style.cssText = 'padding:40px var(--nui-space-4);text-align:center;color:var(--nui-text-muted);font-size:14px;line-height:1.6;';
                empty.innerHTML = '<div style="font-size:32px;margin-bottom:12px;">🎉</div><div style="font-weight:700;color:var(--nui-text);margin-bottom:4px;">All caught up!</div><div>You have no events queued up.</div>';
                list.appendChild(empty);
                return;
            }

            events.forEach((ev, i) => {
                const row = document.createElement('div');
                const isOdd = i % 2 === 0;
                row.style.cssText = `display:flex;align-items:center;gap:10px;padding:10px var(--nui-space-4);border-bottom:1px solid var(--nui-border);background:${isOdd ? 'var(--nui-surface)' : 'var(--nui-surface-2)'};transition:background 0.1s;cursor:pointer;`;

                // Checkbox
                const cb = document.createElement('input');
                cb.type = 'checkbox';
                cb.style.cssText = 'flex-shrink:0;width:16px;height:16px;accent-color:var(--nui-accent);cursor:pointer;';
                cb.checked = selected.has(ev.eventId);

                // Icon
                const iconWrap = document.createElement('a');
                iconWrap.href = ev.url || '#';
                iconWrap.style.cssText = 'flex-shrink:0;width:36px;height:36px;border-radius:var(--nui-radius-sm);overflow:hidden;background:var(--nui-surface-3);display:flex;align-items:center;justify-content:center;';
                iconWrap.addEventListener('click', e => e.stopPropagation());
                if (ev.iconUrl) {
                    const img = document.createElement('img');
                    img.src = ev.iconUrl;
                    img.alt = ev.title || '';
                    img.style.cssText = 'width:100%;height:100%;object-fit:cover;';
                    img.onerror = () => { img.style.display = 'none'; };
                    iconWrap.appendChild(img);
                }

                // Text block
                const text = document.createElement('div');
                text.style.cssText = 'flex:1;min-width:0;';

                const titleLink = document.createElement('a');
                titleLink.href = ev.url || '#';
                titleLink.style.cssText = 'font-size:13px;font-weight:700;color:var(--nui-text);display:block;white-space:nowrap;overflow:hidden;text-overflow:ellipsis;text-decoration:none;';
                titleLink.textContent = ev.title || 'Event';
                titleLink.addEventListener('click', e => e.stopPropagation());

                const desc = document.createElement('div');
                desc.style.cssText = 'font-size:11px;color:var(--nui-text-muted);margin-top:2px;overflow:hidden;display:-webkit-box;-webkit-line-clamp:2;-webkit-box-orient:vertical;';
                desc.innerHTML = ev.descHtml || '';

                const time = document.createElement('div');
                time.style.cssText = 'font-size:10px;color:var(--nui-text-faint);margin-top:3px;';
                time.textContent = [ev.dateLabel, ev.timeLabel].filter(Boolean).join(' · ');

                text.append(titleLink, desc, time);
                row.append(cb, iconWrap, text);

                // Highlight selected state
                function applySelected() {
                    row.style.background = selected.has(ev.eventId)
                        ? 'color-mix(in srgb, var(--nui-accent) 12%, var(--nui-surface))'
                        : (isOdd ? 'var(--nui-surface)' : 'var(--nui-surface-2)');
                    cb.checked = selected.has(ev.eventId);
                }
                applySelected();

                row.addEventListener('click', () => {
                    if (busy) return;
                    if (selected.has(ev.eventId)) selected.delete(ev.eventId);
                    else selected.add(ev.eventId);
                    applySelected();
                    updateToolbar();
                });

                list.appendChild(row);
            });
        }

        function setBusy(state) {
            busy = state;
            deleteSelBtn.disabled = state;
            deleteAllBtn.disabled = state;
            selectAllCb.disabled = state;
            list.style.opacity = state ? '0.5' : '1';
            list.style.pointerEvents = state ? 'none' : '';
        }

        function showStatus(msg, isError) {
            statusBar.textContent = msg;
            statusBar.style.display = 'block';
            statusBar.style.color = isError ? 'var(--nui-danger)' : 'var(--nui-accent)';
            clearTimeout(statusBar._t);
            statusBar._t = setTimeout(() => { statusBar.style.display = 'none'; }, 3000);
        }

        // ── Actions ───────────────────────────────────────────────────────

        selectAllCb.addEventListener('change', () => {
            if (selectAllCb.checked) events.forEach(ev => selected.add(ev.eventId));
            else selected.clear();
            renderList();
            updateToolbar();
        });

        deleteSelBtn.addEventListener('click', async () => {
            if (busy || selected.size === 0) return;
            const ids = Array.from(selected);
            setBusy(true);
            try {
                const data = await deleteEvents(refCk, 'selected', ids);
                const removed = new Set(ids);
                events = events.filter(ev => !removed.has(ev.eventId));
                selected.clear();
                renderList();
                updateToolbar();
                updateSubtitle();
                showStatus(`Deleted ${data.deleted || ids.length} event${ids.length !== 1 ? 's' : ''}.`);
            } catch (e) {
                showStatus('Could not delete events — please try again.', true);
            } finally {
                setBusy(false);
            }
        });

        deleteAllBtn.addEventListener('click', async () => {
            if (busy || events.length === 0) return;
            setBusy(true);
            try {
                await deleteEvents(refCk, 'all', []);
                events = [];
                selected.clear();
                renderList();
                updateToolbar();
                updateSubtitle();
                showStatus('All events deleted.');
            } catch (e) {
                showStatus('Could not delete events — please try again.', true);
            } finally {
                setBusy(false);
            }
        });

        // ── Initial render ────────────────────────────────────────────────
        renderList();
        updateToolbar();
    }

    // __allEventsData is set by an inline <script> before the Vue app mounts.
    // At document-end it's usually already populated, but poll briefly in case
    // the Vue bundle scripts run after us on slower connections.
    function tryBuild(attempts) {
        if (window.__allEventsData) { buildUI(); return; }
        if (attempts > 20) { buildUI(); return; } // give up, render empty state
        setTimeout(function () { tryBuild(attempts + 1); }, 100);
    }
    if (document.readyState === 'loading') {
        document.addEventListener('DOMContentLoaded', function () { tryBuild(0); });
    } else {
        tryBuild(0);
    }

})();

// ==============================================================================
// MODULE 32: THE COINCIDENCE
// ==============================================================================
// True SPA rebuild with a custom SSW modal.
// ==============================================================================

(function () {
    'use strict';

    if (!/\/space\/coincidence\.phtml/.test(location.pathname)) return;
    if (!window.NeoUI || !window.NeoUI.isModuleEnabled('coincidence')) return;

    function showFatalError(err) {
        try {
            const box = document.createElement('div');
            box.style.cssText = 'position:fixed;top:0;left:0;right:0;z-index:99999;background:#fee2e2;color:#7f1d1d;font:14px monospace;padding:15px;white-space:pre-wrap;max-height:50vh;overflow:auto;border-bottom:3px solid #dc2626;';
            box.textContent = 'Coincidence crashed:\n' + (err && err.stack ? err.stack : String(err));
            document.body.insertBefore(box, document.body.firstChild);
        } catch (e2) { }
    }

    const NeoUI = window.NeoUI;

    // Profile is scraped once from the live DOM on first render (when the
    // Neopets chrome is still visible). On subsequent re-renders triggered by
    // reloadSPA() the live DOM has been nuked, so we fall back to this cache.
    let _cachedProfile = null;

    // --- Custom SSW Modal ---
    function openCustomSSW(itemName) { if (window.NeoUI && window.NeoUI.openSSW) window.NeoUI.openSSW(itemName); }

    // --- Dynamic RE Catcher (For AJAX injected events) ---
    function observeInjectedREs() {
        const observer = new MutationObserver((mutations) => {
            mutations.forEach(mutation => {
                mutation.addedNodes.forEach(node => {
                    if (node.nodeType === 1) {
                        if (node.classList && (node.classList.contains('randomEvent') || node.classList.contains('re-container') || node.id === 'randomEvents')) {
                            injectRECard(node.innerHTML);
                            node.style.display = 'none';
                        }
                    }
                });
            });
        });
        observer.observe(document.documentElement, { childList: true, subtree: true });
    }

    function injectRECard(htmlContent) {
        const container = document.getElementById('coincidence-app-wrapper');
        if (!container) return;

        let reCard = document.getElementById('nui-re-card');
        if (!reCard) {
            reCard = document.createElement('div');
            reCard.id = 'nui-re-card';
            reCard.className = 'nui-surface';
            reCard.style.cssText = 'border-radius: var(--nui-radius-lg); border: 2px solid var(--nui-accent); padding: var(--nui-space-4); box-shadow: 0 4px 16px var(--nui-shadow); text-align: center; font-size: 15px; color: var(--nui-text); background: var(--nui-surface-2);';

            // Insert it below the title
            container.insertBefore(reCard, container.children[1]);
        }

        reCard.innerHTML = `
            <div style="font-family: var(--nui-font-display); font-size: 22px; font-weight: 800; color: var(--nui-accent); margin-bottom: 12px; display: flex; align-items: center; justify-content: center; gap: 8px;">
                <span style="font-size: 26px;">⚡</span> Event Result! <span style="font-size: 26px;">⚡</span>
            </div>
            <hr style="border: 0; border-bottom: 1px solid var(--nui-border); margin: 16px 0;">
            ${htmlContent}
        `;
    }

    // --- SPA State Manager ---
    async function reloadSPA(actionUrl, options = {}) {
        const wrapper = document.getElementById('coincidence-app-wrapper');
        if (wrapper) {
            wrapper.style.opacity = '0.5';
            wrapper.style.pointerEvents = 'none';
        }

        try {
            let res;
            if (actionUrl) {
                res = await fetch(actionUrl, options);
            } else {
                res = await fetch('/space/coincidence.phtml');
            }

            const html = await res.text();
            const newDoc = new DOMParser().parseFromString(html, 'text/html');

            if (wrapper) {
                wrapper.style.opacity = '';
                wrapper.style.pointerEvents = '';
            }

            renderCoincidence(newDoc);
        } catch (err) {
            if (wrapper) { wrapper.style.opacity = ''; wrapper.style.pointerEvents = ''; }
            showFatalError(err);
        }
    }

    function renderCoincidence(doc) {
        // Use the live DOM profile on first call; fall back to cache on refreshes
        // (the Neopets chrome is hidden after the first render so scraping would return empty data)
        const freshProfile = NeoUI.scrapeLegacyProfile();
        const profile = (freshProfile && freshProfile.np) ? freshProfile : (_cachedProfile || freshProfile);
        if (freshProfile && freshProfile.np) _cachedProfile = freshProfile;

        // 1. Scrape Quest Items
        const items = [];
        const questTable = doc.getElementById('questItems');
        if (questTable) {
            questTable.querySelectorAll('td').forEach(td => {
                const img = td.querySelector('img');
                const b = td.querySelector('b');
                if (!img || !b) return;
                let itemName = '';
                td.childNodes.forEach(node => {
                    if (node.nodeType === Node.TEXT_NODE && node.nodeValue.trim().length > 0) itemName = node.nodeValue.trim();
                });
                items.push({ name: itemName, qty: b.textContent.trim(), imgSrc: img.src });
            });
        }

        // 2. Scrape Story/Status Text
        const messages = [];
        doc.querySelectorAll('td.content > p').forEach(p => {
            const text = p.textContent.trim();
            if (text && !text.includes('RESEARCH COMPLETE IN:')) messages.push(p.innerHTML);
        });

                // 3. Static RE Scrape (From the POST response DOM)
        const staticREs = [];
        doc.querySelectorAll('.randomEvent, #randomEvents, .re-container').forEach(re => {
            if (re.textContent.trim().length > 0) {
                staticREs.push(re.innerHTML);
            }
        });

        // Catch Coincidence-specific centered results if they aren't marked as standard REs
        doc.querySelectorAll('.content > div[align="center"], td.content > div[align="center"], .content > center, td.content > center').forEach(div => {
            const html = div.innerHTML;
            // Exclude the timer, main UI images, and quest tables. Catch only the results/dialogue.
            if (!html.includes('RESEARCH COMPLETE IN') &&
                !html.includes('id="countdownClock"') &&
                !html.includes('questItems') &&
                !html.includes('coincidence_machine') &&
                div.textContent.trim().length > 0) {
                staticREs.push(html);
            }
        });


        // 4. Scrape Timer (If active)
        let cooldown = null;
        doc.querySelectorAll('script').forEach(script => {
            const match = script.textContent.match(/hours:\s*(\d+),\s*minutes:\s*(\d+),\s*seconds:\s*(\d+)/);
            if (match) {
                cooldown = { h: parseInt(match[1], 10), m: parseInt(match[2], 10), s: parseInt(match[3], 10) };
            }
        });

        // 5. Scrape and Translate Legacy Buttons
        const actionButtons = [];
        doc.querySelectorAll('div[class*="shipButton"]').forEach(btn => {
            const className = Array.from(btn.classList).find(c => c.startsWith('shipButton') && c !== 'shipButton');
            if (!className) return;

            let btnConfig = null;
            if (className === 'shipButtonCancelQuest' || className === 'shipButtonNoCancel') {
                btnConfig = { text: 'Cancel Quest', class: 'nui-btn-danger', action: 'cancel' };
            } else if (className === 'shipButtonReturn' || className === 'shipButtonLater' || className === 'shipButtonYesLater' || className === 'shipButtonNoCreep') {
                btnConfig = { text: 'Leave Ship', class: 'nui-btn-secondary', action: 'link', href: '/explore.phtml' };
            } else if (className === 'shipButtonHelp' || className === 'shipButtonYesAsk' || className === 'shipButtonYesBoldly' || className === 'shipButtonSure') {
                btnConfig = { text: 'Accept / Fire Machine', class: 'nui-btn-primary', action: 'submit_form' };
            } else if (className === 'shipButtonDoIt') {
                btnConfig = { text: 'Complete Quest', class: 'nui-btn-primary', action: 'submit_form' };
            }

            if (btnConfig) {
                btnConfig.legacyForm = btn.closest('form') || doc.getElementById('shipCombine') || doc.getElementById('shipQuest');
                actionButtons.push(btnConfig);
            }
        });

        const uniqueActions = [];
        const seenTexts = new Set();
        actionButtons.forEach(btn => {
            if (!seenTexts.has(btn.text)) {
                seenTexts.add(btn.text);
                uniqueActions.push(btn);
            }
        });

        // 6. Safely Hide Legacy DOM and init shell — only on first render
        const alreadyInitialized = !!document.getElementById('coincidence-main-wrapper');
        if (!alreadyInitialized) {
            Array.from(document.body.children).forEach(child => {
                const tag = child.tagName.toLowerCase();
                if (['script', 'style', 'link'].includes(tag)) return;
                if (['panelPopups', 'neoFade', 'colorbox', 'cboxOverlay', 'cboxWrapper'].includes(child.id)) return;
                child.style.display = 'none';
            });

            document.body.className = 'nui-reset';
            document.documentElement.style.background = 'var(--nui-bg)';
            document.body.style.background = 'var(--nui-bg)';

            if (!NeoUI.isInitialized) NeoUI.init();
            NeoUI.setProfileInfo(profile);
            NeoUI.buildTopbar({ stats: { np: profile.np, nc: profile.nc }, hasNotification: profile.hasNotification });
        }

        // 7. Build the UI
        let pageWrapper = document.getElementById('coincidence-main-wrapper');
        if (!pageWrapper) {
            pageWrapper = document.createElement('div');
            pageWrapper.id = 'coincidence-main-wrapper';
            pageWrapper.style.cssText = 'min-height: 100vh; display: flex; flex-direction: column; align-items: center; padding: calc(var(--nui-topbar-h) + var(--nui-space-4)) var(--nui-space-4) var(--nui-space-5); box-sizing: border-box;';
            document.body.appendChild(pageWrapper);
        } else {
            pageWrapper.innerHTML = '';
        }

        const container = document.createElement('div');
        container.id = 'coincidence-app-wrapper';
        container.style.cssText = 'width: 100%; max-width: 600px; display: flex; flex-direction: column; gap: var(--nui-space-4);';
        pageWrapper.appendChild(container);

        // Banner card
        const coincidenceBanner = document.createElement('div');
        coincidenceBanner.className = 'nui-surface';
        coincidenceBanner.style.cssText = 'border-radius:var(--nui-radius-lg);border:1px solid var(--nui-border);overflow:hidden;box-shadow:0 4px 12px var(--nui-shadow);';
        coincidenceBanner.innerHTML = `
            <div style="position:relative;width:100%;height:110px;overflow:hidden;background:linear-gradient(135deg,var(--nui-bg) 0%,var(--nui-surface-2) 100%);">
                <img src="//images.neopets.com/space/station_bg.gif"
                     style="position:absolute;inset:0;width:100%;height:100%;object-fit:cover;opacity:0.25;"
                     onerror="this.style.display='none'">
                <div style="position:absolute;inset:0;display:flex;align-items:center;justify-content:space-between;padding:0 var(--nui-space-4);">
                    <div style="display:flex;align-items:center;gap:12px;">
                        <img src="//images.neopets.com/space/coincidence_small.gif"
                             style="width:64px;height:64px;border-radius:var(--nui-radius-md);border:2px solid var(--nui-border);object-fit:cover;flex-shrink:0;filter:drop-shadow(0 2px 6px var(--nui-shadow));"
                             onerror="this.style.display='none'">
                        <div>
                            <div style="font-family:var(--nui-font-display);font-weight:800;font-size:26px;color:var(--nui-accent);text-shadow:0 2px 6px var(--nui-shadow);line-height:1.1;">The Coincidence</div>
                            <div style="font-size:12px;color:var(--nui-text-muted);font-weight:600;margin-top:2px;">Dr. Landelbrot's Lab</div>
                        </div>
                    </div>
                    <button type="button" id="nui-coincidence-refresh-btn" class="nui-btn nui-btn-secondary nui-btn-sm" style="flex-shrink:0;display:flex;align-items:center;gap:6px;" title="Refresh quest status">
                        <svg width="14" height="14" fill="none" stroke="currentColor" stroke-width="2.5" viewBox="0 0 24 24"><path stroke-linecap="round" stroke-linejoin="round" d="M4 4v5h.582m15.356 2A8.001 8.001 0 004.582 9m0 0H9m11 11v-5h-.581m0 0a8.003 8.003 0 01-15.357-2m15.357 2H15"></path></svg>
                        Refresh
                    </button>
                </div>
            </div>
        `;
        container.appendChild(coincidenceBanner);

        // Wire the refresh button
        const refreshBtn = coincidenceBanner.querySelector('#nui-coincidence-refresh-btn');
        if (refreshBtn) {
            refreshBtn.addEventListener('click', () => {
                refreshBtn.disabled = true;
                refreshBtn.innerHTML = '<svg width="14" height="14" fill="none" stroke="currentColor" stroke-width="2.5" viewBox="0 0 24 24" style="animation:nui-spin 1s linear infinite"><path stroke-linecap="round" stroke-linejoin="round" d="M4 4v5h.582m15.356 2A8.001 8.001 0 004.582 9m0 0H9m11 11v-5h-.581m0 0a8.003 8.003 0 01-15.357-2m15.357 2H15"></path></svg> Refreshing...';
                if (!document.getElementById('nui-spin-style')) {
                    const s = document.createElement('style');
                    s.id = 'nui-spin-style';
                    s.textContent = '@keyframes nui-spin { to { transform: rotate(360deg); } }';
                    document.head.appendChild(s);
                }
                reloadSPA(null).catch(() => {}).finally(() => {
                    if (refreshBtn) { refreshBtn.disabled = false; refreshBtn.innerHTML = '<svg width="14" height="14" fill="none" stroke="currentColor" stroke-width="2.5" viewBox="0 0 24 24"><path stroke-linecap="round" stroke-linejoin="round" d="M4 4v5h.582m15.356 2A8.001 8.001 0 004.582 9m0 0H9m11 11v-5h-.581m0 0a8.003 8.003 0 01-15.357-2m15.357 2H15"></path></svg> Refresh'; }
                });
            });
        }

        // Render Static REs if caught on load
        if (staticREs.length > 0) {
            injectRECard(staticREs.join('<hr style="border: 0; border-bottom: 1px solid var(--nui-border); margin: 16px 0;">'));
        }

        // Narrative Text Card
        if (messages.length > 0) {
            const msgCard = document.createElement(items.length > 0 ? 'details' : 'div');
            msgCard.className = 'nui-surface';
            msgCard.style.cssText = 'border-radius: var(--nui-radius-lg); border: 1px solid var(--nui-border); padding: var(--nui-space-3) var(--nui-space-4); box-shadow: 0 4px 12px var(--nui-shadow); font-size: 14px; line-height: 1.5; color: var(--nui-text);';
            if (items.length > 0) {
                msgCard.innerHTML = `<summary style="font-weight: 800; cursor: pointer; color: var(--nui-text-muted); outline: none;">Dr. Landelbrot says...</summary><div style="margin-top: 12px;">${messages.join('<br><br>')}</div>`;
            } else {
                msgCard.innerHTML = messages.join('<br><br>');
            }
            container.appendChild(msgCard);
        }

        // Custom Timer UI
        if (cooldown) {
            const timerCard = document.createElement('div');
            timerCard.className = 'nui-surface';
            timerCard.style.cssText = 'border-radius: var(--nui-radius-lg); border: 1px solid var(--nui-border); padding: var(--nui-space-5) var(--nui-space-4); box-shadow: 0 4px 12px var(--nui-shadow); display: flex; flex-direction: column; align-items: center; gap: 12px;';

            timerCard.innerHTML = `
                <div style="font-weight: 800; color: var(--nui-text-muted); font-size: 13px; text-transform: uppercase; letter-spacing: 1px;">Research Complete In</div>
                <div id="nui-ship-timer" style="font-family: var(--nui-font-display); font-size: 42px; font-weight: 800; color: var(--nui-accent); line-height: 1; text-shadow: 0 2px 4px var(--nui-shadow);">
                    --:--:--
                </div>
            `;
            container.appendChild(timerCard);

            let totalSeconds = (cooldown.h * 3600) + (cooldown.m * 60) + cooldown.s;
            const timerDisplay = timerCard.querySelector('#nui-ship-timer');

            const tick = setInterval(() => {
                if (totalSeconds <= 0) {
                    clearInterval(tick);
                    timerDisplay.textContent = "Ready!";
                    reloadSPA();
                    return;
                }
                totalSeconds--;
                const h = Math.floor(totalSeconds / 3600).toString().padStart(2, '0');
                const m = Math.floor((totalSeconds % 3600) / 60).toString().padStart(2, '0');
                const s = (totalSeconds % 60).toString().padStart(2, '0');
                timerDisplay.textContent = `${h}:${m}:${s}`;
            }, 1000);

            const h = Math.floor(totalSeconds / 3600).toString().padStart(2, '0');
            const m = Math.floor((totalSeconds % 3600) / 60).toString().padStart(2, '0');
            const s = (totalSeconds % 60).toString().padStart(2, '0');
            timerDisplay.textContent = `${h}:${m}:${s}`;
        }

        // Quest Items List
        if (items.length > 0) {
            const itemsWrap = document.createElement('div');
            itemsWrap.style.cssText = 'display: flex; flex-direction: column; gap: var(--nui-space-3);';

            items.forEach(item => {
                const card = document.createElement('div');
                card.className = 'nui-surface';
                card.style.cssText = 'border-radius: var(--nui-radius-lg); border: 1px solid var(--nui-border); padding: var(--nui-space-3); display: flex; align-items: center; gap: var(--nui-space-3); box-shadow: 0 2px 6px var(--nui-shadow); flex-wrap: wrap;';

                card.innerHTML = `
                    <div style="width: 56px; height: 56px; border-radius: var(--nui-radius-md); background: var(--nui-surface-2); display: flex; align-items: center; justify-content: center; flex-shrink: 0; border: 1px solid var(--nui-border);">
                        <img src="${item.imgSrc}" style="max-width: 48px; max-height: 48px; object-fit: contain;">
                    </div>
                    <div style="flex: 1; min-width: 120px;">
                        <div style="font-weight: 800; font-size: 15px; color: var(--nui-text);">${item.name}</div>
                        <div class="nui-badge" style="display: inline-block; margin-top: 4px; background: var(--nui-accent-soft); color: var(--nui-accent);">Needed: ${item.qty}</div>
                    </div>
                `;

                const actionsWrap = document.createElement('div');
                actionsWrap.style.cssText = 'display: flex; gap: 8px; align-items: center; margin-left: auto;';

                const copyBtn = document.createElement('button');
                copyBtn.className = 'nui-btn nui-btn-secondary nui-btn-sm';
                copyBtn.style.padding = '8px 12px';
                copyBtn.innerHTML = `<svg width="18" height="18" fill="none" stroke="currentColor" stroke-width="2" viewBox="0 0 24 24"><path stroke-linecap="round" stroke-linejoin="round" d="M8 16H6a2 2 0 01-2-2V6a2 2 0 012-2h8a2 2 0 012 2v2m-6 12h8a2 2 0 002-2v-8a2 2 0 00-2-2h-8a2 2 0 00-2 2v8a2 2 0 002 2z"></path></svg>`;
                copyBtn.addEventListener('click', () => {
                    navigator.clipboard.writeText(item.name);
                    copyBtn.style.color = 'var(--nui-success)';
                    setTimeout(() => copyBtn.style.color = '', 2000);
                });

                const sswBtn = document.createElement('button');
                sswBtn.className = 'nui-btn nui-btn-primary nui-btn-sm';
                sswBtn.style.padding = '8px 16px';
                sswBtn.textContent = 'SSW';
                sswBtn.addEventListener('click', () => openCustomSSW(item.name));

                const swBtn = document.createElement('button');
                swBtn.className = 'nui-btn nui-btn-secondary nui-btn-sm';
                swBtn.style.padding = '8px 16px';
                swBtn.textContent = 'SW';
                swBtn.title = 'Shop Wizard (works without Premium)';
                swBtn.addEventListener('click', () => { if (window.NeoUI && window.NeoUI.openSW) window.NeoUI.openSW(item.name); });

                actionsWrap.appendChild(copyBtn);
                actionsWrap.appendChild(swBtn);
                actionsWrap.appendChild(sswBtn);
                card.appendChild(actionsWrap);
                itemsWrap.appendChild(card);
            });
            container.appendChild(itemsWrap);
        }

        if (uniqueActions.length > 0) {
            const btnWrap = document.createElement('div');
            btnWrap.style.cssText = 'display: flex; flex-direction: column; gap: var(--nui-space-3); margin-top: var(--nui-space-2); width: 100%;';

            uniqueActions.forEach(action => {
                const btn = document.createElement('button');
                btn.className = `nui-btn ${action.class} nui-btn-block`;
                btn.textContent = action.text;

                                btn.addEventListener('click', () => {
                    if (action.action === 'link') {
                        window.location.href = action.href;
                    } else if (action.action === 'cancel') {
                        if (window.confirm('Are you sure you want to cancel? You will forfeit your quest for the day.')) {
                            const refMatch = doc.documentElement.innerHTML.match(/_ref_ck:\s*["']([^"']+)["']/);
                            const fd = new URLSearchParams();
                            if (refMatch) fd.append('_ref_ck', refMatch[1]);

                            const wrapper = document.getElementById('coincidence-app-wrapper');
                            if (wrapper) wrapper.innerHTML = `<div class="nui-empty" style="padding-top: 50px;"><span class="nui-empty-emoji">🚀</span><br>Cancelling quest...</div>`;

                            // Use fetch for the silent cancellation, then force a native reload to stay in sync
                            fetch('/magma/portal/ajax/cancelQuest.php', { method: 'POST', body: fd, headers: { 'Content-Type': 'application/x-www-form-urlencoded' } })
                                .then(() => window.location.href = '/space/coincidence.phtml');
                        }
                    } else if (action.action === 'submit_form') {
                        const wrapper = document.getElementById('coincidence-app-wrapper');
                        if (wrapper) wrapper.innerHTML = `<div class="nui-empty" style="padding-top: 50px;"><span class="nui-empty-emoji">🚀</span><br>Communicating with the ship...</div>`;

                        if (action.legacyForm) {
    // Native submission bypasses SPA routing to ensure hidden Neopets inputs process correctly.
    // Ensure the scraped form is attached to the live DOM before submitting.
    if (!document.body.contains(action.legacyForm)) {
        action.legacyForm.style.display = 'none';
        document.body.appendChild(action.legacyForm);
    }
    action.legacyForm.submit();
} else {
    window.location.href = '/space/coincidence.phtml';
}

                    }
                });

                btnWrap.appendChild(btn);
            });
            container.appendChild(btnWrap);
        }
    }

    if (document.readyState === 'complete' || document.readyState === 'interactive') {
        try {
            observeInjectedREs();
            renderCoincidence(document);
        } catch (err) { showFatalError(err); }
    } else {
        document.addEventListener('DOMContentLoaded', () => {
            try {
                observeInjectedREs();
                renderCoincidence(document);
            } catch (err) { showFatalError(err); }
        });
    }
})();

// ==============================================================================
// MODULE 33: FOOD CLUB
// ==============================================================================
// Pirates, bet, my-bets, collect, history tabs; NeoFoodClub bet-string
// importer; odds calc; max-bet enforced; Collect tab has Trophy Run mode
// (live FIFO winnings-queue tracking with Round-ID-based expiry warnings).
// ==============================================================================

// Activates on: /pirates/foodclub.phtml (all ?type= subpages)
//
// Features:
//   • Pirates tab   — stat table with win-rate bars and sort
//   • Bet tab       — 5-arena dropdowns, live odds calc, max-bet enforced
//   • My Bets tab   — current round bets with odds breakdown
//   • Collect tab   — collect winnings form
//   • History tab   — lifetime bet history stats
//   • Trophy Run tab — models the real trophy-run mechanic: uncollected
//     winnings sit in a single FIFO queue (max 8 rounds — today's + the 7
//     before), collecting is all-or-nothing across the whole queue, and a
//     round expires exactly 7 days after it concluded at Midnight NST. The
//     queue status (size, round span, expiry) is read live off the actual
//     Collect page every render — the site's own data is the source of
//     truth — with a secondary local log for a human-readable day-by-day
//     history. Escalating warnings fire once (newest round − oldest round)
//     reaches 7, with severity increasing as Midnight NST approaches.
//     Stored in localStorage only — purely a label/tracker, never touches
//     real NP or auto-collects (except the explicit Collect buttons, which
//     also clear the local log since a real collect drains everything).
//   • NeoFoodClub bet-string importer — paste an NFC URL/string to generate
//     an editable, auto-capped bet queue (live per-row amount editing, a
//     per-row Max button, and a bulk "set all" control) and submit them
//     sequentially.
// ==============================================================================

(function () {
    'use strict';

    if (!/\/pirates\/foodclub\.phtml/.test(location.pathname)) return;
    if (!window.NeoUI || !window.NeoUI.isModuleEnabled('foodclub')) return;

    const NeoUI = window.NeoUI;
    if (!NeoUI) return;

    // ─────────────────────────────────────────────────────────────────────────
    // FATAL ERROR BOX
    // ─────────────────────────────────────────────────────────────────────────
    function showFatalError(err) {
        try {
            const box = document.createElement('div');
            box.style.cssText = 'position:fixed;top:0;left:0;right:0;z-index:99999;background:#fee2e2;color:#7f1d1d;font:14px monospace;padding:15px;white-space:pre-wrap;max-height:50vh;overflow:auto;border-bottom:3px solid #dc2626;';
            box.textContent = 'Food Club SPA crashed:\n' + (err && err.stack ? err.stack : String(err));
            document.body.insertBefore(box, document.body.firstChild);
        } catch (e2) {}
    }

    const ARENAS = ['Shipwreck', 'Lagoon', 'Treasure Island', 'Hidden Cove', "Harpoon Harry's"];
    const MAX_WIN = 1000000;

    // ─────────────────────────────────────────────────────────────────────────
    // TROPHY RUN — localStorage-backed day/expiry labels
    // ─────────────────────────────────────────────────────────────────────────
    // A "trophy run" is holding food club winnings uncollected across multiple
    // rounds so the eventual single collection posts one large cumulative
    // score on the High Score Table. This is a manual label/tracker only —
    // nothing here touches real NP or auto-collects.
    //
    // How the real system behaves (this is what the logic below models):
    //   • Uncollected winnings sit in a single FIFO queue keyed by Round ID.
    //   • The queue holds at most 8 rounds at once (today's + the 7 before).
    //   • Collecting is all-or-nothing: it drains the entire queue in one
    //     shot, never individual rounds.
    //   • A round's winnings vanish exactly 7 days after that round
    //     concluded, at Midnight NST — i.e. once
    //     (current round ID − oldest queued round ID) reaches 7, the oldest
    //     round expires that same night.
    //
    // The live Collect page (scraped fresh into `rows` every time the tab is
    // opened) *is* that real queue — it's the site's own ground truth, not
    // something we have to reconstruct. So queue-capacity/expiry math below
    // is driven off `rows` + Round IDs, not off when-we-happened-to-visit
    // timestamps. The local `entries` log underneath is a secondary,
    // human-readable day-by-day history of what's been logged — nice for
    // the UI, but never the source of truth for "is this about to expire."
    const TROPHY_KEY = 'neoui_fc_trophy_run';
    const TROPHY_EXPIRY_DAYS = 7;            // legacy fallback for entries with no round number
    const TROPHY_MAX_QUEUE_ROUNDS = 8;       // strict cap: current round + 7 previous
    const TROPHY_EXPIRY_ROUND_DELTA = 7;     // oldest round expires once (newest − oldest) reaches this

    function loadTrophyRun() {
        try {
            const raw = localStorage.getItem(TROPHY_KEY);
            if (!raw) return null;
            const data = JSON.parse(raw);
            if (!data || !Array.isArray(data.entries)) return null;
            return data;
        } catch (e) { return null; }
    }

    function saveTrophyRun(data) {
        try { localStorage.setItem(TROPHY_KEY, JSON.stringify(data)); } catch (e) {}
    }

    function startTrophyRun() {
        const data = { startedAt: Date.now(), entries: [] };
        saveTrophyRun(data);
        return data;
    }

    function endTrophyRun() {
        try { localStorage.removeItem(TROPHY_KEY); } catch (e) {}
    }

    function addTrophyEntry(run, amount, note, round) {
        run.entries.push({
            id: 'e' + Date.now() + Math.random().toString(36).slice(2, 7),
            loggedAt: Date.now(),
            amount: amount,
            note: note || '',
            round: (round != null) ? String(round) : null,
            collected: false,
            collectedAt: null,
        });
        saveTrophyRun(run);
    }

    // Marks every currently-active entry as collected. Collection is
    // all-or-nothing on the real site — a successful "Collect All Winnings"
    // (or the trophy run's emergency collect) drains the *entire* queue at
    // once, so the local log must be fully cleared to match, not left
    // showing rounds that no longer exist.
    function markAllTrophyEntriesCollected(run) {
        const now = Date.now();
        (run.entries || []).forEach(entry => {
            if (!entry.collected) { entry.collected = true; entry.collectedAt = now; }
        });
        saveTrophyRun(run);
        return run;
    }

    // Rounds already represented in this run's entries — used so re-opening
    // the Collect tab or clicking "Log & Hold" again never re-logs the same
    // round's winnings a second time. Falls back to parsing round numbers
    // out of the note text for entries logged before per-round tracking
    // existed (old entries stored one combined blob per click, e.g.
    // "Round 1442, 1443").
    function loggedRoundSet(run) {
        const set = new Set();
        (run.entries || []).forEach(entry => {
            if (entry.round != null) { set.add(String(entry.round)); return; }
            if (entry.note) {
                const nums = entry.note.match(/\d+/g);
                if (nums) nums.forEach(n => set.add(n));
            }
        });
        return set;
    }

    function dayNumberFor(run, ts) {
        const msPerDay = 86400000;
        return Math.floor((ts - run.startedAt) / msPerDay) + 1;
    }

    // Legacy wall-clock fallback — only used for entries with no round
    // number attached (pre-dates per-round tracking). Real expiry is
    // round-based; see computeQueueInfo().
    function expiryInfoFor(entry) {
        const expiresAt = entry.loggedAt + TROPHY_EXPIRY_DAYS * 86400000;
        const msLeft = expiresAt - Date.now();
        const daysLeft = Math.ceil(msLeft / 86400000);
        return { expiresAt, daysLeft, expired: daysLeft <= 0 };
    }

    // ─── Neopian Standard Time (NST = fixed UTC−8, no DST) ─────────────────
    function nstNow() {
        return new Date(Date.now() - 8 * 3600000);
    }

    function msUntilNstMidnight() {
        const nst = nstNow();
        const nextMidnightNst = Date.UTC(nst.getUTCFullYear(), nst.getUTCMonth(), nst.getUTCDate() + 1, 0, 0, 0);
        return nextMidnightNst - nst.getTime();
    }

    function formatHoursMinutes(ms) {
        const totalMin = Math.max(0, Math.round(ms / 60000));
        const h = Math.floor(totalMin / 60);
        const m = totalMin % 60;
        return h > 0 ? `${h}h ${m}m` : `${m}m`;
    }

    // The real, authoritative Winnings Queue — built fresh from the live
    // Collect page every render. This is a FIFO array of {round, amount}
    // sorted oldest→newest by Round ID, capped conceptually at 8 entries
    // (Check Condition 1 fires once the round gap reaches 7 regardless of
    // exact entry count, since a missed betting day can leave the queue
    // under 8 rounds wide even while the oldest is still about to expire).
    function computeQueueInfo(rows) {
        // `rows` is one entry PER WINNING BET (you can place up to 10 bets a
        // round, and any subset can win), but the real winnings queue is
        // keyed by Round ID — multiple winning bets in the same round occupy
        // one queue slot there, not several. Group and sum by round first,
        // or `size`/`atCapacity` below end up counting bets instead of
        // rounds (e.g. 5 rounds with 2 winning bets each would misreport as
        // a 10-round queue and falsely trigger the 8-round capacity/expiry
        // warnings).
        const byRound = new Map(); // round -> { round, roundNum, amount }
        (rows || []).forEach(r => {
            const roundNum = parseInt(r.round, 10);
            if (isNaN(roundNum)) return;
            const n = parseInt((r.winnings || '').replace(/[^0-9]/g, ''), 10);
            const amount = isNaN(n) ? 0 : n;
            const existing = byRound.get(roundNum);
            if (existing) existing.amount += amount;
            else byRound.set(roundNum, { round: r.round, roundNum, amount });
        });
        const parsed = Array.from(byRound.values());

        if (parsed.length === 0) return null;

        parsed.sort((a, b) => a.roundNum - b.roundNum); // FIFO: oldest first
        const oldest = parsed[0];
        const newest = parsed[parsed.length - 1];
        const roundDelta = newest.roundNum - oldest.roundNum;
        const total = parsed.reduce((s, r) => s + r.amount, 0);

        return {
            queue: parsed,
            size: parsed.length,
            oldest,
            newest,
            roundDelta,
            total,
            atCapacity: parsed.length >= TROPHY_MAX_QUEUE_ROUNDS,
            oldestExpiresTonight: roundDelta >= TROPHY_EXPIRY_ROUND_DELTA,
            // If the round gap ever exceeds the expiry window, our last-seen
            // snapshot is stale (the oldest round should already be gone
            // server-side) — flag it so the UI prompts a refresh instead of
            // quietly trusting outdated data.
            possiblyStale: roundDelta > TROPHY_EXPIRY_ROUND_DELTA
        };
    }

    // Builds the exact required warning copy for the oldest queued round.
    function buildExpiryWarning(queueInfo) {
        if (!queueInfo || !queueInfo.oldestExpiresTonight) return null;
        const { oldest, size } = queueInfo;
        return `WARNING: Your winnings from Round ${oldest.round} will expire tonight at Midnight NST. You are currently holding ${size} round${size === 1 ? '' : 's'} of winnings. You must collect your total balance before midnight, or Round ${oldest.round}'s data will be permanently deleted.`;
    }


    // ─────────────────────────────────────────────────────────────────────────
    // FETCH HELPERS
    // ─────────────────────────────────────────────────────────────────────────
    async function fetchFC(type) {
        const res = await fetch(`/pirates/foodclub.phtml?type=${type}`, { credentials: 'include' });
        const html = await res.text();
        return { doc: new DOMParser().parseFromString(html, 'text/html'), raw: html };
    }

    // ─────────────────────────────────────────────────────────────────────────
    // SCRAPERS
    // ─────────────────────────────────────────────────────────────────────────
    function scrapePirates(doc) {
        const pirates = [];
        const rows = doc.querySelectorAll("tr");
        rows.forEach(row => {
            const cells = row.querySelectorAll('td');
            if (cells.length < 6) return;
            const link = cells[0].querySelector('a');
            if (!link) return;
            const href = link.getAttribute('href') || '';
            const idMatch = href.match(/id=(\d+)/);
            if (!idMatch) return;
            pirates.push({
                id: parseInt(idMatch[1]),
                name: link.textContent.trim(),
                strength: parseInt(cells[1].textContent) || 0,
                weight: parseInt(cells[2].textContent) || 0,
                wins: parseInt(cells[3].textContent.replace(/,/g, '')) || 0,
                losses: parseInt(cells[4].textContent.replace(/,/g, '')) || 0,
                pct: parseInt(cells[5].textContent) || 0,
            });
        });
        return pirates;
    }
    function scrapeBetForm(doc) {
        const raw = doc.documentElement.innerHTML;

        // 1. Scrape Max Bet Amount safely from the text string or JS fallback
        let maxBet = 0;
        const textMatch = raw.match(/up to <b>(\d+)<\/b> NeoPoints/i);
        const jsMatch = raw.match(/max_bet\s*=\s*(\d+)/i);

        if (textMatch) {
            maxBet = parseInt(textMatch[1], 10);
        } else if (jsMatch) {
            maxBet = parseInt(jsMatch[1], 10);
        }

        // 2. Scrape Pirate Odds
        const oddsMap = {};
        const oddsRe = /pirate_odds\[(\d+)\]\s*=\s*(\d+)/g;
        let m;
        while ((m = oddsRe.exec(raw)) !== null) {
            oddsMap[parseInt(m[1], 10)] = parseInt(m[2], 10);
        }

        // 3. Map Arenas and Pirates
        const arenas = [];
        const betTable = doc.querySelector("form[name='bet_form'] table");
        if (!betTable) return { maxBet, arenas };

        const rows = betTable.querySelectorAll('tr');
        rows.forEach(row => {
            const cbInput = row.querySelector('input[type="checkbox"][name="matches[]"]');
            if (!cbInput) return;
            const arenaIndex = parseInt(cbInput.value, 10) - 1;
            const arenaName = ARENAS[arenaIndex] || `Arena ${arenaIndex + 1}`;
            const select = row.querySelector('select');
            if (!select) return;

            const pirates = [];
            select.querySelectorAll('option').forEach(opt => {
                if (!opt.value) return;
                const id = parseInt(opt.value, 10);
                const oddsVal = oddsMap[id] || 1;
                const txt = opt.textContent.trim();
                const nameMatch = txt.match(/^(.+?)\s+\(/);
                const name = nameMatch ? nameMatch[1].trim() : txt;
                pirates.push({ id, name, odds: oddsVal });
            });

            arenas.push({ name: arenaName, arenaIndex, pirates });
        });

        return { maxBet, arenas };
    }


    function scrapeCurrentBets(doc) {
        const bets = [];
        const rows = doc.querySelectorAll("tr");
        let dataRows = 0;
        rows.forEach(row => {
            const cells = row.querySelectorAll('td');
            if (cells.length === 5 && cells[0].textContent.trim() !== 'Round' && cells[0].textContent.trim() !== '') {
                const betInfo = cells[1].innerHTML.trim();
                const amount = cells[2].textContent.trim();
                const odds = cells[3].textContent.trim();
                const winnings = cells[4].textContent.trim();
                bets.push({ betInfo, amount, odds, winnings });
                dataRows++;
            }
        });

        if (dataRows === 0) {
            const emptyCell = doc.querySelector("td[colspan='5']");
            if (emptyCell && emptyCell.textContent.includes('You do not have any bets placed')) return null;
        }

        return bets;
    }

    // Keeps the Home page's Quickview "Food Club Bets" widget fresh: any
    // time the My Bets tab is actually loaded on this page, mirror the
    // totals into the same cache key the homepage reads on load, so the
    // widget doesn't need its own background fetch to catch up.
    function cacheQuickviewFoodClub(bets) {
        try {
            const toNum = s => parseInt(String(s).replace(/[^0-9]/g, ''), 10) || 0;
            let valueHtml, sub;
            if (!bets || !bets.length) {
                valueHtml = `<span style="color:var(--nui-text-muted);font-size:12px;">No bets</span>`;
                sub = 'No bets placed this round';
            } else {
                const totalBet = bets.reduce((s, b) => s + toNum(b.amount), 0);
                const totalWin = bets.reduce((s, b) => s + toNum(b.winnings), 0);
                const fmt = n => n.toLocaleString();
                valueHtml = `${fmt(totalWin)} NP<br><span style="font-size:11px;color:var(--nui-text-muted);">potential</span>`;
                sub = `${bets.length} bet${bets.length === 1 ? '' : 's'} · ${fmt(totalBet)} NP wagered`;
            }
            localStorage.setItem('nui_qv_fc_cache', JSON.stringify({ valueHtml, sub, ts: Date.now() }));
        } catch (e) {}
    }

    function scrapeCollect(doc) {
        const formAction = 'process_foodclub.phtml';
        const rows = [];
        const trs = doc.querySelectorAll("tr");
        trs.forEach(row => {
            const cells = row.querySelectorAll('td');
            if (cells.length === 5 && cells[0].textContent.trim() !== 'Round' && cells[0].textContent.trim() !== '') {
                rows.push({
                    round: cells[0].textContent.trim(),
                    betInfo: cells[1].innerHTML.trim(),
                    amount: cells[2].textContent.trim(),
                    odds: cells[3].textContent.trim(),
                    winnings: cells[4].textContent.trim(),
                });
            }
        });

        let emptyCheck = false;
        trs.forEach(row => {
            const td = row.querySelector("td[colspan='5']");
            if (td && td.textContent.includes("You do not have any winning bets")) emptyCheck = true;
        });

        const hasWinnings = rows.length > 0 && !emptyCheck;
        return { hasWinnings, rows, formAction };
    }

    function scrapeHistory(doc) {
        const tables = doc.querySelectorAll('table');
        let historyData = null;
        tables.forEach(table => {
            if (table.textContent.includes('Bets Placed') && table.textContent.includes('Bet Total')) {
                const rows = table.querySelectorAll('tr');
                if (rows.length >= 3) {
                    const cells = rows[2].querySelectorAll('td');
                    if (cells.length >= 4) {
                        historyData = {
                            betsPlaced: cells[0].textContent.trim(),
                            betTotal: cells[1].textContent.trim(),
                            winTotal: cells[2].textContent.trim(),
                            differenceHtml: cells[3].innerHTML.trim()
                        };
                    }
                }
            }
        });
        return historyData;
    }

    // ─────────────────────────────────────────────────────────────────────────
    // POST A SINGLE BET
    // ─────────────────────────────────────────────────────────────────────────
    async function postBet(row, amount) {
        const fd = new FormData();
        fd.append('type', 'bet');
        fd.append('bet_amount', String(amount));

        row.forEach((pid, arenaIdx) => {
            if (!pid) return;
            fd.append('matches[]', String(arenaIdx + 1));
            fd.append(`winner${arenaIdx + 1}`, String(pid));
        });

        const res = await fetch('/pirates/process_foodclub.phtml', {
            method: 'POST',
            credentials: 'include',
            body: fd,
        });
        const html = await res.text();
        const doc = new DOMParser().parseFromString(html, 'text/html');

        // SUCCESS SIGNAL: a successful bet redirects to the current-bets page.
        // That page contains bet rows (tr with 5 td cells, first cell ≠ 'Round').
        // We look for that positive signal rather than scanning for error keywords,
        // which was triggering on incidental text in the current-bets tables.
        const rows = doc.querySelectorAll('tr');
        let hasBetRows = false;
        rows.forEach(row => {
            const cells = row.querySelectorAll('td');
            if (cells.length === 5 && cells[0].textContent.trim() !== 'Round' && cells[0].textContent.trim() !== '') {
                hasBetRows = true;
            }
        });
        if (hasBetRows) return { ok: true, message: 'Bet placed!' };

        // Also accept an empty current-bets page (no bets yet placed this round
        // but no error either — e.g. first bet in a fresh round clears after redirect)
        const emptyBets = doc.querySelector("td[colspan='5']");
        if (emptyBets && emptyBets.textContent.includes('You do not have any bets')) {
            return { ok: true, message: 'Bet placed!' };
        }

        // Explicit error elements from Neopets
        const errorEl = doc.querySelector('.errorMessage, #errorMessage, .error_msg, p.error, .neopets-error');
        if (errorEl) {
            return { ok: false, message: errorEl.textContent.replace(/\s+/g, ' ').trim().slice(0, 200) };
        }

        // Fallback: if we can't read a positive signal, assume success (the bet
        // went through and process_foodclub redirected us somewhere unexpected).
        return { ok: true, message: 'Bet placed!' };
    }

    // ─────────────────────────────────────────────────────────────────────────
    // INIT
    // ─────────────────────────────────────────────────────────────────────────
    async function init() {
        const profile = NeoUI.scrapeLegacyProfile();

        const nextMatchEl = document.querySelector('center');
        const nextMatchText = nextMatchEl ? nextMatchEl.textContent.trim() : '';

        document.body.innerHTML = '';
        document.body.className = 'nui-reset';
        document.documentElement.style.background = 'var(--nui-bg)';
        document.body.style.background = 'var(--nui-bg)';

        NeoUI.init();
        NeoUI.setProfileInfo(profile);
        NeoUI.buildTopbar({ stats: { np: profile.np, nc: profile.nc }, hasNotification: profile.hasNotification });

        const wrapper = document.createElement('div');
        wrapper.className = 'nui-reset';
        wrapper.style.cssText = 'padding: calc(var(--nui-topbar-h) + var(--nui-space-4)) var(--nui-space-4) var(--nui-space-5); max-width: 760px; margin: 0 auto; display: flex; flex-direction: column; gap: var(--nui-space-4);';

        // Banner card
        const bannerCard = document.createElement('div');
        bannerCard.className = 'nui-surface';
        bannerCard.style.cssText = 'border-radius:var(--nui-radius-lg);border:1px solid var(--nui-border);overflow:hidden;box-shadow:0 4px 12px var(--nui-shadow);position:relative;';
        bannerCard.innerHTML = `
            <div style="position:relative;width:100%;height:120px;overflow:hidden;background:linear-gradient(135deg,#2B1A0A 0%,#4A2E12 50%,#2B1A0A 100%);">
                <img src="//images.neopets.com/pirates/fc/foodclub_bg.gif"
                     style="position:absolute;inset:0;width:100%;height:100%;object-fit:cover;opacity:0.45;"
                     onerror="this.style.display='none'">
                <div style="position:absolute;inset:0;display:flex;align-items:center;gap:14px;padding:0 var(--nui-space-4);">
                    <img src="//images.neopets.com/pirates/fc/bookie.gif"
                         style="width:72px;height:72px;border-radius:var(--nui-radius-md);border:2px solid rgba(255,255,255,0.25);object-fit:cover;flex-shrink:0;filter:drop-shadow(0 4px 8px rgba(0,0,0,0.6));"
                         onerror="this.style.display='none'">
                    <div>
                        <div style="font-family:var(--nui-font-display);font-weight:800;font-size:28px;color:#FFD060;text-shadow:0 2px 8px rgba(0,0,0,0.6);line-height:1.1;">Food Club</div>
                        <div id="nui-fc-next" style="font-size:13px;color:rgba(255,220,120,0.9);font-weight:600;margin-top:3px;text-shadow:0 1px 3px rgba(0,0,0,0.5);">${nextMatchText}</div>
                    </div>
                </div>
            </div>
        `;
        wrapper.appendChild(bannerCard);

        const tabBar = document.createElement('div');
        tabBar.style.cssText = 'display:flex;gap:6px;border-bottom:2px solid var(--nui-border);padding-bottom:0;overflow-x:auto;scrollbar-width:none;';

        const TABS = [
            { id: 'pirates',  label: '🏴‍☠️ Pirates'  },
            { id: 'bet',      label: '🎰 Place Bet'  },
            { id: 'mybets',   label: '📋 My Bets'    },
            { id: 'collect',  label: '💰 Collect'    },
            { id: 'history',  label: '📜 History'    },
        ];

        const urlType = new URLSearchParams(location.search).get('type') || '';
        const startTab = urlType === 'current_bets' ? 'mybets'
                       : urlType === 'collect'       ? 'collect'
                       : urlType === 'bet'           ? 'bet'
                       : urlType === 'history'       ? 'history'
                       : 'pirates';

        let activeTab = startTab;
        const tabEls = {};

        TABS.forEach(t => {
            const btn = document.createElement('button');
            btn.type = 'button';
            btn.textContent = t.label;
            btn.style.cssText = 'padding:8px 14px;border:none;cursor:pointer;font-weight:700;font-size:13px;border-radius:var(--nui-radius-sm) var(--nui-radius-sm) 0 0;background:transparent;color:var(--nui-text-muted);border-bottom:3px solid transparent;margin-bottom:-2px;transition:all 0.15s;white-space:nowrap;flex-shrink:0;';
            tabEls[t.id] = btn;
            tabBar.appendChild(btn);
        });
        wrapper.appendChild(tabBar);

        const contentPanel = document.createElement('div');
        contentPanel.className = 'nui-surface';
        contentPanel.style.cssText = 'border-radius:var(--nui-radius-lg);overflow:hidden;min-height:200px;box-shadow:0 4px 12px var(--nui-shadow);border:1px solid var(--nui-border);';

        const contentInner = document.createElement('div');
        contentInner.style.cssText = 'padding:var(--nui-space-4);';
        contentPanel.appendChild(contentInner);
        wrapper.appendChild(contentPanel);

        document.body.appendChild(wrapper);

        function showToast(msg, isError) {
            const toast = document.createElement('div');
            toast.style.cssText = `position:fixed;bottom:80px;left:50%;transform:translateX(-50%);z-index:99999;padding:10px 18px;border-radius:var(--nui-radius-md);font-size:14px;font-weight:700;max-width:90vw;text-align:center;box-shadow:0 4px 16px var(--nui-shadow);background:${isError ? 'var(--nui-danger)' : 'var(--nui-success)'};color:#fff;transition:opacity 0.3s;`;
            toast.textContent = msg;
            document.body.appendChild(toast);
            setTimeout(() => { toast.style.opacity = '0'; setTimeout(() => toast.remove(), 300); }, 3500);
        }

        async function switchTab(id, extraState) {
            activeTab = id;
            Object.entries(tabEls).forEach(([tid, btn]) => {
                const on = tid === id;
                btn.style.color = on ? 'var(--nui-accent)' : 'var(--nui-text-muted)';
                btn.style.borderBottomColor = on ? 'var(--nui-accent)' : 'transparent';
                btn.style.background = on ? 'var(--nui-surface-2)' : 'transparent';
            });
            contentInner.innerHTML = '<div style="text-align:center;padding:40px;color:var(--nui-text-faint);">Loading...</div>';
            try {
                if      (id === 'pirates') await renderPirates();
                else if (id === 'bet')     await renderBet(extraState);
                else if (id === 'mybets')  await renderMyBets();
                else if (id === 'collect') await renderCollect();
                else if (id === 'history') await renderHistory();
            } catch (err) {
                contentInner.innerHTML = `<div style="color:var(--nui-danger);font-weight:600;text-align:center;padding:var(--nui-space-4);">Failed to load: ${err.message}</div>`;
            }
        }

        TABS.forEach(t => { tabEls[t.id].addEventListener('click', () => switchTab(t.id)); });

        // ─────────────────────────────────────────────────────────────────────
        // RENDER: PIRATES TAB
        // ─────────────────────────────────────────────────────────────────────
        async function renderPirates() {
            const { doc } = await fetchFC('pirates');
            const pirates = scrapePirates(doc);

            contentInner.innerHTML = '';

            if (!pirates.length) {
                contentInner.innerHTML = '<div class="nui-empty"><span class="nui-empty-emoji">🏴‍☠️</span>No pirate data found.</div>';
                return;
            }

            let sortKey = 'pct';
            let sortDir = -1;

            function renderTable() {
                contentInner.innerHTML = '';

                const sorted = [...pirates].sort((a, b) => {
                    const av = a[sortKey], bv = b[sortKey];
                    return typeof av === 'number' ? (bv - av) * sortDir : sortDir * String(av).localeCompare(String(bv));
                });

                const sortRow = document.createElement('div');
                sortRow.style.cssText = 'display:flex;gap:6px;flex-wrap:wrap;margin-bottom:var(--nui-space-3);align-items:center;';
                sortRow.innerHTML = '<span style="font-size:12px;font-weight:800;color:var(--nui-text-faint);text-transform:uppercase;">Sort by</span>';

                [['name','Name'],['pct','Win%'],['wins','Wins'],['strength','Str'],['weight','Wt']].forEach(([key, label]) => {
                    const btn = document.createElement('button');
                    btn.type = 'button';
                    btn.style.cssText = `padding:4px 10px;border-radius:var(--nui-radius-pill);border:1px solid var(--nui-border);font-size:12px;font-weight:700;cursor:pointer;transition:all 0.1s;background:${sortKey===key?'var(--nui-accent-soft)':'var(--nui-surface-2)'};color:${sortKey===key?'var(--nui-accent)':'var(--nui-text-muted)'};`;
                    btn.textContent = label + (sortKey === key ? (sortDir === -1 ? ' ↓' : ' ↑') : '');
                    btn.addEventListener('click', () => {
                        if (sortKey === key) sortDir *= -1;
                        else { sortKey = key; sortDir = -1; }
                        renderTable();
                    });
                    sortRow.appendChild(btn);
                });
                contentInner.appendChild(sortRow);

                const grid = document.createElement('div');
                grid.style.cssText = 'display:flex;flex-direction:column;gap:var(--nui-space-2);';

                sorted.forEach(p => {
                    const card = document.createElement('div');
                    card.style.cssText = 'border:1px solid var(--nui-border);border-radius:var(--nui-radius-md);padding:10px 14px;background:var(--nui-surface-2);display:grid;grid-template-columns:1fr auto;gap:8px;align-items:center;';

                    const total = p.wins + p.losses;
                    const barW = total > 0 ? Math.round((p.wins / total) * 100) : 0;
                    const barColor = p.pct >= 50 ? 'var(--nui-success)' : p.pct >= 25 ? 'var(--nui-warning)' : 'var(--nui-danger)';

                    card.innerHTML = `
                        <div style="min-width:0;">
                            <div style="font-weight:800;font-size:15px;color:var(--nui-text);overflow:hidden;text-overflow:ellipsis;white-space:nowrap;">
                                <a href="/pirates/foodclub.phtml?type=pirates&id=${p.id}" style="color:var(--nui-accent);text-decoration:none;">${p.name}</a>
                            </div>
                            <div style="font-size:12px;color:var(--nui-text-muted);font-weight:600;margin-top:3px;">
                                Str <b style="color:var(--nui-text);">${p.strength}</b> &nbsp;·&nbsp;
                                Wt <b style="color:var(--nui-text);">${p.weight}</b> &nbsp;·&nbsp;
                                ${p.wins.toLocaleString()} W / ${p.losses.toLocaleString()} L
                            </div>
                            <div style="margin-top:6px;height:5px;background:var(--nui-surface);border-radius:3px;overflow:hidden;">
                                <div style="height:100%;width:${barW}%;background:${barColor};border-radius:3px;transition:width 0.3s;"></div>
                            </div>
                        </div>
                        <div style="text-align:center;flex-shrink:0;">
                            <div style="font-family:var(--nui-font-display);font-size:22px;font-weight:800;color:${barColor};">${p.pct}%</div>
                            <div style="font-size:10px;font-weight:700;color:var(--nui-text-faint);text-transform:uppercase;">Win Rate</div>
                        </div>
                    `;

                    grid.appendChild(card);
                });

                contentInner.appendChild(grid);
            }

            renderTable();
        }

        // ─────────────────────────────────────────────────────────────────────
        // RENDER: BET TAB (WITH MULTIPLE BET QUEUE AND CAPPING)
        // ─────────────────────────────────────────────────────────────────────
        async function renderBet(extraState) {
            const { doc } = await fetchFC('bet');
            const { maxBet, arenas } = scrapeBetForm(doc);
            const globalOddsMap = {};
            arenas.forEach(a => a.pirates.forEach(p => { globalOddsMap[p.id] = p.odds; }));

            contentInner.innerHTML = '';

            if (!arenas.length) {
                contentInner.innerHTML = `<div class="nui-empty"><span class="nui-empty-emoji">🎰</span>Betting is not currently available.</div>`;
                return;
            }

            // --- Top Importer Row (Always visible) ---
            const importRow = document.createElement('div');
            importRow.style.cssText = 'display:flex;gap:8px;margin-bottom:var(--nui-space-4);align-items:flex-start;flex-wrap:wrap;';
            importRow.innerHTML = `
                <div style="flex:1;min-width:180px;">
                    <div style="font-size:11px;font-weight:800;text-transform:uppercase;color:var(--nui-text-faint);letter-spacing:0.5px;margin-bottom:4px;">NeoFoodClub Import</div>
                    <input class="nui-input" id="nui-fc-nfc-input" type="text" placeholder="Paste NFC URL or bet string…" style="font-size:13px;padding:9px 12px;">
                </div>
                <button type="button" class="nui-btn nui-btn-secondary nui-btn-sm" id="nui-fc-nfc-btn" style="align-self:flex-end;white-space:nowrap;">Load Bets</button>
            `;
            contentInner.appendChild(importRow);

            // Container for shifting between Queue View and Single View
            const viewContainer = document.createElement('div');
            contentInner.appendChild(viewContainer);

            // Import Button Listener
            importRow.querySelector('#nui-fc-nfc-btn').addEventListener('click', () => {
                const val = importRow.querySelector('#nui-fc-nfc-input').value.trim();
                if (!val) { showToast('Paste an NFC URL or bet string first.', true); return; }

                const hashIdx = val.indexOf('#');
                const fragment = hashIdx !== -1 ? val.slice(hashIdx + 1) : val;
                const params = new URLSearchParams(fragment);

                let parsedBets = [];
                let parsedAmounts = [];

                if (params.has('b')) {
                    const alphabet = "abcdefghijklmnopqrstuvwxy";
                    const nums = params.get('b').replace(/[^a-y]/g, "").split("").map(c => alphabet.indexOf(c));

                    const flat = [];
                    for (let i = 0; i < nums.length; i++) {
                        flat.push(Math.floor(nums[i] / 5));
                        flat.push(nums[i] % 5);
                    }

                    const betArrays = [];
                    for (let i = 0; i < flat.length; i += 5) {
                        const chunk = flat.slice(i, i + 5);
                        if (chunk.length === 5) betArrays.push(chunk);
                    }

                    parsedBets = betArrays.map(betRow => {
                        const arenaSelections = [null, null, null, null, null];
                        betRow.forEach((pirateIdx, arenaIdx) => {
                            if (pirateIdx === 0) return;
                            const arena = arenas[arenaIdx];
                            if (arena && arena.pirates[pirateIdx - 1]) {
                                arenaSelections[arenaIdx] = arena.pirates[pirateIdx - 1].id;
                            }
                        });
                        return arenaSelections;
                    });
                }

                if (params.has('a')) {
                    const aStr = params.get('a');
                    const alphabet = "abcdefghijklmnopqrstuvwxyzABCDEFGHIJKLMNOPQRSTUVWXYZ";
                    const chunks = aStr.replace(/[^a-zA-Z]/g, "").match(/.{1,3}/g) || [];
                    parsedAmounts = chunks.map(chunk => {
                        let v = 0;
                        for (let i = 0; i < chunk.length; i++) {
                            v *= 52;
                            v += alphabet.indexOf(chunk[i]);
                        }
                        return v - 70304;
                    });
                }

                if (!parsedBets || !parsedBets.length) {
                    showToast('Could not parse NFC string. Make sure it contains a b= parameter.', true);
                    return;
                }

                // Map into Queue Format
                const betQueue = parsedBets.map((arenaSelections, i) => {
                    let amt = null;
                    if (parsedAmounts && parsedAmounts[i]) {
                        amt = parsedAmounts[i];
                    } else if (parsedAmounts && parsedAmounts.length > 0) {
                        amt = parsedAmounts[0];
                    }
                    return { arenaSelections, amount: amt };
                });

                showToast(`Loaded ${betQueue.length} bet(s).`, false);
                switchTab('bet', { betQueue });
            });


            // --- QUEUE VIEW (If array of bets is passed) ---
            if (extraState && extraState.betQueue) {
                // Local editable working copy — lets the user tweak picks and
                // amounts before placing, without mutating the parsed import.
                let workingQueue = extraState.betQueue.map(bet => ({
                    arenaSelections: bet.arenaSelections.slice(),
                    amount: bet.amount
                }));

                function computeCap(bet) {
                    let totalOdds = 1;
                    let hasPirate = false;
                    bet.arenaSelections.forEach(pid => {
                        if (pid) { hasPirate = true; totalOdds *= (globalOddsMap[pid] || 1); }
                    });
                    if (!hasPirate) totalOdds = 0;
                    // The site's real ceiling on a bet is just the per-bet max
                    // (maxBet) — it accepts bets whose potential payout exceeds
                    // the 1,000,000 NP winnings cap and simply pays out no more
                    // than MAX_WIN if the bet hits. So `cap` here tracks the
                    // actual placeable amount, not a payout-derived amount.
                    const cap = maxBet;
                    return { totalOdds, cap };
                }

                // Clamps bet.amount into the legal [50, cap] range and reports
                // whether the value the caller was holding got adjusted, so the
                // UI can say *why* a typed amount changed instead of silently
                // snapping it — that silent snap is what made amounts feel
                // uneditable when betting near a bet's payout cap.
                function clampAmount(bet) {
                    const { totalOdds, cap } = computeCap(bet);
                    const ceiling = totalOdds > 0 ? cap : maxBet;
                    const raw = (bet.amount != null && !isNaN(bet.amount)) ? bet.amount : ceiling;
                    const finalAmt = Math.max(50, Math.min(raw, ceiling));
                    const wasClamped = finalAmt !== raw;
                    bet.amount = finalAmt;
                    return { totalOdds, cap, finalAmt, payout: totalOdds * finalAmt, wasClamped };
                }

                function computeQueueRow(bet) {
                    return clampAmount(bet);
                }

                function renderQueueView() {
                    viewContainer.innerHTML = '';

                    if (workingQueue.length === 0) {
                        viewContainer.insertAdjacentHTML('beforeend', `<div class="nui-empty"><span class="nui-empty-emoji">🗑️</span>All bets removed from the queue.</div>`);
                        const backBtnEmpty = document.createElement('button');
                        backBtnEmpty.className = 'nui-btn nui-btn-secondary nui-btn-block';
                        backBtnEmpty.textContent = 'Back to Single Bet';
                        backBtnEmpty.style.marginTop = '8px';
                        backBtnEmpty.addEventListener('click', () => switchTab('bet'));
                        viewContainer.appendChild(backBtnEmpty);
                        return;
                    }

                    const queueCard = document.createElement('div');
                    queueCard.style.cssText = 'display:flex;flex-direction:column;gap:8px;';

                    // ── Bulk "Set All" amount control ──────────────────────────────
                    // Imported NFC strings often carry one strategy-wide amount;
                    // editing 10 rows one at a time to override it was the main
                    // friction point, so this applies one value to every row at
                    // once (each row still gets clamped to its own payout cap).
                    const bulkRow = document.createElement('div');
                    bulkRow.style.cssText = 'display:flex;gap:8px;align-items:center;flex-wrap:wrap;padding:8px 10px;background:var(--nui-surface-2);border:1px solid var(--nui-border);border-radius:var(--nui-radius-sm);';
                    bulkRow.innerHTML = `
                        <span style="font-size:11px;font-weight:800;color:var(--nui-text-muted);white-space:nowrap;">Set all amounts:</span>
                        <input class="nui-input" id="nui-fc-bulk-amt" type="number" min="50" placeholder="NP" style="width:100px;font-size:12px;padding:5px 8px;">
                        <button type="button" class="nui-btn nui-btn-secondary" id="nui-fc-bulk-apply" style="font-size:11px;padding:5px 10px;">Apply to All</button>
                        <button type="button" class="nui-btn nui-btn-secondary" id="nui-fc-bulk-max" style="font-size:11px;padding:5px 10px;">Max Every Bet</button>
                    `;
                    queueCard.appendChild(bulkRow);
                    bulkRow.querySelector('#nui-fc-bulk-apply').addEventListener('click', () => {
                        const v = parseInt(bulkRow.querySelector('#nui-fc-bulk-amt').value, 10);
                        if (isNaN(v)) { showToast('Enter an amount first.', true); return; }
                        workingQueue.forEach(bet => { bet.amount = v; });
                        renderQueueView();
                    });
                    bulkRow.querySelector('#nui-fc-bulk-max').addEventListener('click', () => {
                        workingQueue.forEach(bet => { bet.amount = computeCap(bet).cap; });
                        renderQueueView();
                    });

                    const table = document.createElement('div');
                    table.style.cssText = 'display:flex;flex-direction:column;gap:6px;';

                    let totalCost = 0;
                    const rowRefs = []; // { payoutSpan, capNote, cap, totalOdds, finalAmt }

                    workingQueue.forEach((bet, i) => {
                        const { totalOdds, finalAmt, cap, payout, wasClamped } = computeQueueRow(bet);
                        totalCost += finalAmt;

                        const row = document.createElement('div');
                        row.className = 'nui-surface-2';
                        row.style.cssText = 'border:1px solid var(--nui-border);border-radius:var(--nui-radius-sm);padding:8px 10px;display:flex;flex-direction:column;gap:6px;';

                        // Per-arena pirate pickers — lets the user change who this bet is on.
                        const pickersRow = document.createElement('div');
                        pickersRow.style.cssText = 'display:flex;gap:4px;flex-wrap:wrap;';
                        arenas.forEach((arena, aIdx) => {
                            const sel = document.createElement('select');
                            sel.className = 'nui-input';
                            sel.style.cssText = 'font-size:11px;padding:4px 6px;flex:1;min-width:88px;';
                            sel.title = arena.name;

                            const noneOpt = document.createElement('option');
                            noneOpt.value = '';
                            noneOpt.textContent = arena.name + ' — none';
                            sel.appendChild(noneOpt);

                            arena.pirates.forEach(p => {
                                const opt = document.createElement('option');
                                opt.value = String(p.id);
                                opt.textContent = `${p.name} (${p.odds}:1)`;
                                if (bet.arenaSelections[aIdx] === p.id) opt.selected = true;
                                sel.appendChild(opt);
                            });

                            sel.addEventListener('change', () => {
                                bet.arenaSelections[aIdx] = sel.value ? parseInt(sel.value, 10) : null;
                                renderQueueView();
                            });

                            pickersRow.appendChild(sel);
                        });

                        // Odds / editable amount / payout / status / remove
                        const statsRow = document.createElement('div');
                        statsRow.style.cssText = 'display:flex;gap:8px;align-items:center;justify-content:flex-end;flex-wrap:wrap;';

                        const oddsLabel = document.createElement('div');
                        oddsLabel.style.cssText = 'font-size:11px;font-weight:700;color:var(--nui-text-muted);margin-right:auto;';
                        oddsLabel.textContent = totalOdds > 0 ? `${totalOdds}:1` : 'No picks — will be skipped';
                        statsRow.appendChild(oddsLabel);

                        const amtInput = document.createElement('input');
                        amtInput.type = 'number';
                        amtInput.className = 'nui-input';
                        amtInput.min = '50';
                        amtInput.value = String(finalAmt);
                        amtInput.title = `Min 50, max ${cap.toLocaleString()} (account bet cap)`;
                        amtInput.style.cssText = 'width:80px;font-size:12px;padding:5px 8px;';
                        amtInput.disabled = totalOdds === 0;

                        // Live-updates the payout preview and running total as the
                        // user types — without rebuilding the DOM, so the field
                        // never loses focus mid-edit (a full re-render on every
                        // keystroke was effectively eating typed digits).
                        amtInput.addEventListener('input', () => {
                            const raw = parseInt(amtInput.value, 10);
                            const previewAmt = isNaN(raw) ? 0 : Math.min(Math.max(raw, 0), totalOdds > 0 ? cap : maxBet);
                            payoutSpan.textContent = (totalOdds * previewAmt).toLocaleString();
                            const overCap = !isNaN(raw) && raw > (totalOdds > 0 ? cap : maxBet);
                            capNote.style.display = overCap ? 'block' : 'none';
                            if (overCap) capNote.textContent = `Will be capped at ${cap.toLocaleString()} NP on save (account bet max)`;
                            const overPayoutCap = totalOdds > 0 && !isNaN(raw) && (totalOdds * Math.min(Math.max(raw, 0), cap)) > MAX_WIN;
                            if (overPayoutCap) {
                                payoutCapNote.style.display = 'block';
                                payoutCapNote.textContent = `Payout will be capped at ${MAX_WIN.toLocaleString()} NP if this bet hits — the bet itself is not reduced.`;
                            } else {
                                payoutCapNote.style.display = 'none';
                            }
                            bet.amount = isNaN(raw) ? null : raw; // raw, unclamped — clamp happens on blur
                        });

                        // Commit + clamp once the user is done editing, then fully
                        // resync so every derived number (totals, other rows if a
                        // bulk action changed odds elsewhere) stays consistent.
                        amtInput.addEventListener('blur', () => {
                            const { wasClamped: clampedNow, finalAmt: settled } = clampAmount(bet);
                            if (clampedNow) showToast(`Amount adjusted to ${settled.toLocaleString()} NP (account bet max).`, false);
                            renderQueueView();
                        });
                        amtInput.addEventListener('keydown', (e) => { if (e.key === 'Enter') amtInput.blur(); });
                        statsRow.appendChild(amtInput);

                        const maxRowBtn = document.createElement('button');
                        maxRowBtn.type = 'button';
                        maxRowBtn.className = 'nui-btn nui-btn-secondary';
                        maxRowBtn.textContent = 'Max';
                        maxRowBtn.title = 'Set to this bet\'s payout cap';
                        maxRowBtn.style.cssText = 'flex-shrink:0;font-size:11px;padding:4px 8px;';
                        maxRowBtn.disabled = totalOdds === 0;
                        maxRowBtn.addEventListener('click', () => {
                            bet.amount = cap;
                            renderQueueView();
                        });
                        statsRow.appendChild(maxRowBtn);

                        const payoutSpan = document.createElement('div');
                        payoutSpan.style.cssText = 'width:75px;font-size:12px;font-weight:800;color:var(--nui-success);text-align:right;';
                        payoutSpan.textContent = payout.toLocaleString();
                        statsRow.appendChild(payoutSpan);

                        const statusSpan = document.createElement('div');
                        statusSpan.id = `q-status-${i}`;
                        statusSpan.style.cssText = 'width:52px;font-size:11px;color:var(--nui-text-faint);text-align:center;';
                        statusSpan.textContent = 'Ready';
                        statsRow.appendChild(statusSpan);

                        const removeBtn = document.createElement('button');
                        removeBtn.type = 'button';
                        removeBtn.className = 'nui-btn nui-btn-secondary';
                        removeBtn.textContent = '✕';
                        removeBtn.title = 'Remove this bet from the queue';
                        removeBtn.style.cssText = 'flex-shrink:0;font-size:11px;padding:4px 8px;';
                        removeBtn.addEventListener('click', () => {
                            workingQueue.splice(i, 1);
                            renderQueueView();
                        });
                        statsRow.appendChild(removeBtn);

                        const capNote = document.createElement('div');
                        capNote.style.cssText = 'display:none;font-size:10px;font-weight:700;color:var(--nui-warning,#f5a623);text-align:right;';
                        if (wasClamped) { capNote.style.display = 'block'; capNote.textContent = `Adjusted to ${finalAmt.toLocaleString()} NP (account bet max).`; }

                        // Informational only — this bet is still placed in
                        // full; Neopets itself is what caps the eventual
                        // payout at MAX_WIN, not this script.
                        const payoutCapNote = document.createElement('div');
                        const overPayoutCapInitial = totalOdds > 0 && (totalOdds * finalAmt) > MAX_WIN;
                        payoutCapNote.style.cssText = `display:${overPayoutCapInitial ? 'block' : 'none'};font-size:10px;font-weight:700;color:var(--nui-text-faint);text-align:right;`;
                        if (overPayoutCapInitial) payoutCapNote.textContent = `Payout will be capped at ${MAX_WIN.toLocaleString()} NP if this bet hits — the bet itself is not reduced.`;

                        row.appendChild(pickersRow);
                        row.appendChild(statsRow);
                        row.appendChild(capNote);
                        row.appendChild(payoutCapNote);
                        table.appendChild(row);
                        rowRefs.push({ bet, cap, totalOdds });
                    });

                    const summary = document.createElement('div');
                    summary.style.cssText = 'padding:12px;background:var(--nui-surface-2);border-radius:var(--nui-radius-md);margin-bottom:8px;font-weight:800;display:flex;justify-content:space-between;flex-wrap:wrap;gap:6px;border:1px solid var(--nui-border);';
                    summary.innerHTML = `
                        <span style="color:var(--nui-text-muted);">Bets: <b style="color:var(--nui-text);">${workingQueue.length}</b></span>
                        <span style="color:var(--nui-text-muted);">Max Bet: <b style="color:var(--nui-accent);">${maxBet.toLocaleString()} NP</b></span>
                        <span style="color:var(--nui-text-muted);">Total Cost: <b style="color:var(--nui-danger);">${totalCost.toLocaleString()} NP</b></span>
                    `;

                    const placeBtn = document.createElement('button');
                    placeBtn.className = 'nui-btn nui-btn-primary nui-btn-block';
                    placeBtn.textContent = 'Place All Bets';
                    placeBtn.addEventListener('click', async () => {
                        placeBtn.disabled = true;
                        // Recompute clamped amounts fresh from workingQueue rather
                        // than trusting values captured at the last full render —
                        // if the user is still mid-edit (typed but hasn't blurred)
                        // this guarantees what's submitted matches what's on screen.
                        const toSubmit = rowRefs.map(({ bet }, idx) => {
                            const { totalOdds, finalAmt } = clampAmount(bet);
                            return { selections: bet.arenaSelections, amt: finalAmt, idx, odds: totalOdds };
                        });
                        for (const r of toSubmit) {
                            if (r.odds === 0) continue;
                            const st = document.getElementById('q-status-' + r.idx);
                            if (st) { st.textContent = '...'; st.style.color = 'var(--nui-warning)'; }

                            const res = await postBet(r.selections, r.amt);
                            if (st) {
                                if (res.ok) {
                                    st.textContent = 'Placed!';
                                    st.style.color = 'var(--nui-success)';
                                } else {
                                    st.textContent = 'Error';
                                    st.style.color = 'var(--nui-danger)';
                                    st.title = res.message;
                                }
                            }
                            await new Promise(resolve => setTimeout(resolve, 600)); // Be nice to the servers
                        }
                        placeBtn.textContent = 'Finished!';
                    });

                    const backBtn = document.createElement('button');
                    backBtn.className = 'nui-btn nui-btn-secondary nui-btn-block';
                    backBtn.textContent = 'Cancel / Back to Single Bet';
                    backBtn.style.marginTop = '8px';
                    backBtn.addEventListener('click', () => switchTab('bet'));

                    queueCard.appendChild(summary);
                    queueCard.appendChild(table);
                    queueCard.appendChild(placeBtn);
                    queueCard.appendChild(backBtn);

                    viewContainer.appendChild(queueCard);
                }

                renderQueueView();
                return;
            }


            // --- SINGLE VIEW (Default) ---
            const infoRow = document.createElement('div');
            infoRow.style.cssText = 'display:flex;gap:8px;align-items:center;flex-wrap:wrap;margin-bottom:var(--nui-space-3);';
            infoRow.innerHTML = `
                <span class="nui-badge" style="background:var(--nui-accent-soft);color:var(--nui-accent);">Max Bet: <b>${maxBet.toLocaleString()} NP</b></span>
                <span class="nui-badge">Check up to 5 arenas</span>
            `;
            viewContainer.appendChild(infoRow);

            const betState = {
                checked: [false, false, false, false, false],
                selected: [null, null, null, null, null],
                amount: 0,
            };

            const form = document.createElement('form');
            form.method = 'post';
            form.action = 'process_foodclub.phtml';
            form.style.cssText = 'display:flex;flex-direction:column;gap:var(--nui-space-3);';
            form.innerHTML = '<input type="hidden" name="type" value="bet">';

            const oddsCard = document.createElement('div');
            oddsCard.style.cssText = 'background:var(--nui-surface-2);border:1px solid var(--nui-border);border-radius:var(--nui-radius-md);padding:12px 16px;display:flex;gap:16px;align-items:center;flex-wrap:wrap;';
            oddsCard.innerHTML = `
                <div style="display:flex;flex-direction:column;align-items:center;">
                    <div id="nui-fc-total-odds" style="font-family:var(--nui-font-display);font-size:26px;font-weight:800;color:var(--nui-accent);">0</div>
                    <div style="font-size:10px;font-weight:700;color:var(--nui-text-faint);text-transform:uppercase;">Odds</div>
                </div>
                <div style="flex:1;min-width:120px;">
                    <label style="font-size:12px;font-weight:700;color:var(--nui-text-muted);display:block;margin-bottom:4px;">Bet Amount (NP)</label>
                    <div style="display:flex;gap:8px;">
                        <input class="nui-input" id="nui-fc-bet-amount" type="number" min="50" max="${maxBet}" value="" placeholder="Enter NP…" style="font-size:14px;padding:8px 12px;flex:1;">
                        <button type="button" class="nui-btn nui-btn-secondary" id="nui-fc-max-btn" style="padding:8px 12px;font-size:12px;">Max</button>
                    </div>
                </div>
                <div style="display:flex;flex-direction:column;align-items:center;">
                    <div id="nui-fc-payoff" style="font-family:var(--nui-font-display);font-size:22px;font-weight:800;color:var(--nui-success);">0</div>
                    <div style="font-size:10px;font-weight:700;color:var(--nui-text-faint);text-transform:uppercase;">Potential Payoff</div>
                </div>
            `;

            const arenaContainer = document.createElement('div');
            arenaContainer.style.cssText = 'display:flex;flex-direction:column;gap:10px;';

            arenas.forEach((arena, idx) => {
                const cbWrap = document.createElement('div');
                cbWrap.style.cssText = 'border:1px solid var(--nui-border);border-radius:var(--nui-radius-md);padding:10px 14px;background:var(--nui-surface);transition:border-color 0.15s;display:flex;flex-direction:column;gap:8px;';

                const topRow = document.createElement('div');
                topRow.style.cssText = 'display:flex;align-items:center;gap:10px;';

                const cb = document.createElement('input');
                cb.type = 'checkbox';
                cb.name = 'matches[]';
                cb.value = String(idx + 1);
                cb.style.cssText = 'width:18px;height:18px;accent-color:var(--nui-accent);cursor:pointer;flex-shrink:0;';
                cb.checked = betState.checked[idx];

                const arenaLabel = document.createElement('span');
                arenaLabel.style.cssText = 'font-weight:800;font-size:15px;color:var(--nui-text);flex:1;';
                arenaLabel.textContent = arena.name;

                const oddsChip = document.createElement('span');
                oddsChip.id = `nui-fc-arena-odds-${idx}`;
                oddsChip.className = 'nui-badge';
                oddsChip.style.cssText = 'font-size:12px;';
                oddsChip.textContent = '—';

                topRow.appendChild(cb);
                topRow.appendChild(arenaLabel);
                topRow.appendChild(oddsChip);
                cbWrap.appendChild(topRow);

                const pillsRow = document.createElement('div');
                pillsRow.style.cssText = 'display:flex;flex-wrap:wrap;gap:6px;padding-left:28px;';

                const hiddenSelect = document.createElement('select');
                hiddenSelect.name = `winner${idx + 1}`;
                hiddenSelect.style.display = 'none';

                const blankOpt = document.createElement('option');
                blankOpt.value = '';
                hiddenSelect.appendChild(blankOpt);

                arena.pirates.forEach(p => {
                    const opt = document.createElement('option');
                    opt.value = String(p.id);
                    opt.textContent = p.name;
                    hiddenSelect.appendChild(opt);

                    const pill = document.createElement('button');
                    pill.type = 'button';
                    pill.setAttribute('data-pid', p.id);
                    pill.style.cssText = 'padding:5px 11px;border-radius:var(--nui-radius-pill);border:1px solid var(--nui-border);font-size:12px;font-weight:700;cursor:pointer;transition:all 0.1s;background:var(--nui-surface-2);color:var(--nui-text-muted);display:flex;align-items:center;gap:5px;';
                    pill.innerHTML = `${p.name} <span style="background:var(--nui-surface);border-radius:4px;padding:1px 5px;font-size:11px;color:var(--nui-text-faint);">${p.odds}:1</span>`;

                    pill.addEventListener('click', () => {
                        if (betState.selected[idx] === p.id) {
                            betState.selected[idx] = null;
                            hiddenSelect.value = '';
                        } else {
                            betState.selected[idx] = p.id;
                            hiddenSelect.value = String(p.id);
                        }
                        if (betState.selected[idx]) betState.checked[idx] = true;
                        cb.checked = betState.checked[idx];

                        pillsRow.querySelectorAll('button[data-pid]').forEach(btn => {
                            const isActive = parseInt(btn.getAttribute('data-pid')) === betState.selected[idx];
                            btn.style.background = isActive ? 'var(--nui-accent-soft)' : 'var(--nui-surface-2)';
                            btn.style.color = isActive ? 'var(--nui-accent)' : 'var(--nui-text-muted)';
                            btn.style.borderColor = isActive ? 'var(--nui-accent)' : 'var(--nui-border)';
                        });

                        updateOdds();
                    });

                    pillsRow.appendChild(pill);
                });

                cbWrap.appendChild(pillsRow);
                cbWrap.appendChild(hiddenSelect);
                arenaContainer.appendChild(cbWrap);

                cb.addEventListener('change', () => {
                    betState.checked[idx] = cb.checked;
                    cbWrap.style.borderColor = cb.checked ? 'var(--nui-accent)' : 'var(--nui-border)';
                    if (!cb.checked) {
                        betState.selected[idx] = null;
                        hiddenSelect.value = '';
                        pillsRow.querySelectorAll('button[data-pid]').forEach(btn => {
                            btn.style.background = 'var(--nui-surface-2)';
                            btn.style.color = 'var(--nui-text-muted)';
                            btn.style.borderColor = 'var(--nui-border)';
                        });
                    }
                    updateOdds();
                });

                if (betState.checked[idx]) cbWrap.style.borderColor = 'var(--nui-accent)';

                function updateArenaChip() {
                    const sel = betState.selected[idx];
                    const chip = document.getElementById(`nui-fc-arena-odds-${idx}`);
                    if (!chip) return;
                    if (sel && betState.checked[idx]) {
                        const o = globalOddsMap[sel] || 1;
                        chip.textContent = `${o}:1`;
                        chip.style.background = 'var(--nui-accent-soft)';
                        chip.style.color = 'var(--nui-accent)';
                    } else {
                        chip.textContent = '—';
                        chip.style.background = '';
                        chip.style.color = '';
                    }
                }

                cbWrap._updateChip = updateArenaChip;
                if (betState.checked[idx] && betState.selected[idx]) updateArenaChip();
            });

            function updateOdds() {
                let totalOdds = 0;
                arenas.forEach((arena, idx) => {
                    if (!betState.checked[idx] || !betState.selected[idx]) return;
                    const o = globalOddsMap[betState.selected[idx]] || 1;
                    totalOdds = totalOdds === 0 ? o : totalOdds * o;
                });

                const oddsEl = document.getElementById('nui-fc-total-odds');
                const payEl = document.getElementById('nui-fc-payoff');
                if (oddsEl) oddsEl.textContent = totalOdds > 0 ? `${totalOdds}:1` : '0';

                const amtInput = document.getElementById('nui-fc-bet-amount');
                const amt = amtInput ? Math.min(parseInt(amtInput.value) || 0, maxBet) : 0;
                const payoff = Math.min(totalOdds * amt, MAX_WIN);
                if (payEl) payEl.textContent = payoff > 0 ? payoff.toLocaleString() + ' NP' : '0';

                arenaContainer.childNodes.forEach(node => node._updateChip && node._updateChip());
            }

            oddsCard.querySelector('#nui-fc-bet-amount').addEventListener('input', updateOdds);

            oddsCard.querySelector('#nui-fc-max-btn').addEventListener('click', () => {
                // Max means max bet, full stop — the site lets you bet up to
                // your account's max bet regardless of odds; it's only the
                // eventual payout that's capped at MAX_WIN (handled in the
                // payoff preview below, not by shrinking the bet amount).
                document.getElementById('nui-fc-bet-amount').value = maxBet;
                updateOdds();
            });

            const submitBtn = document.createElement('button');
            submitBtn.type = 'submit';
            submitBtn.className = 'nui-btn nui-btn-primary nui-btn-block';
            submitBtn.textContent = 'Place This Bet!';
            submitBtn.style.marginTop = 'var(--nui-space-2)';

            submitBtn.addEventListener('click', (e) => {
                const anyChecked = betState.checked.some((c, i) => c && betState.selected[i]);
                if (!anyChecked) {
                    e.preventDefault();
                    showToast('Check at least one arena and pick a pirate!', true);
                    return;
                }
                const amt = parseInt(document.getElementById('nui-fc-bet-amount').value) || 0;
                if (amt < 1) {
                    e.preventDefault();
                    showToast('Enter a bet amount!', true);
                    return;
                }
                if (amt > maxBet) {
                    e.preventDefault();
                    showToast(`Max bet is ${maxBet.toLocaleString()} NP!`, true);
                    return;
                }
                let amtInput = form.querySelector('input[name="bet_amount"]');
                if (!amtInput) {
                    amtInput = document.createElement('input');
                    amtInput.type = 'hidden';
                    amtInput.name = 'bet_amount';
                    form.appendChild(amtInput);
                }
                amtInput.value = String(amt);
            });

            form.appendChild(oddsCard);
            form.appendChild(arenaContainer);
            form.appendChild(submitBtn);
            viewContainer.appendChild(form);

            updateOdds();
        }

        // ─────────────────────────────────────────────────────────────────────
        // RENDER: MY BETS TAB
        // ─────────────────────────────────────────────────────────────────────
        async function renderMyBets() {
            const { doc } = await fetchFC('current_bets');
            const bets = scrapeCurrentBets(doc);
            cacheQuickviewFoodClub(bets);

            contentInner.innerHTML = '';

            if (bets === null || bets.length === 0) {
                contentInner.innerHTML = `<div class="nui-empty"><span class="nui-empty-emoji">📋</span>No bets placed for this round yet.</div>`;
                return;
            }

            const heading = document.createElement('div');
            heading.style.cssText = 'font-family:var(--nui-font-display);font-size:18px;font-weight:800;color:var(--nui-text);margin-bottom:var(--nui-space-3);';
            heading.textContent = `Current Bets (${bets.length})`;
            contentInner.appendChild(heading);

            bets.forEach(bet => {
                const card = document.createElement('div');
                card.style.cssText = 'border:1px solid var(--nui-border);border-radius:var(--nui-radius-md);padding:12px 14px;background:var(--nui-surface-2);margin-bottom:10px;display:flex;flex-direction:column;gap:6px;';

                card.innerHTML = `
                    <div style="font-size:13px;color:var(--nui-text-muted);">${bet.betInfo}</div>
                    <div style="display:flex;gap:12px;align-items:center;flex-wrap:wrap;">
                        <div style="display:flex;flex-direction:column;align-items:center;">
                            <span style="font-family:var(--nui-font-display);font-size:18px;font-weight:800;color:var(--nui-text);">${bet.amount}</span>
                            <span style="font-size:10px;font-weight:700;color:var(--nui-text-faint);text-transform:uppercase;">Bet</span>
                        </div>
                        <div style="display:flex;flex-direction:column;align-items:center;">
                            <span style="font-family:var(--nui-font-display);font-size:18px;font-weight:800;color:var(--nui-accent);">${bet.odds}</span>
                            <span style="font-size:10px;font-weight:700;color:var(--nui-text-faint);text-transform:uppercase;">Odds</span>
                        </div>
                        <div style="display:flex;flex-direction:column;align-items:center;">
                            <span style="font-family:var(--nui-font-display);font-size:18px;font-weight:800;color:var(--nui-success);">${bet.winnings}</span>
                            <span style="font-size:10px;font-weight:700;color:var(--nui-text-faint);text-transform:uppercase;">Potential Win</span>
                        </div>
                    </div>
                `;

                contentInner.appendChild(card);
            });
        }

        // ─────────────────────────────────────────────────────────────────────
        // RENDER: COLLECT TAB  (includes integrated Trophy Run mode toggle)
        // ─────────────────────────────────────────────────────────────────────

        // Persisted across renders within this page session
        const FC_TROPHY_MODE_KEY = 'neoui_fc_trophy_mode';
        function isTrophyMode() {
            try { return localStorage.getItem(FC_TROPHY_MODE_KEY) === '1'; } catch(e) { return false; }
        }
        function setTrophyMode(on) {
            try { localStorage.setItem(FC_TROPHY_MODE_KEY, on ? '1' : '0'); } catch(e) {}
        }

        function trophyExpiryLabel(entry, queueInfo) {
            if (entry.collected) {
                return { text: `✔ Collected ${new Date(entry.collectedAt).toLocaleDateString()}`, color: 'var(--nui-text-faint)' };
            }
            // Prefer round-based expiry (exact — matches the site's real
            // 7-day-after-round-concludes rule) whenever we know both this
            // entry's round and the current newest round from the live
            // queue. Only fall back to the wall-clock estimate for legacy
            // entries with no round number attached.
            if (entry.round != null && queueInfo && queueInfo.newest) {
                const entryRound = parseInt(entry.round, 10);
                if (!isNaN(entryRound)) {
                    const delta = queueInfo.newest.roundNum - entryRound;
                    const daysLeft = TROPHY_EXPIRY_ROUND_DELTA - delta;
                    if (daysLeft <= 0) return { text: '⛔ Expired — winnings are gone', color: 'var(--nui-danger)' };
                    if (daysLeft === 1) return { text: `⚠ Collect now — expires tonight (Round ${entry.round})`, color: 'var(--nui-danger)' };
                    if (daysLeft <= 3) return { text: `⏳ Expires in ${daysLeft}d (Round ${entry.round})`, color: 'var(--nui-warning)' };
                    return { text: `🟢 Safe to hold — ${daysLeft}d left (Round ${entry.round})`, color: 'var(--nui-success)' };
                }
            }
            const expiresAt = entry.loggedAt + TROPHY_EXPIRY_DAYS * 86400000;
            const msLeft = expiresAt - Date.now();
            const daysLeft = Math.ceil(msLeft / 86400000);
            if (daysLeft <= 0) return { text: '⛔ Expired — winnings are gone', color: 'var(--nui-danger)' };
            if (daysLeft <= 2) return { text: `⚠ Collect now — expires in ${daysLeft}d (est.)`, color: 'var(--nui-danger)' };
            if (daysLeft <= 4) return { text: `⏳ Expires in ${daysLeft}d (est.)`, color: 'var(--nui-warning)' };
            return { text: `🟢 Safe to hold — ${daysLeft}d left (est.)`, color: 'var(--nui-success)' };
        }

        async function renderCollect() {
            const { doc } = await fetchFC('collect');
            const { hasWinnings, rows } = scrapeCollect(doc);
            const trophyOn = isTrophyMode();
            const queueInfo = computeQueueInfo(rows); // live, authoritative FIFO queue — null if nothing uncollected

            contentInner.innerHTML = '';

            // ── Trophy Run toggle row (always shown) ─────────────────────────
            const toggleRow = document.createElement('div');
            toggleRow.style.cssText = 'display:flex;align-items:center;justify-content:space-between;gap:12px;padding:10px 14px;border-radius:var(--nui-radius-md);margin-bottom:var(--nui-space-3);background:' + (trophyOn ? 'var(--nui-warning-soft,rgba(255,200,0,0.12))' : 'var(--nui-surface-2)') + ';border:1px solid ' + (trophyOn ? 'var(--nui-warning,#f5a623)' : 'var(--nui-border)') + ';';
            toggleRow.innerHTML = `
                <div>
                    <div style="font-weight:800;font-size:13px;color:${trophyOn ? 'var(--nui-warning,#f5a623)' : 'var(--nui-text)'};display:flex;align-items:center;gap:6px;">🏆 Trophy Run Mode</div>
                    <div style="font-size:11px;color:var(--nui-text-faint);margin-top:2px;">${trophyOn ? 'Log & hold winnings — do NOT collect yet' : 'Off — collect winnings normally'}</div>
                </div>
            `;
            const toggleBtn = document.createElement('button');
            toggleBtn.type = 'button';
            toggleBtn.className = trophyOn ? 'nui-btn nui-btn-primary' : 'nui-btn nui-btn-secondary';
            toggleBtn.style.cssText = 'flex-shrink:0;font-size:12px;padding:6px 14px;';
            toggleBtn.textContent = trophyOn ? 'ON' : 'OFF';
            toggleBtn.addEventListener('click', () => { setTrophyMode(!trophyOn); renderCollect(); });
            toggleRow.appendChild(toggleBtn);
            contentInner.appendChild(toggleRow);

            // ── Held entries panel (only in trophy mode) ──────────────────────
            if (trophyOn) {
                let run = loadTrophyRun();
                if (!run) run = startTrophyRun();

                // ── Live Queue Status — sourced from the real Collect page,
                // not from local logging, since this is the site's actual
                // FIFO winnings queue (max 8 rounds; collecting drains all
                // of it at once; the oldest round expires at Midnight NST
                // once the round gap reaches 7).
                const queueStatus = document.createElement('div');
                queueStatus.style.cssText = 'border-radius:var(--nui-radius-md);padding:10px 14px;margin-bottom:var(--nui-space-2);border:1px solid var(--nui-border);background:var(--nui-surface-2);';

                if (!queueInfo) {
                    queueStatus.innerHTML = `<div style="font-size:12px;color:var(--nui-text-faint);">Queue empty — no uncollected rounds on Neopets right now.</div>`;
                    contentInner.appendChild(queueStatus);
                } else {
                    const capLabel = `${queueInfo.size}/${TROPHY_MAX_QUEUE_ROUNDS}`;
                    const spanLabel = queueInfo.oldest.round === queueInfo.newest.round
                        ? `Round ${queueInfo.oldest.round}`
                        : `Rounds ${queueInfo.oldest.round}–${queueInfo.newest.round}`;
                    queueStatus.innerHTML = `
                        <div style="display:flex;justify-content:space-between;align-items:center;flex-wrap:wrap;gap:8px;">
                            <div style="font-family:var(--nui-font-display);font-size:14px;font-weight:800;color:var(--nui-text);">Queue: ${capLabel} rounds${queueInfo.atCapacity ? ' — FULL' : ''}</div>
                            <div style="font-family:var(--nui-font-display);font-size:16px;font-weight:800;color:var(--nui-success);">${queueInfo.total.toLocaleString()} NP</div>
                        </div>
                        <div style="font-size:11px;color:var(--nui-text-faint);margin-top:2px;">${spanLabel} (gap: ${queueInfo.roundDelta} day${queueInfo.roundDelta === 1 ? '' : 's'})</div>
                    `;
                    contentInner.appendChild(queueStatus);

                    if (queueInfo.possiblyStale) {
                        const staleBanner = document.createElement('div');
                        staleBanner.style.cssText = 'padding:8px 12px;background:var(--nui-warning-soft,rgba(255,200,0,0.12));border:1px solid var(--nui-warning,#f5a623);border-radius:var(--nui-radius-md);color:var(--nui-warning,#f5a623);font-weight:700;font-size:12px;margin-bottom:var(--nui-space-2);';
                        staleBanner.textContent = `⚠ Round gap is wider than ${TROPHY_EXPIRY_ROUND_DELTA} days — the oldest round shown may already be gone. Refresh to confirm.`;
                        contentInner.appendChild(staleBanner);
                    } else if (queueInfo.oldestExpiresTonight) {
                        // The spec's exact escalating warning, with severity
                        // scaling as Midnight NST approaches.
                        const msLeft = msUntilNstMidnight();
                        const critical = msLeft <= 3 * 3600000; // last 3 hours
                        const warnBanner = document.createElement('div');
                        warnBanner.style.cssText = `padding:10px 12px;background:${critical ? 'var(--nui-danger)' : 'var(--nui-danger-soft)'};border:1px solid var(--nui-danger);border-radius:var(--nui-radius-md);color:${critical ? '#fff' : 'var(--nui-danger)'};font-weight:800;font-size:12px;margin-bottom:var(--nui-space-2);line-height:1.5;`;
                        warnBanner.textContent = buildExpiryWarning(queueInfo);
                        contentInner.appendChild(warnBanner);

                        const countdown = document.createElement('div');
                        countdown.style.cssText = 'text-align:center;font-size:11px;font-weight:700;color:var(--nui-danger);margin-bottom:var(--nui-space-2);';
                        countdown.textContent = `⏰ ${formatHoursMinutes(msLeft)} until Midnight NST`;
                        contentInner.appendChild(countdown);
                    } else if (queueInfo.atCapacity) {
                        const fullBanner = document.createElement('div');
                        fullBanner.style.cssText = 'padding:8px 12px;background:var(--nui-warning-soft,rgba(255,200,0,0.12));border:1px solid var(--nui-warning,#f5a623);border-radius:var(--nui-radius-md);color:var(--nui-warning,#f5a623);font-weight:700;font-size:12px;margin-bottom:var(--nui-space-2);';
                        fullBanner.textContent = `🏆 Queue is at max capacity (${TROPHY_MAX_QUEUE_ROUNDS}/${TROPHY_MAX_QUEUE_ROUNDS}) — this is peak trophy-run size. Collect before Round ${queueInfo.oldest.round}'s window closes.`;
                        contentInner.appendChild(fullBanner);
                    }
                }

                const activeEntries = run.entries.filter(e => !e.collected);
                const totalHeld = activeEntries.reduce((s, e) => s + (e.amount || 0), 0);

                const heldHeader = document.createElement('div');
                heldHeader.style.cssText = 'display:flex;justify-content:space-between;align-items:center;flex-wrap:wrap;gap:8px;margin-bottom:var(--nui-space-2);';
                heldHeader.innerHTML = `
                    <div style="font-family:var(--nui-font-display);font-size:15px;font-weight:800;color:var(--nui-text);">Logged History</div>
                    <div style="font-family:var(--nui-font-display);font-size:14px;font-weight:800;color:var(--nui-text-faint);">${totalHeld.toLocaleString()} NP logged</div>
                `;
                contentInner.appendChild(heldHeader);

                if (activeEntries.length === 0) {
                    const emptyHeld = document.createElement('div');
                    emptyHeld.style.cssText = 'font-size:12px;color:var(--nui-text-faint);padding:6px 0 10px;';
                    emptyHeld.textContent = 'No batches logged yet — log today\'s winnings below after you don\'t collect.';
                    contentInner.appendChild(emptyHeld);
                } else {
                    // Show held entries newest→oldest, each with expiry label
                    const entriesByNewest = activeEntries.slice().sort((a, b) => b.loggedAt - a.loggedAt);
                    entriesByNewest.forEach(entry => {
                        const { text: exText, color: exColor } = trophyExpiryLabel(entry, queueInfo);
                        const eRow = document.createElement('div');
                        eRow.style.cssText = 'border:1px solid var(--nui-border);border-radius:var(--nui-radius-md);padding:8px 12px;background:var(--nui-surface-2);margin-bottom:6px;display:flex;align-items:center;gap:10px;flex-wrap:wrap;';
                        eRow.innerHTML = `
                            <div style="flex:1;min-width:100px;">
                                <div style="font-size:11px;color:var(--nui-text-faint);font-weight:700;">${new Date(entry.loggedAt).toLocaleDateString()}${entry.note ? ' · ' + entry.note.replace(/</g,'&lt;') : ''}</div>
                                <div style="font-weight:800;color:var(--nui-text);font-size:14px;">${(entry.amount || 0).toLocaleString()} NP</div>
                            </div>
                            <div style="font-size:12px;font-weight:700;color:${exColor};">${exText}</div>
                        `;
                        const rmBtn = document.createElement('button');
                        rmBtn.type = 'button';
                        rmBtn.className = 'nui-btn nui-btn-secondary';
                        rmBtn.textContent = '✕';
                        rmBtn.title = 'Remove entry';
                        rmBtn.style.cssText = 'flex-shrink:0;font-size:11px;padding:4px 8px;';
                        rmBtn.addEventListener('click', () => {
                            run.entries = run.entries.filter(e => e.id !== entry.id);
                            saveTrophyRun(run);
                            renderCollect();
                        });
                        eRow.appendChild(rmBtn);
                        contentInner.appendChild(eRow);
                    });
                }

                const divider = document.createElement('div');
                divider.style.cssText = 'border-top:1px solid var(--nui-border);margin:var(--nui-space-3) 0;';
                contentInner.appendChild(divider);
            }

            // ── Winnings available section ─────────────────────────────────
            if (!hasWinnings) {
                contentInner.insertAdjacentHTML('beforeend', `<div class="nui-empty"><span class="nui-empty-emoji">💰</span>No winning bets to collect right now.</div>`);
                return;
            }

            const heading = document.createElement('div');
            heading.style.cssText = 'font-family:var(--nui-font-display);font-size:18px;font-weight:800;color:var(--nui-text);margin-bottom:var(--nui-space-3);';
            heading.textContent = 'Winnings Available!';
            contentInner.appendChild(heading);

            let totalWin = 0;
            rows.forEach(r => {
                const n = parseInt((r.winnings || '').replace(/[^0-9]/g, ''));
                if (!isNaN(n)) totalWin += n;
            });

            // Figure out which of these rounds have already been logged into
            // the trophy run, so we never re-log the same round's winnings —
            // the Neopets collect page shows a running total across every
            // uncollected round, not just the newest one.
            //
            // `rows` is one entry PER WINNING BET, not per round — you can
            // place up to 10 bets in a single round, and any subset of them
            // can win. The real winnings queue is keyed by Round ID, so
            // multiple winning bets in the same round combine into one queue
            // slot there. Group by round and sum here too, before diffing
            // against loggedRounds — otherwise two winning bets in the same
            // round would survive the filter as two separate "new" rows and
            // get logged as two round entries instead of one.
            let trophyRunForLog = null, loggedRounds = new Set(), newRows = [], newTotal = 0, totalRoundCount = 0;
            if (trophyOn) {
                trophyRunForLog = loadTrophyRun();
                if (!trophyRunForLog) trophyRunForLog = startTrophyRun();
                loggedRounds = loggedRoundSet(trophyRunForLog);
                const roundTotals = new Map(); // round -> summed winnings (NP), in first-seen order
                rows.forEach(r => {
                    const n = parseInt((r.winnings || '').replace(/[^0-9]/g, ''));
                    if (isNaN(n)) return;
                    roundTotals.set(r.round, (roundTotals.get(r.round) || 0) + n);
                });
                totalRoundCount = roundTotals.size;
                newRows = Array.from(roundTotals.entries())
                    .filter(([round]) => !loggedRounds.has(String(round)))
                    .map(([round, amount]) => ({ round: round, winnings: String(amount) }));
                newRows.forEach(r => { newTotal += parseInt(r.winnings, 10) || 0; });
            }

            if (totalWin > 0) {
                const totalBadge = document.createElement('div');
                totalBadge.style.cssText = 'display:inline-flex;align-items:center;gap:8px;padding:8px 14px;background:var(--nui-success-soft);border:1px solid var(--nui-success);border-radius:var(--nui-radius-pill);font-weight:800;color:var(--nui-success);font-size:15px;margin-bottom:' + (trophyOn ? 'var(--nui-space-1)' : 'var(--nui-space-3)') + ';';
                totalBadge.innerHTML = `🎉 Total: ${totalWin.toLocaleString()} NP`;
                contentInner.appendChild(totalBadge);

                if (trophyOn) {
                    const newLine = document.createElement('div');
                    newLine.style.cssText = 'font-size:11px;color:var(--nui-text-faint);margin-bottom:var(--nui-space-3);';
                    newLine.textContent = newRows.length > 0
                        ? `${newTotal.toLocaleString()} NP of that is new since your last log (${newRows.length} round${newRows.length === 1 ? '' : 's'}).`
                        : 'All of that has already been logged to your trophy run.';
                    contentInner.appendChild(newLine);
                }
            }

            rows.forEach(r => {
                const alreadyLogged = trophyOn && loggedRounds.has(String(r.round));
                const card = document.createElement('div');
                card.style.cssText = 'border:1px solid var(--nui-border);border-radius:var(--nui-radius-md);padding:12px 14px;background:var(--nui-surface-2);margin-bottom:10px;display:flex;gap:12px;align-items:center;flex-wrap:wrap;' + (alreadyLogged ? 'opacity:0.6;' : '');
                card.innerHTML = `
                    <div style="flex:1;min-width:0;">
                        <div style="font-size:12px;color:var(--nui-text-faint);font-weight:700;margin-bottom:3px;">Round ${r.round}${alreadyLogged ? ' <span style="color:var(--nui-success);">· ✔ Logged</span>' : ''}</div>
                        <div style="font-size:13px;color:var(--nui-text-muted);">${r.betInfo}</div>
                    </div>
                    <div style="display:flex;gap:12px;align-items:center;">
                        <div style="text-align:center;">
                            <div style="font-weight:800;color:var(--nui-text);font-size:15px;">${r.amount}</div>
                            <div style="font-size:10px;font-weight:700;color:var(--nui-text-faint);text-transform:uppercase;">Bet</div>
                        </div>
                        <div style="text-align:center;">
                            <div style="font-weight:800;color:var(--nui-accent);font-size:15px;">${r.odds}</div>
                            <div style="font-size:10px;font-weight:700;color:var(--nui-text-faint);text-transform:uppercase;">Odds</div>
                        </div>
                        <div style="text-align:center;">
                            <div style="font-weight:800;color:var(--nui-success);font-size:18px;">${r.winnings}</div>
                            <div style="font-size:10px;font-weight:700;color:var(--nui-text-faint);text-transform:uppercase;">Won</div>
                        </div>
                    </div>
                `;
                contentInner.appendChild(card);
            });

            if (trophyOn) {
                // Trophy mode: log & hold instead of collecting. Only rounds
                // not already represented in the run get logged, and each
                // round becomes its own entry — never one blob of the whole
                // running total (which would double-count rounds still
                // sitting uncollected from a previous click).
                const holdBtn = document.createElement('button');
                holdBtn.type = 'button';
                holdBtn.style.marginTop = 'var(--nui-space-3)';

                if (newRows.length === 0) {
                    holdBtn.className = 'nui-btn nui-btn-secondary nui-btn-block';
                    holdBtn.textContent = `✔ All ${totalRoundCount} round${totalRoundCount === 1 ? '' : 's'} already logged`;
                    holdBtn.disabled = true;
                } else {
                    holdBtn.className = 'nui-btn nui-btn-primary nui-btn-block';
                    holdBtn.textContent = `🏆 Log & Hold ${newRows.length} New Round${newRows.length === 1 ? '' : 's'} — ${newTotal.toLocaleString()} NP (do NOT collect)`;
                    holdBtn.addEventListener('click', () => {
                        const run = trophyRunForLog || loadTrophyRun() || startTrophyRun();
                        newRows.forEach(r => {
                            const n = parseInt((r.winnings || '').replace(/[^0-9]/g, ''));
                            addTrophyEntry(run, isNaN(n) ? 0 : n, `Round ${r.round}`, r.round);
                        });
                        holdBtn.textContent = `✔ Logged ${newRows.length} round${newRows.length === 1 ? '' : 's'} — ${newTotal.toLocaleString()} NP added`;
                        holdBtn.disabled = true;
                        // Refresh after a moment to show updated held entries
                        setTimeout(() => renderCollect(), 900);
                    });
                }
                contentInner.appendChild(holdBtn);

                // All-or-nothing reminder: matches the real site — there is
                // no way to collect a single round, so any collect click
                // (including the emergency one below) drains the entire
                // queue shown above at once.
                const warningNote = document.createElement('div');
                warningNote.style.cssText = 'text-align:center;font-size:11px;color:var(--nui-text-faint);margin-top:8px;';
                warningNote.textContent = queueInfo
                    ? `⚠ Collecting is all-or-nothing — it will drain all ${queueInfo.size} queued round${queueInfo.size === 1 ? '' : 's'} (${queueInfo.total.toLocaleString()} NP) at once.`
                    : '⚠ Do not use "Collect All Winnings" on Neopets while Trophy Run is active.';
                contentInner.appendChild(warningNote);

                // Secondary: still allow emergency collect
                const emergencyBtn = document.createElement('button');
                emergencyBtn.type = 'button';
                emergencyBtn.className = 'nui-btn nui-btn-secondary nui-btn-block';
                emergencyBtn.style.marginTop = 'var(--nui-space-2)';
                emergencyBtn.textContent = 'Collect All Winnings (emergency — ends run intent)';
                emergencyBtn.addEventListener('click', async () => {
                    if (!confirm('Collect winnings now? This will end your trophy run for this cycle if uncollected NP is being held.')) return;
                    emergencyBtn.disabled = true;
                    emergencyBtn.textContent = 'Collecting…';
                    const fd = new FormData();
                    fd.append('type', 'collect');
                    try {
                        const res = await fetch('/pirates/process_foodclub.phtml', { method: 'POST', credentials: 'include', body: fd });
                        const html = await res.text();
                        const rdoc = new DOMParser().parseFromString(html, 'text/html');
                        const errorEl = rdoc.querySelector('.errorMessage, #errorMessage, .error_msg, p.error, .neopets-error');
                        if (errorEl) {
                            emergencyBtn.textContent = '⚠ ' + errorEl.textContent.replace(/\s+/g, ' ').trim().slice(0, 80);
                            emergencyBtn.className = 'nui-btn nui-btn-danger nui-btn-block';
                        } else {
                            // Same reasoning as the normal-mode collect button:
                            // trust the total we already scraped/summed from the
                            // Collect page (totalWin) instead of re-parsing the
                            // confirmation page's body text, which can surface
                            // an unrelated, smaller "<number> NP" mention first.
                            emergencyBtn.textContent = '✓ Collected ' + totalWin.toLocaleString() + ' NP!';
                            emergencyBtn.className = 'nui-btn nui-btn-success nui-btn-block';
                            // Real collection is all-or-nothing, so the entire
                            // local log is now stale — mark it collected to
                            // match reality instead of leaving old rounds
                            // showing as still "held".
                            const runNow = loadTrophyRun();
                            if (runNow) markAllTrophyEntriesCollected(runNow);
                            setTimeout(() => renderCollect(), 1500);
                        }
                    } catch (e) {
                        emergencyBtn.textContent = '⚠ Network error';
                        emergencyBtn.className = 'nui-btn nui-btn-danger nui-btn-block';
                    }
                });
                contentInner.appendChild(emergencyBtn);

            } else {
                // Normal mode: collect immediately
                const collectBtn = document.createElement('button');
                collectBtn.type = 'button';
                collectBtn.className = 'nui-btn nui-btn-primary nui-btn-block';
                collectBtn.style.marginTop = 'var(--nui-space-3)';
                collectBtn.textContent = 'Collect All Winnings';
                collectBtn.addEventListener('click', async () => {
                    collectBtn.disabled = true;
                    collectBtn.textContent = 'Collecting…';
                    const fd = new FormData();
                    fd.append('type', 'collect');
                    try {
                        const res = await fetch('/pirates/process_foodclub.phtml', {
                            method: 'POST',
                            credentials: 'include',
                            body: fd,
                        });
                        const html = await res.text();
                        const rdoc = new DOMParser().parseFromString(html, 'text/html');
                        const errorEl = rdoc.querySelector('.errorMessage, #errorMessage, .error_msg, p.error, .neopets-error');
                        if (errorEl) {
                            const msg = errorEl.textContent.replace(/\s+/g, ' ').trim().slice(0, 80);
                            collectBtn.textContent = '⚠ ' + msg;
                            collectBtn.className = 'nui-btn nui-btn-danger nui-btn-block';
                        } else {
                            // Don't re-scrape the confirmation page for the
                            // collected amount — its body text usually has
                            // several other "<number> NP" mentions (nav bar
                            // balance, sidebar stats, etc.) sitting earlier in
                            // the DOM than the actual payout, so a first-match
                            // regex grabs whichever of those happens to come
                            // first rather than the real total. We already
                            // scraped and summed the true amount (totalWin)
                            // from the Collect page itself before submitting,
                            // so that's the trustworthy number to show.
                            collectBtn.textContent = '✓ Collected ' + totalWin.toLocaleString() + ' NP!';
                            collectBtn.className = 'nui-btn nui-btn-success nui-btn-block';
                            // Same all-or-nothing reasoning as the emergency
                            // path above — clear any stale local log entries.
                            const runNow = loadTrophyRun();
                            if (runNow) markAllTrophyEntriesCollected(runNow);
                            setTimeout(() => renderCollect(), 1500);
                        }
                    } catch (e) {
                        collectBtn.textContent = '⚠ Network error';
                        collectBtn.className = 'nui-btn nui-btn-danger nui-btn-block';
                    }
                });
                contentInner.appendChild(collectBtn);
            }
        }

        // ─────────────────────────────────────────────────────────────────────
        // RENDER: HISTORY TAB
        // ─────────────────────────────────────────────────────────────────────
        async function renderHistory() {
            const { doc } = await fetchFC('history');
            const historyData = scrapeHistory(doc);

            contentInner.innerHTML = '';

            if (!historyData) {
                contentInner.innerHTML = `<div class="nui-empty"><span class="nui-empty-emoji">📜</span>No bet history found.</div>`;
                return;
            }

            const heading = document.createElement('div');
            heading.style.cssText = 'font-family:var(--nui-font-display);font-size:18px;font-weight:800;color:var(--nui-text);margin-bottom:var(--nui-space-3);';
            heading.textContent = `Bet History`;
            contentInner.appendChild(heading);

            const card = document.createElement('div');
            card.style.cssText = 'border:1px solid var(--nui-border);border-radius:var(--nui-radius-md);padding:16px 20px;background:var(--nui-surface-2);display:flex;gap:16px;justify-content:space-around;flex-wrap:wrap;text-align:center;';

            const diffText = historyData.differenceHtml.replace(/<[^>]+>/g, '');
            const diffVal = parseInt(diffText.replace(/,/g, '')) || 0;
            const diffColor = diffVal >= 0 ? 'var(--nui-success)' : 'var(--nui-danger)';

            card.innerHTML = `
                <div>
                    <div style="font-size:11px;font-weight:800;color:var(--nui-text-faint);text-transform:uppercase;letter-spacing:0.5px;margin-bottom:4px;">Bets Placed</div>
                    <div style="font-family:var(--nui-font-display);font-size:22px;font-weight:800;color:var(--nui-text);">${historyData.betsPlaced}</div>
                </div>
                <div>
                    <div style="font-size:11px;font-weight:800;color:var(--nui-text-faint);text-transform:uppercase;letter-spacing:0.5px;margin-bottom:4px;">Bet Total</div>
                    <div style="font-family:var(--nui-font-display);font-size:22px;font-weight:800;color:var(--nui-text);">${historyData.betTotal}</div>
                </div>
                <div>
                    <div style="font-size:11px;font-weight:800;color:var(--nui-text-faint);text-transform:uppercase;letter-spacing:0.5px;margin-bottom:4px;">Win Total</div>
                    <div style="font-family:var(--nui-font-display);font-size:22px;font-weight:800;color:var(--nui-accent);">${historyData.winTotal}</div>
                </div>
                <div>
                    <div style="font-size:11px;font-weight:800;color:var(--nui-text-faint);text-transform:uppercase;letter-spacing:0.5px;margin-bottom:4px;">Difference</div>
                    <div style="font-family:var(--nui-font-display);font-size:22px;font-weight:800;color:${diffColor};">${diffText}</div>
                </div>
            `;

            contentInner.appendChild(card);
        }

        // (Trophy Run tab removed — trophy mode is now a toggle on the Collect tab)
        // Dead code placeholder to preserve line structure; functions below are gone.
        if (false) { async function renderTrophy() { // eslint-disable-line
            contentInner.innerHTML = '';
            let run = loadTrophyRun();

            if (!run) {
                const intro = document.createElement('div');
                intro.style.cssText = 'text-align:center;padding:30px 10px;';
                intro.innerHTML = `
                    <div style="font-size:36px;margin-bottom:10px;">🏆</div>
                    <div style="font-family:var(--nui-font-display);font-size:18px;font-weight:800;color:var(--nui-text);margin-bottom:8px;">Start a Trophy Run</div>
                    <div style="font-size:13px;color:var(--nui-text-muted);max-width:420px;margin:0 auto 18px;line-height:1.5;">
                        Log each day's winnings instead of collecting them, so your total
                        keeps growing toward a trophy. Every logged day gets a 7-day expiry
                        label — collect before it expires or the winnings are lost.
                    </div>
                `;
                const startBtn = document.createElement('button');
                startBtn.type = 'button';
                startBtn.className = 'nui-btn nui-btn-primary';
                startBtn.textContent = '🏆 Start Trophy Run';
                startBtn.addEventListener('click', () => { startTrophyRun(); renderTrophy(); });
                intro.appendChild(startBtn);
                contentInner.appendChild(intro);
                return;
            }

            const dayNow = dayNumberFor(run, Date.now());
            const active = run.entries.filter(e => !e.collected);
            const totalHeld = active.reduce((s, e) => s + (e.amount || 0), 0);
            const soonest = active
                .map(e => expiryInfoFor(e).daysLeft)
                .filter(d => !isNaN(d))
                .sort((a, b) => a - b)[0];

            const header = document.createElement('div');
            header.style.cssText = 'display:flex;justify-content:space-between;align-items:flex-start;flex-wrap:wrap;gap:10px;margin-bottom:var(--nui-space-3);';
            header.innerHTML = `
                <div>
                    <div style="font-family:var(--nui-font-display);font-size:18px;font-weight:800;color:var(--nui-text);">🏆 Trophy Run — Day ${dayNow}</div>
                    <div style="font-size:12px;color:var(--nui-text-faint);margin-top:2px;">Started ${new Date(run.startedAt).toLocaleDateString()}</div>
                </div>
                <div style="text-align:right;">
                    <div style="font-family:var(--nui-font-display);font-size:20px;font-weight:800;color:var(--nui-success);">${totalHeld.toLocaleString()} NP</div>
                    <div style="font-size:11px;font-weight:700;color:var(--nui-text-faint);text-transform:uppercase;">Held Across ${active.length} Day${active.length === 1 ? '' : 's'}</div>
                </div>
            `;
            contentInner.appendChild(header);

            if (soonest !== undefined && soonest <= 2) {
                const warn = document.createElement('div');
                warn.style.cssText = 'padding:8px 12px;background:var(--nui-danger-soft);border:1px solid var(--nui-danger);border-radius:var(--nui-radius-md);color:var(--nui-danger);font-weight:700;font-size:13px;margin-bottom:var(--nui-space-3);';
                warn.textContent = soonest <= 0
                    ? '⛔ One or more held days have expired.'
                    : `⚠ Your oldest held winnings expire in ${soonest} day${soonest === 1 ? '' : 's'} — collect soon!`;
                contentInner.appendChild(warn);
            }

            // Log-a-day form
            const logCard = document.createElement('div');
            logCard.style.cssText = 'border:1px solid var(--nui-border);border-radius:var(--nui-radius-md);padding:12px 14px;background:var(--nui-surface-2);margin-bottom:var(--nui-space-3);display:flex;gap:8px;flex-wrap:wrap;align-items:center;';
            logCard.innerHTML = `
                <input id="nui-trophy-amt" type="number" placeholder="Winnings (NP)" min="0" style="flex:1;min-width:120px;padding:8px 10px;border-radius:var(--nui-radius-sm);border:1px solid var(--nui-border);background:var(--nui-surface);color:var(--nui-text);font-size:13px;">
                <input id="nui-trophy-note" type="text" placeholder="Note (optional)" maxlength="60" style="flex:2;min-width:140px;padding:8px 10px;border-radius:var(--nui-radius-sm);border:1px solid var(--nui-border);background:var(--nui-surface);color:var(--nui-text);font-size:13px;">
            `;
            const logBtn = document.createElement('button');
            logBtn.type = 'button';
            logBtn.className = 'nui-btn nui-btn-primary';
            logBtn.textContent = '+ Log Today';
            logBtn.style.flexShrink = '0';
            logBtn.addEventListener('click', () => {
                const amtEl = contentInner.querySelector('#nui-trophy-amt');
                const noteEl = contentInner.querySelector('#nui-trophy-note');
                const amt = parseInt(amtEl.value, 10);
                if (isNaN(amt) || amt < 0) { amtEl.focus(); return; }
                addTrophyEntry(run, amt, noteEl.value.trim());
                renderTrophy();
            });
            logCard.appendChild(logBtn);
            contentInner.appendChild(logCard);

            // Entries list, newest first
            const sorted = run.entries.slice().sort((a, b) => b.loggedAt - a.loggedAt);
            if (!sorted.length) {
                contentInner.insertAdjacentHTML('beforeend', '<div class="nui-empty"><span class="nui-empty-emoji">📭</span>No days logged yet. Add today\'s winnings above.</div>');
            } else {
                sorted.forEach(entry => {
                    const status = trophyStatusLabel(entry);
                    const day = dayNumberFor(run, entry.loggedAt);
                    const row = document.createElement('div');
                    row.style.cssText = `border:1px solid var(--nui-border);border-radius:var(--nui-radius-md);padding:10px 14px;background:var(--nui-surface-2);margin-bottom:8px;display:flex;gap:12px;align-items:center;flex-wrap:wrap;${entry.collected ? 'opacity:0.6;' : ''}`;
                    row.innerHTML = `
                        <div style="flex:1;min-width:120px;">
                            <div style="font-size:12px;color:var(--nui-text-faint);font-weight:700;">Day ${day} · ${new Date(entry.loggedAt).toLocaleDateString()}</div>
                            <div style="font-weight:800;color:var(--nui-text);font-size:15px;">${(entry.amount || 0).toLocaleString()} NP</div>
                            ${entry.note ? `<div style="font-size:12px;color:var(--nui-text-muted);margin-top:2px;">${entry.note.replace(/</g, '&lt;')}</div>` : ''}
                        </div>
                        <div style="font-size:12px;font-weight:700;color:${status.color};text-align:right;flex:1;min-width:160px;">${status.text}</div>
                    `;
                    if (!entry.collected) {
                        const collectBtn = document.createElement('button');
                        collectBtn.type = 'button';
                        collectBtn.className = 'nui-btn nui-btn-success';
                        collectBtn.textContent = 'Mark Collected';
                        collectBtn.style.cssText += 'flex-shrink:0;font-size:12px;padding:6px 10px;';
                        collectBtn.addEventListener('click', () => {
                            entry.collected = true;
                            entry.collectedAt = Date.now();
                            saveTrophyRun(run);
                            renderTrophy();
                        });
                        row.appendChild(collectBtn);
                    }
                    const removeBtn = document.createElement('button');
                    removeBtn.type = 'button';
                    removeBtn.className = 'nui-btn nui-btn-secondary';
                    removeBtn.textContent = '✕';
                    removeBtn.title = 'Remove entry';
                    removeBtn.style.cssText += 'flex-shrink:0;font-size:12px;padding:6px 10px;';
                    removeBtn.addEventListener('click', () => {
                        run.entries = run.entries.filter(e => e.id !== entry.id);
                        saveTrophyRun(run);
                        renderTrophy();
                    });
                    row.appendChild(removeBtn);
                    contentInner.appendChild(row);
                });
            }

            const endBtn = document.createElement('button');
            endBtn.type = 'button';
            endBtn.className = 'nui-btn nui-btn-danger nui-btn-block';
            endBtn.style.marginTop = 'var(--nui-space-3)';
            endBtn.textContent = 'End Trophy Run';
            endBtn.addEventListener('click', () => {
                if (!confirm('End this trophy run? Logged days will be cleared (this does not affect real NP or in-game winnings).')) return;
                endTrophyRun();
                renderTrophy();
            });
            contentInner.appendChild(endBtn);
        } } // end dead-code block

        switchTab(activeTab);
    }

    // ─────────────────────────────────────────────────────────────────────────
    // ENTRY POINT
    // ─────────────────────────────────────────────────────────────────────────
    let booted = false;
    function boot() {
        if (booted) return;
        booted = true;
        init().catch(showFatalError);
    }

    if (document.readyState === 'complete' || document.readyState === 'interactive') {
        boot();
    } else {
        document.addEventListener('DOMContentLoaded', boot);
    }

})();

// ==============================================================================
// MODULE 34: COCONUT SHY
// ==============================================================================
// Headless SPA wrapper for the daily Coconut Shy game.
// ==============================================================================

(function () {
    'use strict';

    if (!/\/halloween\/coconutshy\.phtml/.test(location.pathname)) return;
    if (!window.NeoUI || !window.NeoUI.isModuleEnabled('coconut-shy')) return;

    const NeoUI = window.NeoUI;
    if (!NeoUI || !NeoUI.__ready) return;

    function showFatalError(err) {
        try {
            const box = document.createElement('div');
            box.style.cssText = 'position:fixed;top:0;left:0;right:0;z-index:99999;background:#fee2e2;color:#7f1d1d;font:14px monospace;padding:15px;white-space:pre-wrap;max-height:50vh;overflow:auto;border-bottom:3px solid #dc2626;';
            box.textContent = 'Coconut Shy SPA crashed:\n' + (err && err.stack ? err.stack : String(err));
            document.body.insertBefore(box, document.body.firstChild);
        } catch (e2) {}
    }

    let throwCount = 0;

    // Read-side of the same store syncDailyTimer() writes to. The SPA
    // rebuilds from scratch on every visit, so without this it forgets
    // "you already threw your last coconut an hour ago" and shows a fresh
    // "Ready to throw" every reload — costing a wasted throw attempt (and
    // a wasted 100 NP click) before it re-learns what the hub already
    // knew. The timers are stable/known in advance, so we just read them.
    function getStoredCoconutNextAt() {
        try {
            const raw = localStorage.getItem('neoui_daily_timers_v1');
            const list = raw ? JSON.parse(raw) : [];
            if (!Array.isArray(list)) return null;
            const entry = list.find(function (i) { return i && i.id === 'coconut-shy'; });
            return entry && entry.nextAt ? entry.nextAt : null;
        } catch (e) { return null; }
    }

    // Inject custom animation styles for the throw
    const style = document.createElement('style');
    style.textContent = `
        @keyframes nui-shake {
            0% { transform: translate(1px, 1px) rotate(0deg); }
            10% { transform: translate(-1px, -2px) rotate(-1deg); }
            20% { transform: translate(-3px, 0px) rotate(1deg); }
            30% { transform: translate(3px, 2px) rotate(0deg); }
            40% { transform: translate(1px, -1px) rotate(1deg); }
            50% { transform: translate(-1px, 2px) rotate(-1deg); }
            60% { transform: translate(-3px, 1px) rotate(0deg); }
            70% { transform: translate(3px, 1px) rotate(-1deg); }
            80% { transform: translate(-1px, -1px) rotate(1deg); }
            90% { transform: translate(1px, 2px) rotate(0deg); }
            100% { transform: translate(1px, -2px) rotate(-1deg); }
        }
        .nui-shake { animation: nui-shake 0.3s cubic-bezier(.36,.07,.19,.97) both; animation-iteration-count: infinite; }
    `;
    document.head.appendChild(style);

    // --- API Calls ---
    async function throwCoconut() {
        const coconutId = Math.floor(Math.random() * 5) + 1;
        const url = `/halloween/process_cocoshy.phtml?coconut=${coconutId}&_=${Date.now()}`;

        const res = await fetch(url, { method: 'POST' });
        const text = await res.text();
        const params = new URLSearchParams(text);

        return {
            points: parseInt(params.get('points') || '0', 10),
            totalNp: params.get('totalnp') || null,
            success: params.get('success') === '1',
            error: params.get('error') || '',
            item: params.get('item') || null
        };
    }

    function updateLiveNP(newNpStr) {
        if (!newNpStr) return;
        const npNum = parseInt(newNpStr, 10);
        if (isNaN(npNum)) return;

        const npElements = document.querySelectorAll('.nui-topbar-stats span, #npanchor, .nui-badge');
        npElements.forEach(el => {
            if (el.textContent.includes('NP') || !isNaN(parseInt(el.textContent.replace(/,/g, '')))) {
                if (!el.innerHTML.includes('<')) {
                    el.textContent = npNum.toLocaleString();
                }
            }
        });
    }

    // --- UI Builders ---
    function initAppShell() {
        const profile = NeoUI.scrapeLegacyProfile();

        Array.from(document.body.children).forEach(child => {
            if (['script', 'style', 'link'].includes(child.tagName.toLowerCase())) return;
            child.style.display = 'none';
        });

        document.body.className = 'nui-reset nui-spa-active';

        NeoUI.init();
        NeoUI.setProfileInfo(profile);
        NeoUI.buildTopbar({ stats: { np: profile.np, nc: profile.nc }, hasNotification: profile.hasNotification });

        const appWrapper = document.createElement('div');
        appWrapper.id = 'nui-cocoshy-app';
        appWrapper.style.cssText = 'display: flex; flex-direction: column; height: 100vh; padding-top: var(--nui-topbar-h); box-sizing: border-box; align-items: center; background: var(--nui-bg); overflow-y: auto;';

        const contentArea = document.createElement('div');
        contentArea.style.cssText = 'width: 100%; max-width: 600px; padding: var(--nui-space-4); display: flex; flex-direction: column; gap: var(--nui-space-4);';

        appWrapper.appendChild(contentArea);
        document.body.appendChild(appWrapper);
        return contentArea;
    }

    function renderDashboard(container) {
        const dashboard = document.createElement('div');
        dashboard.className = 'nui-surface';
        dashboard.style.cssText = 'border: 1px solid var(--nui-border); border-radius: var(--nui-radius-lg); overflow: hidden; box-shadow: 0 4px 16px var(--nui-shadow); text-align: center; display: flex; flex-direction: column; align-items: center; background: var(--nui-surface);';

        dashboard.innerHTML = `
            <div id="coco-stage" style="width: 100%; height: 150px; border-bottom: 2px solid var(--nui-border); background: var(--nui-surface-2);">
                <img src="https://images.neopets.com/games/clicktoplay/screenshot_fullsize_490_1_v1.png" style="width: 100%; height: 100%; object-fit: cover; object-position: center 20%;">
            </div>



                <div style="font-family: var(--nui-font-display); font-size: 32px; font-weight: 800; color: var(--nui-text);">Coconut Shy</div>
                <div style="font-size: 14px; color: var(--nui-text-muted); font-weight: 600; margin-bottom: 12px;">100 NP per throw. Knock one down to win a prize!</div>

                <div id="coco-result-box" style="width: 80%; min-height: 60px; display: flex; flex-direction: column; align-items: center; justify-content: center; border-radius: var(--nui-radius-md); background: var(--nui-surface-2); border: 1px solid var(--nui-border); font-size: 15px; font-weight: 700; color: var(--nui-text-muted); padding: 12px; transition: all 0.2s;">
                    <span>Ready to throw.</span>
                </div>

                <button type="button" id="btn-throw" class="nui-btn nui-btn-primary" style="font-size: 18px; padding: 16px 32px; border-radius: 30px; width: 100%; max-width: 300px; margin-top: 16px; box-shadow: 0 4px 12px var(--nui-shadow);">
                    Throw (100 NP)
                </button>
                <div id="throw-counter" style="margin-top: 12px; font-size: 12px; color: var(--nui-text-faint); font-weight: 700;">Throws this session: 0</div>
            </div>
        `;

        container.appendChild(dashboard);

        const btnThrow = dashboard.querySelector('#btn-throw');
        const resultBox = dashboard.querySelector('#coco-result-box');
        const cocoStage = dashboard.querySelector('#coco-stage');
        const counterEl = dashboard.querySelector('#throw-counter');

        // If we already know (from an earlier throw today, this session
        // or a prior one) that this account is tapped out until reset,
        // show that immediately instead of a misleading "Ready to throw".
        const storedNextAt = getStoredCoconutNextAt();
        if (storedNextAt && storedNextAt > Date.now()) {
            resultBox.style.background = 'var(--nui-surface-2)';
            resultBox.style.borderColor = 'var(--nui-border)';
            resultBox.style.color = 'var(--nui-text-muted)';
            resultBox.innerHTML = '<span>You\'ve had yer lot for today. Check the Dailies Hub for the reset time.</span>';
            btnThrow.disabled = true;
            btnThrow.textContent = 'Out of Throws';
            btnThrow.style.background = 'var(--nui-surface-2)';
            btnThrow.style.color = 'var(--nui-text-muted)';
        }

        btnThrow.addEventListener('click', async () => {
            btnThrow.disabled = true;
            btnThrow.textContent = 'Aiming...';


            resultBox.style.background = 'var(--nui-surface-2)';
            resultBox.style.borderColor = 'var(--nui-border)';
            resultBox.style.color = 'var(--nui-text-muted)';
            resultBox.innerHTML = `<span>Winding up...</span>`;

            try {
                const res = await throwCoconut();

                if (res.totalNp) updateLiveNP(res.totalNp);


                if (res.error) {
                    cocoStage.style.borderColor = 'var(--nui-danger)';
                    resultBox.style.background = 'rgba(239, 68, 68, 0.05)';
                    resultBox.style.borderColor = 'var(--nui-danger)';
                    resultBox.style.color = 'var(--nui-danger)';
                    resultBox.innerHTML = `<span>${res.error}</span>`;

                    if (res.error.toLowerCase().includes('no more') || res.error.toLowerCase().includes('had yer lot')) {
                        btnThrow.textContent = 'Out of Throws';
                        btnThrow.style.background = 'var(--nui-surface-2)';
                        btnThrow.style.color = 'var(--nui-text-muted)';
                        // Sync timer to midnight NST (approximate: next midnight PST)
                        try {
                            const now = new Date();
                            const pst = new Date(now.toLocaleString('en-US', { timeZone: 'America/Los_Angeles' }));
                            const msTilMidnight = ((23 - pst.getHours()) * 3600 + (59 - pst.getMinutes()) * 60 + (60 - pst.getSeconds())) * 1000;
                            window.NeoUI.syncDailyTimer('coconut-shy', msTilMidnight);
                        } catch (e) {}
                        return;
                    }
                } else if (res.points === 10000) {
                    cocoStage.style.borderColor = 'var(--nui-success)';
                    cocoStage.style.background = 'rgba(16, 185, 129, 0.1)';

                    resultBox.style.background = 'rgba(16, 185, 129, 0.1)';
                    resultBox.style.borderColor = 'var(--nui-success)';
                    resultBox.style.color = 'var(--nui-success)';

                    let winText = `JACKPOT! You exploded the coconut!<br>Won 10,000 NP`;
                    if (res.item) winText += `<br><span style="color: var(--nui-text); font-size: 13px;">Also received: ${res.item}</span>`;

                    resultBox.innerHTML = winText;

                } else if (res.points === 300) {
                    cocoStage.style.borderColor = 'var(--nui-success)';
                    resultBox.style.background = 'rgba(16, 185, 129, 0.05)';
                    resultBox.style.borderColor = 'var(--nui-success)';
                    resultBox.style.color = 'var(--nui-success)';
                    resultBox.innerHTML = `<span>You knocked it down! Won 300 NP.</span>`;

                } else if (res.points === 50) {
                    cocoStage.style.borderColor = 'var(--nui-accent)';
                    resultBox.style.color = 'var(--nui-accent)';
                    resultBox.innerHTML = `<span>You hit it, but it just wobbled. Won 50 NP.</span>`;

                } else {
                    cocoStage.style.borderColor = 'var(--nui-border)';
                    resultBox.style.color = 'var(--nui-text)';
                    resultBox.innerHTML = `<span>You completely missed!</span>`;
                }

                throwCount++;
                counterEl.textContent = `Throws this session: ${throwCount}`;
                btnThrow.textContent = 'Throw Again (100 NP)';
                btnThrow.disabled = false;

            } catch (err) {
                cocoStage.style.borderColor = 'var(--nui-danger)';
                resultBox.style.borderColor = 'var(--nui-danger)';
                resultBox.style.color = 'var(--nui-danger)';
                resultBox.innerHTML = `<span>Network error. Try again.</span>`;
                btnThrow.textContent = 'Throw (100 NP)';
                btnThrow.disabled = false;
            }
        });
    }

    if (document.readyState === 'complete' || document.readyState === 'interactive') {
        try { const container = initAppShell(); renderDashboard(container); } catch (err) { showFatalError(err); }
    } else {
        document.addEventListener('DOMContentLoaded', () => {
            try { const container = initAppShell(); renderDashboard(container); } catch (err) { showFatalError(err); }
        });
    }

})();

// ==============================================================================
// MODULE 35: BURIED TREASURE
// ==============================================================================
// Mobile-friendly pick-a-spot map (scaled clicks), cooldown synced to the
// daily timer hub.
// ==============================================================================

// Activates on: /pirates/buriedtreasure/index.phtml and
//               /pirates/buriedtreasure/buriedtreasure.phtml
//
// The legacy flow spans four different server-rendered states glued together
// by a plain HTML ISMAP: an intro/story screen with a "Play" button, a
// pick-a-spot map, a post-dig cooldown screen, and (unsampled here, but
// certain to exist) a win/lose result screen. All four are scraped from
// whatever `document`/fetch response is on hand and re-rendered as one
// mobile-forward card, with the whole loop — Play, pick a spot, get a
// result — staying inside the SPA via fetch() instead of full page loads.
// ==============================================================================

(function () {
    'use strict';

    if (!/\/pirates\/buriedtreasure\//.test(location.pathname)) return;
    if (!window.NeoUI || !window.NeoUI.isModuleEnabled('buried-treasure')) return;

    const NeoUI = window.NeoUI;
    if (!NeoUI || !NeoUI.__ready) return;

    function showFatalError(err) {
        try {
            const box = document.createElement('div');
            box.style.cssText = 'position:fixed;top:0;left:0;right:0;z-index:99999;background:#fee2e2;color:#7f1d1d;font:14px monospace;padding:15px;white-space:pre-wrap;max-height:50vh;overflow:auto;border-bottom:3px solid #dc2626;';
            box.textContent = 'Buried Treasure SPA crashed:\n' + (err && err.stack ? err.stack : String(err));
            document.body.insertBefore(box, document.body.firstChild);
        } catch (e2) {}
    }

    const DAILY_TIMERS_KEY = 'neoui_daily_timers_v1';
    const TIMER_ID = 'buried-treasure';

    // ─────────────────────────────────────────────────────────────────────────
    // Keep the shared Daily Timer Hub in sync with the real server cooldown,
    // instead of relying on the person remembering to tap "done" over there
    // too — we already know the exact minutes remaining from this page.
    // ─────────────────────────────────────────────────────────────────────────
    function syncTimer(msFromNow) {
        try {
            const raw = localStorage.getItem(DAILY_TIMERS_KEY);
            const parsed = raw ? JSON.parse(raw) : [];
            const list = Array.isArray(parsed) ? parsed : [];
            let entry = list.find(function (item) { return item && item.id === TIMER_ID; });
            if (!entry) { entry = { id: TIMER_ID }; list.push(entry); }
            entry.nextAt = Date.now() + msFromNow;
            localStorage.setItem(DAILY_TIMERS_KEY, JSON.stringify(list));
        } catch (e) {}
        // A fresh cooldown just started, so any stale "ready" notification
        // from the previous round shouldn't stick around in the bell/drawer.
        try { if (NeoUI.timerCleared) NeoUI.timerCleared(TIMER_ID); } catch (e) {}
    }

    function formatClock(msLeft) {
        const totalSec = Math.max(0, Math.ceil(msLeft / 1000));
        const h = Math.floor(totalSec / 3600);
        const m = Math.floor((totalSec % 3600) / 60);
        const s = totalSec % 60;
        const pad = function (n) { return String(n).padStart(2, '0'); };
        return pad(h) + ':' + pad(m) + ':' + pad(s);
    }

    // ─────────────────────────────────────────────────────────────────────────
    // SCRAPERS — figure out which of the four server states `doc` holds
    // ─────────────────────────────────────────────────────────────────────────
    function scrapeState(doc, baseUrl) {
        const content = doc.querySelector('td.content') || doc.body;
        const raw = content.innerHTML;
        const jackpotMatch = raw.match(/Cumulative Jackpot[^0-9]*([\d,]+)\s*NP/i);
        const jackpot = jackpotMatch ? jackpotMatch[1] : null;

        // Cooldown: "Sorry, you have to wait NNN minutes to play again"
        const waitMatch = raw.match(/wait another\s*(\d+)\s*minutes/i);
        if (waitMatch) {
            const petImg = content.querySelector('img[src*="/cpn/"]') || content.querySelector('img');
            return {
                type: 'cooldown',
                minutes: parseInt(waitMatch[1], 10),
                petImage: petImg ? new URL(petImg.getAttribute('src'), baseUrl).href : null,
            };
        }

        // Ready state: the intro story + "Click to Play!" submit button
        const playForm = Array.prototype.find.call(content.querySelectorAll('form'), function (f) {
            return /buriedtreasure\.phtml/i.test(f.getAttribute('action') || '');
        });
        if (playForm) {
            const submitBtn = playForm.querySelector('input[type="submit"]');
            if (submitBtn && /click to play/i.test(submitBtn.value || '')) {
                return {
                    type: 'ready',
                    playAction: new URL(playForm.getAttribute('action'), baseUrl).href,
                };
            }
        }

        // Map state: an ISMAP image wrapped in an <a>
        const mapAnchor = Array.prototype.find.call(content.querySelectorAll('a'), function (a) {
            return a.querySelector('img[ismap], img[ISMAP]');
        });
        if (mapAnchor) {
            const img = mapAnchor.querySelector('img');
            return {
                type: 'map',
                jackpot: jackpot,
                mapImg: new URL(img.getAttribute('src'), baseUrl).href,
                mapAction: new URL(mapAnchor.getAttribute('href'), baseUrl).href,
                naturalWidth: parseInt(img.getAttribute('width'), 10) || 540,
                naturalHeight: parseInt(img.getAttribute('height'), 10) || 550,
            };
        }

       // Result state: a "[pet] pulls out a ticket... and..." narration line,
// then a table whose first row holds the win/lose headline (e.g. "You
// Won Nothing :(" or "You Won 5,000 NP!") spanning both columns, and a
// second row with the pet's picture next to the prize (or blank scroll)
// picture. A closing italic line offers encouragement either way.
const table = content.querySelector('table');
const scope = table || content;
const images = Array.prototype.map.call(scope.querySelectorAll('img'), function (img) {
    return {
        src: new URL(img.getAttribute('src'), baseUrl).href,
        alt: (img.getAttribute('alt') || '').trim(),
    };
});
const headlineCell = table ? table.querySelector('td[colspan], td[bgcolor], th') : null;
const headline = headlineCell ? headlineCell.textContent.replace(/\s+/g, ' ').trim() : null;
const narrationP = Array.prototype.find.call(content.querySelectorAll('p'), function (p) {
    return /pulls out a ticket/i.test(p.textContent);
});
const narration = narrationP ? narrationP.textContent.replace(/\s+/g, ' ').trim() : null;
const flavorEl = content.querySelector('i');
const flavor = flavorEl ? flavorEl.textContent.replace(/\s+/g, ' ').trim() : null;

return {
    type: 'result',
    narration: narration,
    headline: headline,
    flavor: flavor,
    images: images,
};
    }

    async function fetchState(url) {
        const res = await fetch(url, { credentials: 'include' });
        const html = await res.text();
        const doc = new DOMParser().parseFromString(html, 'text/html');
        return scrapeState(doc, url);
    }

    // ─────────────────────────────────────────────────────────────────────────
    // SHARED CHROME — hero banner reused across every state
    // ─────────────────────────────────────────────────────────────────────────
    function buildBanner() {
        const banner = document.createElement('div');
        banner.className = 'nui-surface';
        banner.style.cssText = 'border-radius:var(--nui-radius-lg);border:1px solid var(--nui-border);overflow:hidden;box-shadow:0 4px 12px var(--nui-shadow);position:relative;';
        banner.innerHTML = `
            <div style="position:relative;width:100%;height:110px;overflow:hidden;background:linear-gradient(135deg,#0B2B2E 0%,#124A44 50%,#0B2B2E 100%);display:flex;align-items:center;gap:14px;padding:0 var(--nui-space-4);">
                <img src="https://images.neopets.com/pirates/map_frontpg.gif"
                     style="width:74px;height:74px;border-radius:var(--nui-radius-md);border:2px solid rgba(255,255,255,0.25);object-fit:cover;flex-shrink:0;filter:drop-shadow(0 4px 8px rgba(0,0,0,0.6));background:#fff;"
                     onerror="this.style.display='none'">
                <div>
                    <div style="font-family:var(--nui-font-display);font-weight:800;font-size:26px;color:#FFD060;text-shadow:0 2px 8px rgba(0,0,0,0.6);line-height:1.1;">Buried Treasure</div>
                    <div style="font-size:12.5px;color:rgba(180,255,225,0.9);font-weight:600;margin-top:3px;text-shadow:0 1px 3px rgba(0,0,0,0.5);">Treasure of the Black Pawkeet · once every 3 hours</div>
                </div>
            </div>
        `;
        return banner;
    }

    function backToKrawkButton() {
        const btn = document.createElement('a');
        btn.href = '/pirates/index.phtml';
        btn.className = 'nui-btn nui-btn-secondary nui-btn-block';
        btn.style.cssText = 'text-decoration:none;display:block;box-sizing:border-box;';
        btn.textContent = '← Back to Krawk Island';
        return btn;
    }

    // ─────────────────────────────────────────────────────────────────────────
    // STATE RENDERERS
    // ─────────────────────────────────────────────────────────────────────────
    let clockInterval = null;
    function clearClock() {
        if (clockInterval) { clearInterval(clockInterval); clockInterval = null; }
    }

    function renderReady(wrapper, state) {
        clearClock();
        wrapper.innerHTML = '';
        wrapper.appendChild(buildBanner());

        const card = document.createElement('div');
        card.className = 'nui-surface';
        card.style.cssText = 'border:1px solid var(--nui-border);border-radius:var(--nui-radius-lg);padding:var(--nui-space-5) var(--nui-space-4);box-shadow:0 4px 12px var(--nui-shadow);text-align:center;display:flex;flex-direction:column;align-items:center;gap:var(--nui-space-3);';
        card.innerHTML = `
            <div style="font-size:15px;color:var(--nui-text-muted);line-height:1.5;max-width:420px;">
                Somewhere on Krawk Island, the old pirate Bloodhook's treasure is
                still waiting for someone to dig it up. Pick a square on the map
                and see if fortune's on your side.
            </div>
            <button type="button" id="bt-play-btn" class="nui-btn nui-btn-primary" style="font-size:16px;padding:14px 28px;border-radius:30px;width:100%;max-width:300px;box-shadow:0 4px 12px var(--nui-shadow);">
                Dig for Treasure (300 NP)
            </button>
        `;
        wrapper.appendChild(card);
        wrapper.appendChild(backToKrawkButton());

        card.querySelector('#bt-play-btn').addEventListener('click', async function () {
            const btn = this;
            btn.disabled = true;
            btn.textContent = 'Setting sail...';
            try {
                const next = await fetchState(state.playAction);
                renderState(wrapper, next);
            } catch (err) {
                showFatalError(err);
                btn.disabled = false;
                btn.textContent = 'Dig for Treasure (300 NP)';
            }
        });
    }

    function renderMap(wrapper, state) {
        clearClock();
        wrapper.innerHTML = '';
        wrapper.appendChild(buildBanner());

        const card = document.createElement('div');
        card.className = 'nui-surface';
        card.style.cssText = 'border:1px solid var(--nui-border);border-radius:var(--nui-radius-lg);padding:var(--nui-space-4);box-shadow:0 4px 12px var(--nui-shadow);display:flex;flex-direction:column;align-items:center;gap:var(--nui-space-3);';

        const jackpotHtml = state.jackpot
            ? '<span class="nui-badge nui-badge-accent" style="font-size:12px;padding:5px 12px;">💰 Jackpot: ' + state.jackpot + ' NP</span>'
            : '';

        card.innerHTML = `
            ${jackpotHtml}
            <div style="font-size:14px;font-weight:700;color:var(--nui-text);text-align:center;">Where do <em>you</em> think it's buried?</div>
            <div id="bt-map-wrap" style="position:relative;width:100%;max-width:480px;border-radius:var(--nui-radius-md);overflow:hidden;border:1px solid var(--nui-border);cursor:crosshair;">
                <img id="bt-map-img" src="${state.mapImg}" style="display:block;width:100%;height:auto;">
            </div>
            <div style="font-size:12px;color:var(--nui-text-faint);">Tap anywhere on the map to dig there.</div>
        `;
        wrapper.appendChild(card);
        wrapper.appendChild(backToKrawkButton());

        const mapImg = card.querySelector('#bt-map-img');
        const mapWrap = card.querySelector('#bt-map-wrap');
        let locked = false;

        mapImg.addEventListener('click', async function (e) {
            if (locked) return;
            locked = true;

            const rect = mapImg.getBoundingClientRect();
            const scaleX = state.naturalWidth / rect.width;
            const scaleY = state.naturalHeight / rect.height;
            const x = Math.round((e.clientX - rect.left) * scaleX);
            const y = Math.round((e.clientY - rect.top) * scaleY);

            const overlay = document.createElement('div');
            overlay.style.cssText = 'position:absolute;inset:0;background:rgba(0,0,0,0.55);display:flex;align-items:center;justify-content:center;color:#fff;font-weight:700;font-size:14px;';
            overlay.textContent = 'Digging...';
            mapWrap.style.position = 'relative';
            mapWrap.appendChild(overlay);

            try {
                const digUrl = state.mapAction + '?' + x + ',' + y;
                const next = await fetchState(digUrl);
                renderState(wrapper, next);
            } catch (err) {
                overlay.remove();
                locked = false;
                showFatalError(err);
            }
        });
    }

    function renderCooldown(wrapper, state) {
        clearClock();
        wrapper.innerHTML = '';
        wrapper.appendChild(buildBanner());

        const targetAt = Date.now() + state.minutes * 60 * 1000;
        syncTimer(state.minutes * 60 * 1000);

        const card = document.createElement('div');
        card.className = 'nui-surface';
        card.style.cssText = 'border:1px solid var(--nui-border);border-radius:var(--nui-radius-lg);padding:var(--nui-space-5) var(--nui-space-4);box-shadow:0 4px 12px var(--nui-shadow);text-align:center;display:flex;flex-direction:column;align-items:center;gap:var(--nui-space-3);';
        card.innerHTML = `
            ${state.petImage ? '<img src="' + state.petImage + '" style="width:120px;height:120px;border-radius:var(--nui-radius-md);border:1px solid var(--nui-border);object-fit:cover;">' : ''}
            <div style="font-size:15px;font-weight:700;color:var(--nui-text);">You've already tried your luck this round.</div>
            <div id="bt-clock" style="font-family:var(--nui-font-display);font-size:32px;font-weight:800;color:var(--nui-accent);letter-spacing:1px;">${formatClock(targetAt - Date.now())}</div>
            <div style="font-size:12px;color:var(--nui-text-faint);">until you can dig again</div>
            <button type="button" id="bt-retry-btn" class="nui-btn nui-btn-secondary" style="width:100%;max-width:260px;" disabled>Not ready yet</button>
        `;
        wrapper.appendChild(card);
        wrapper.appendChild(backToKrawkButton());

        const clockEl = card.querySelector('#bt-clock');
        const retryBtn = card.querySelector('#bt-retry-btn');

        clockInterval = setInterval(function () {
            const remaining = targetAt - Date.now();
            if (remaining <= 0) {
                clockEl.textContent = '00:00:00';
                retryBtn.disabled = false;
                retryBtn.textContent = 'Check Again';
                clearClock();
                return;
            }
            clockEl.textContent = formatClock(remaining);
        }, 1000);

        retryBtn.addEventListener('click', async function () {
            retryBtn.disabled = true;
            retryBtn.textContent = 'Checking...';
            try {
                const next = await fetchState(new URL('index.phtml', location.href).href);
                renderState(wrapper, next);
            } catch (err) {
                showFatalError(err);
                retryBtn.disabled = false;
                retryBtn.textContent = 'Check Again';
            }
        });
    }

    function renderResult(wrapper, state) {
    clearClock();
    wrapper.innerHTML = '';
    wrapper.appendChild(buildBanner());

    // Stamp the timer the instant the result renders — this is the moment
    // the dig happened, so the 3-hour cooldown starts now regardless of
    // whether we ever see the server's cooldown screen.
    syncTimer(3 * 60 * 60 * 1000);

    const headline = state.headline || 'The tide has come in — check back later.';
    const isWin = !/nothing/i.test(headline);
    const images = state.images || [];

    const imagesHtml = images.length
        ? '<div style="display:flex;gap:var(--nui-space-3);justify-content:center;flex-wrap:wrap;">' +
            images.map(function (im) {
                return '<div style="display:flex;flex-direction:column;align-items:center;gap:4px;">' +
                    '<img src="' + im.src + '" style="width:110px;height:110px;object-fit:contain;border-radius:var(--nui-radius-md);border:1px solid var(--nui-border);background:var(--nui-surface-alt,#f4f4f4);">' +
                    (im.alt ? '<div style="font-size:11px;color:var(--nui-text-faint);max-width:110px;text-align:center;">' + im.alt + '</div>' : '') +
                    '</div>';
            }).join('') +
          '</div>'
        : '';

    const card = document.createElement('div');
    card.className = 'nui-surface';
    card.style.cssText = 'border:1px solid var(--nui-border);border-radius:var(--nui-radius-lg);padding:var(--nui-space-5) var(--nui-space-4);box-shadow:0 4px 12px var(--nui-shadow);text-align:center;display:flex;flex-direction:column;align-items:center;gap:var(--nui-space-3);';
    card.innerHTML = `
        ${isWin ? '<span class="nui-badge nui-badge-success" style="font-size:12px;padding:5px 12px;">🎉 Treasure Found</span>' : '<span class="nui-badge" style="font-size:12px;padding:5px 12px;">🌊 Empty-Handed</span>'}
        ${state.narration ? '<div style="font-size:14px;font-weight:600;color:var(--nui-text-muted);line-height:1.5;">' + state.narration + '</div>' : ''}
        ${imagesHtml}
        <div style="font-family:var(--nui-font-display);font-size:19px;font-weight:800;color:${isWin ? 'var(--nui-success, #16a34a)' : 'var(--nui-text)'};line-height:1.4;">${headline}</div>
        ${state.flavor ? '<div style="font-size:13px;font-style:italic;color:var(--nui-text-faint);">' + state.flavor + '</div>' : ''}
        <button type="button" id="bt-refresh-btn" class="nui-btn nui-btn-secondary" style="width:100%;max-width:260px;">Refresh</button>
    `;
    wrapper.appendChild(card);
    wrapper.appendChild(backToKrawkButton());

    card.querySelector('#bt-refresh-btn').addEventListener('click', async function () {
        const btn = this;
        btn.disabled = true;
        btn.textContent = 'Refreshing...';
        try {
            const next = await fetchState(new URL('index.phtml', location.href).href);
            renderState(wrapper, next);
        } catch (err) {
            showFatalError(err);
            btn.disabled = false;
            btn.textContent = 'Refresh';
        }
    });
}

    function renderState(wrapper, state) {
        if (state.type === 'ready') return renderReady(wrapper, state);
        if (state.type === 'map') return renderMap(wrapper, state);
        if (state.type === 'cooldown') return renderCooldown(wrapper, state);
        return renderResult(wrapper, state);
    }

    // ─────────────────────────────────────────────────────────────────────────
    // INIT
    // ─────────────────────────────────────────────────────────────────────────
    async function init() {
        const profile = NeoUI.scrapeLegacyProfile();
        const initialState = scrapeState(document, location.href);

        document.body.innerHTML = '';
        document.body.className = 'nui-reset';
        document.documentElement.style.background = 'var(--nui-bg)';
        document.body.style.background = 'var(--nui-bg)';

        NeoUI.init();
        NeoUI.setProfileInfo(profile);
        NeoUI.buildTopbar({ stats: { np: profile.np, nc: profile.nc }, hasNotification: profile.hasNotification });

        const wrapper = document.createElement('div');
        wrapper.className = 'nui-reset';
        wrapper.style.cssText = 'padding: calc(var(--nui-topbar-h) + var(--nui-space-4)) var(--nui-space-4) var(--nui-space-5); max-width: 560px; margin: 0 auto; display: flex; flex-direction: column; gap: var(--nui-space-4);';
        document.body.appendChild(wrapper);

        renderState(wrapper, initialState);
    }

    let booted = false;
    function boot() {
        if (booted) return;
        booted = true;
        init().catch(showFatalError);
    }

    if (document.readyState === 'complete' || document.readyState === 'interactive') {
        boot();
    } else {
        document.addEventListener('DOMContentLoaded', boot);
    }

})();

// ==============================================================================
// MODULE 36: GAMES ROOM
