    function buildNeoboardsTab(hiddenTitleSelect) {
        const titleOptions = hiddenTitleSelect ? hiddenTitleSelect.innerHTML : '<option value="">None</option>';

        const hiddenPenGroup = document.querySelector('.settings-group');
        const customPenHtml = hiddenPenGroup ? `<div class="settings-group" id="nui-pen-group">${hiddenPenGroup.innerHTML}</div>` : '';
        // pen_name_id may not exist yet when Vue is still rendering — resolve lazily
        const getPenNameInput = () => document.getElementById('pen_name_id');

        mainContent.innerHTML = `
            <h2>Neoboard Preferences</h2>
            <div class="nui-desc">Modify your avatar, NeoHTML, signature, and preferences. Changes save automatically when you type!</div>

            ${customPenHtml ? `
            <h3>Select Pen</h3>
            <div class="nui-form-row">
                ${customPenHtml}
            </div>
            ` : ''}

            <div id="nui-pen-name-row" class="nui-form-row">
                <label class="nui-label" style="margin-top: 0;">Pen Name</label>
                <input id="nui-input-pen-name" type="text" class="nui-input" maxlength="20" placeholder="Enter pen name...">
                <div class="nui-desc" style="margin-top: 4px;">Rename the selected pen. Changes save automatically.</div>
            </div>

            <h3>Avatar</h3>
            <div class="nui-form-row">
                <div style="display: flex; align-items: center; gap: 16px;">
                    <div style="width: 80px; height: 80px; border-radius: var(--nui-radius-md); border: 1px solid var(--nui-border); background: var(--nui-surface-2); display: flex; align-items: center; justify-content: center; overflow: hidden; box-shadow: 0 4px 6px -4px var(--nui-shadow);">
                        <img id="nui-avatar-preview" src="//images.neopets.com/neoboards/avatars/default.gif" style="max-width: 100%; max-height: 100%; object-fit: contain;">
                    </div>
                    <button id="nui-btn-avatar" class="nui-btn nui-btn-secondary">Change Avatar</button>
                </div>
            </div>

            <h3>Neotitle</h3>
            <div class="nui-form-row">
                <select id="nui-select-title" class="nui-select">${titleOptions}</select>
            </div>

            <h3>NeoHTML & NeoSignature</h3>
            <div class="nui-form-row">
                <label class="nui-label">NeoHTML</label>
                <input id="nui-input-html" type="text" class="nui-input" maxlength="150" placeholder="e.g. [b]neoHTML[/b]">

                <label class="nui-label">NeoSignature</label>
                <input id="nui-input-sig" type="text" class="nui-input" maxlength="150">

                <div style="margin-top: 12px;">
                    <button id="nui-btn-sticker" class="nui-btn nui-btn-secondary nui-btn-sm">Insert Sticker</button>
                </div>
            </div>

            <h3>Preview</h3>
            <div class="nui-preview-box" id="nui-board-preview">
                <div style="color: #666; font-style: italic;">Loading preview...</div>
            </div>

            <h3>Preferences</h3>
            <div class="nui-form-row">
                <label class="nui-checkbox-row">
                    <input type="checkbox" id="nui-check-font" style="width: 16px; height: 16px;">
                    <span style="font-size: 14px; font-weight: 700; color: var(--nui-text);">Hide NeoHTML Font Effects</span>
                </label>
                <label class="nui-checkbox-row">
                    <input type="checkbox" id="nui-check-sig" style="width: 16px; height: 16px;">
                    <span style="font-size: 14px; font-weight: 700; color: var(--nui-text);">Hide NeoSignatures</span>
                </label>
            </div>
        `;

        const hiddenAv = document.getElementById('userAv');
        const hiddenTitle = document.getElementById('neotitle');
        const hiddenHtml = document.getElementById('neohtml_id');
        const hiddenSig = document.getElementById('neosignature_id');
        const hiddenHideFont = document.getElementById('hide_font');
        const hiddenHideSig = document.getElementById('hide_siggy');
        const hiddenPreview = document.getElementById('neoboard_preview');

        const customPenGroup = document.getElementById('nui-pen-group');
        const customPenName = document.getElementById('nui-input-pen-name');
        const customAvPrev = document.getElementById('nui-avatar-preview');
        const customTitle = document.getElementById('nui-select-title');
        const customHtml = document.getElementById('nui-input-html');
        const customSig = document.getElementById('nui-input-sig');
        const customHideFont = document.getElementById('nui-check-font');
        const customHideSig = document.getElementById('nui-check-sig');
        const customPreview = document.getElementById('nui-board-preview');

        if (hiddenAv) customAvPrev.src = `//images.neopets.com/neoboards/avatars/${hiddenAv.value}.gif`;
        if (hiddenTitle) customTitle.value = hiddenTitle.value;
        if (hiddenHtml) customHtml.value = hiddenHtml.value;
        if (hiddenSig) customSig.value = hiddenSig.value;
        if (hiddenHideFont) customHideFont.checked = hiddenHideFont.checked;
        if (hiddenHideSig) customHideSig.checked = hiddenHideSig.checked;
        // Sync pen name once Vue has had time to populate pen_name_id
        setTimeout(() => {
            const hpni = getPenNameInput();
            if (hpni && customPenName) customPenName.value = hpni.value;
        }, 300);

        if (hiddenPreview) {
            customPreview.innerHTML = hiddenPreview.title || hiddenPreview.innerHTML;
            const innerPreview = customPreview.querySelector('.neoboard-preview');
            if (innerPreview) {
                innerPreview.style.background = '#ffffff';
                innerPreview.style.color = '#000000';
            }
        }

        function triggerVueChange(hiddenEl, value, isCheckbox = false) {
            if (!hiddenEl) return;
            if (isCheckbox) hiddenEl.checked = value;
            else hiddenEl.value = value;
            hiddenEl.dispatchEvent(new Event('input', { bubbles: true }));
            hiddenEl.dispatchEvent(new Event('change', { bubbles: true }));
        }

        if (customPenGroup && hiddenPenGroup) {
            customPenGroup.addEventListener('click', e => {
                const btn = e.target.closest('.settings-button');
                if (!btn) return;

                // Click the native hidden button so Vue updates its state
                const hiddenBtn = hiddenPenGroup.querySelector(`[id="${btn.id}"]`);
                if (hiddenBtn) hiddenBtn.click();

                // Immediately load this pen's current name into the custom field.
                // The label text inside the native button is the pen's saved name.
                if (customPenName) {
                    const penLabel = btn.querySelector('b');
                    if (penLabel) {
                        // Give Vue ~250 ms to update pen_name_id for the newly selected pen
                        setTimeout(() => {
                            const hpni = getPenNameInput();
                            if (hpni && document.activeElement !== customPenName) {
                                customPenName.value = hpni.value || penLabel.textContent;
                            }
                        }, 250);
                    }
                }
            });
        }

        if (customPenName) customPenName.addEventListener('input', e => {
            const hpni = getPenNameInput();
            triggerVueChange(hpni, e.target.value);
            // Update the active pen button label live so the strip reflects the new name
            if (customPenGroup) {
                const activeLabel = customPenGroup.querySelector('.settings-button b.active');
                if (activeLabel) activeLabel.textContent = e.target.value;
            }
        });
        customTitle.addEventListener('change', e => triggerVueChange(hiddenTitle, e.target.value));
        customHtml.addEventListener('input', e => triggerVueChange(hiddenHtml, e.target.value));
        customSig.addEventListener('input', e => triggerVueChange(hiddenSig, e.target.value));
        customHideFont.addEventListener('change', e => triggerVueChange(hiddenHideFont, e.target.checked, true));
        customHideSig.addEventListener('change', e => triggerVueChange(hiddenHideSig, e.target.checked, true));

        document.getElementById('nui-btn-avatar').addEventListener('click', openAvatarModal);
        document.getElementById('nui-btn-sticker').addEventListener('click', openStickerModal);

        currentObserver = new MutationObserver(() => {
            if (hiddenPenGroup && customPenGroup) {
                const activeB = hiddenPenGroup.querySelector('b.active');
                const hiddenActiveBtn = activeB ? activeB.closest('.settings-button') : null;

                if (hiddenActiveBtn) {
                    customPenGroup.querySelectorAll('.settings-button').forEach(btn => {
                        const isActive = btn.id === hiddenActiveBtn.id;
                        btn.querySelectorAll('img, b').forEach(el => {
                            if (isActive) {
                                el.classList.add('active');
                                el.classList.remove('inactive');
                            } else {
                                el.classList.remove('active');
                                el.classList.add('inactive');
                            }
                        });
                    });
                }
            }

            const hpni = getPenNameInput();
            if (hpni && document.activeElement !== customPenName) {
                customPenName.value = hpni.value;
            }
            if (hiddenAv && customAvPrev.src.indexOf(hiddenAv.value) === -1) {
                customAvPrev.src = `//images.neopets.com/neoboards/avatars/${hiddenAv.value}.gif`;
            }
            if (hiddenPreview && hiddenPreview.title !== customPreview.innerHTML) {
                customPreview.innerHTML = hiddenPreview.title || hiddenPreview.innerHTML;
                const innerPreview = customPreview.querySelector('.neoboard-preview');
                if (innerPreview) {
                    innerPreview.style.background = '#ffffff';
                    innerPreview.style.color = '#000000';
                }
            }
            if (hiddenSig && document.activeElement !== customSig) {
                customSig.value = hiddenSig.value;
            }
            if (hiddenHtml && document.activeElement !== customHtml) {
                customHtml.value = hiddenHtml.value;
            }

            guardPenNameField();
        });

        if (hiddenPreview) currentObserver.observe(hiddenPreview, { attributes: true, childList: true, subtree: true });
        if (hiddenAv) currentObserver.observe(hiddenAv, { attributes: true });
        if (hiddenSig) currentObserver.observe(hiddenSig, { attributes: true });
        if (hiddenHtml) currentObserver.observe(hiddenHtml, { attributes: true });
        if (appRoot) currentObserver.observe(appRoot, { childList: true, subtree: true });

        guardPenNameField();
    }

    // ── 6. NeoUI Custom Modals (Avatars & Stickers) ──────────────────────────
    function createNeoUIModal(title, searchPlaceholder, buildGridFn) {
        const backdrop = document.createElement('div');
        backdrop.className = 'nui-drawer-backdrop nui-reset is-open';
        backdrop.style.cssText = 'position:fixed;inset:0;z-index:100000;background:var(--nui-overlay);display:flex;align-items:center;justify-content:center;padding:var(--nui-space-4);';

        const modal = document.createElement('div');
        modal.className = 'nui-surface';
        modal.style.cssText = 'width:100%;max-width:600px;max-height:85vh;border-radius:var(--nui-radius-lg);border:1px solid var(--nui-border);box-shadow:0 10px 40px rgba(0,0,0,0.5);display:flex;flex-direction:column;overflow:hidden;transform:scale(0.95);opacity:0;transition:all var(--nui-dur-fast) var(--nui-ease-snap);';

        function closeModal() {
            modal.style.transform = 'scale(0.95)'; modal.style.opacity = '0';
            backdrop.style.opacity = '0';
            setTimeout(() => backdrop.remove(), 200);
        }

        backdrop.addEventListener('click', e => { if (e.target === backdrop) closeModal(); });
        document.addEventListener('keydown', function esc(e) { if (e.key === 'Escape') { closeModal(); document.removeEventListener('keydown', esc); } });

        const header = document.createElement('div');
        header.style.cssText = 'padding:16px 20px;border-bottom:1px solid var(--nui-border);background:var(--nui-surface-2);display:flex;justify-content:space-between;align-items:center;flex-shrink:0;';
        header.innerHTML = `
            <div style="font-family:var(--nui-font-display);font-size:20px;font-weight:800;color:var(--nui-text);">${title}</div>
            <button type="button" class="nui-reset" style="font-size:24px;cursor:pointer;color:var(--nui-text-muted);line-height:1;">&times;</button>
        `;
        header.querySelector('button').addEventListener('click', closeModal);

        const content = document.createElement('div');
        content.style.cssText = 'flex:1;overflow-y:auto;padding:16px 20px;display:flex;flex-direction:column;gap:12px;';

        const searchWrap = document.createElement('div');
        searchWrap.style.cssText = 'position:sticky; top:-16px; background:var(--nui-surface); z-index:10; padding-bottom:12px; border-bottom:1px solid var(--nui-border); margin-top:-16px; padding-top:16px; display:flex; flex-direction:column; gap:8px;';

        const searchInput = document.createElement('input');
        searchInput.type = 'text';
        searchInput.placeholder = searchPlaceholder;
        searchInput.className = 'nui-input';

        const controlsWrap = document.createElement('div');
        controlsWrap.style.cssText = 'display:flex; gap:8px;';

        searchWrap.appendChild(searchInput);
        searchWrap.appendChild(controlsWrap);

        const grid = document.createElement('div');
        grid.className = 'nui-custom-grid';

        buildGridFn(grid, closeModal, controlsWrap, searchInput);

        content.appendChild(searchWrap);
        content.appendChild(grid);
        modal.appendChild(header);
        modal.appendChild(content);
        backdrop.appendChild(modal);
        document.body.appendChild(backdrop);

        requestAnimationFrame(() => {
            modal.style.transform = 'scale(1)';
            modal.style.opacity = '1';
            searchInput.focus();
        });
    }

    function openAvatarModal() {
        createNeoUIModal('Choose an Avatar', 'Search avatars...', (grid, closeModal, controlsWrap, searchInput) => {
            const popupBody = document.querySelector('#SelectAvatarPopup .popup-body__2020');
            const basicAvs = popupBody ? Array.from(popupBody.querySelectorAll('.settings-avatars:nth-of-type(1) .settings-av')) : [];
            const secretAvs = popupBody ? Array.from(popupBody.querySelectorAll('.settings-avatars:nth-of-type(2) .settings-av')) : [];

            let avData = [];
            let nativeIdx = 0;

            const processAv = (el, isSecret) => {
                const img = el.querySelector('img');
                const avId = el.id.replace('Avvie', '');
                avData.push({
                    id: avId,
                    name: el.textContent.trim(),
                    src: img ? img.src : '',
                    isSecret: isSecret,
                    nativeIndex: nativeIdx++,
                    card: null
                });
            };

            basicAvs.forEach(el => processAv(el, false));
            secretAvs.forEach(el => processAv(el, true));

            const currentAv = document.getElementById('userAv') ? document.getElementById('userAv').value : '';

            avData.forEach(av => {
                const card = document.createElement('div');
                card.className = 'nui-settings-av' + (av.id === currentAv ? ' selected-av' : '');
                card.innerHTML = `<img src="${av.src}" alt="${av.name}"><br>${av.name}`;
                card.addEventListener('click', () => {
                    const hiddenAv = document.getElementById('userAv');
                    if (hiddenAv) {
                        hiddenAv.value = av.id;
                        hiddenAv.dispatchEvent(new Event('input', { bubbles: true }));
                        hiddenAv.dispatchEvent(new Event('change', { bubbles: true }));
                    }
                    closeModal();
                });
                av.card = card;
            });

            const filterSelect = document.createElement('select');
            filterSelect.className = 'nui-select';
            filterSelect.style.cssText = 'padding:6px 10px; font-size:12px;';
            filterSelect.innerHTML = `
                <option value="all">All Avatars</option>
                <option value="default">Default Only</option>
                <option value="secret">Secret Only</option>
            `;

            const sortSelect = document.createElement('select');
            sortSelect.className = 'nui-select';
            sortSelect.style.cssText = 'padding:6px 10px; font-size:12px;';
            sortSelect.innerHTML = `
                <option value="az">A-Z</option>
                <option value="za">Z-A</option>
                <option value="newest">Newest First</option>
                <option value="oldest">Oldest First</option>
            `;

            controlsWrap.appendChild(filterSelect);
            controlsWrap.appendChild(sortSelect);

            function applyFilters() {
                const q = searchInput.value.toLowerCase().replace(/[^a-z0-9\s]/g, '');
                const filter = filterSelect.value;
                const sort = sortSelect.value;

                avData.sort((a, b) => {
                    if (sort === 'az') return a.name.localeCompare(b.name);
                    if (sort === 'za') return b.name.localeCompare(a.name);
                    if (sort === 'newest') return b.nativeIndex - a.nativeIndex;
                    if (sort === 'oldest') return a.nativeIndex - b.nativeIndex;
                });

                grid.innerHTML = '';
                avData.forEach(av => {
                    grid.appendChild(av.card);
                    let matchFilter = true;
                    if (filter === 'default' && av.isSecret) matchFilter = false;
                    if (filter === 'secret' && !av.isSecret) matchFilter = false;
                    let matchSearch = av.name.toLowerCase().replace(/[^a-z0-9\s]/g, '').includes(q);
                    av.card.style.display = (matchFilter && matchSearch) ? '' : 'none';
                });
            }

            searchInput.addEventListener('input', applyFilters);
            filterSelect.addEventListener('change', applyFilters);
            sortSelect.addEventListener('change', applyFilters);

            applyFilters();
        });
    }

    function openStickerModal() {
        createNeoUIModal('Choose a Sticker', 'Search stickers...', (grid, closeModal, controlsWrap, searchInput) => {
            const nativeStickers = Array.from(document.querySelectorAll('#SelectStickerPopup .sticker'));

            let stkData = nativeStickers.map(el => {
                const img = el.querySelector('img');
                const isUnavailable = el.classList.contains('unavailable');
                return {
                    id: el.id, code: el.getAttribute('code'), name: el.textContent.trim(), src: img ? img.src : '', unavailable: isUnavailable, card: null
                };
            });

            stkData.forEach(stk => {
                const card = document.createElement('div');
                card.className = 'nui-sticker' + (stk.unavailable ? ' unavailable' : '');
                card.innerHTML = `<img src="${stk.src}" alt="${stk.name}"><br>${stk.name}`;
                card.addEventListener('click', () => {
                    if (stk.unavailable) {
                        if (confirm("You haven't obtained this sticker yet. Check out the NC Mall for bundles!")) {
                            window.open('https://ncmall.neopets.com/', '_blank');
                        }
                        return;
                    }
                    const hiddenSig = document.getElementById('neosignature_id');
                    if (hiddenSig) {
                        hiddenSig.value += stk.code + ' ';
                        hiddenSig.dispatchEvent(new Event('input', { bubbles: true }));
                        hiddenSig.dispatchEvent(new Event('change', { bubbles: true }));
                    }
                    closeModal();
                });
                stk.card = card;
            });

            const filterSelect = document.createElement('select');
            filterSelect.className = 'nui-select';
            filterSelect.style.cssText = 'padding:6px 10px; font-size:12px;';
            filterSelect.innerHTML = `
                <option value="all">All Stickers</option>
                <option value="unlocked">Unlocked Only</option>
            `;
            controlsWrap.appendChild(filterSelect);

            function applyFilters() {
                const q = searchInput.value.toLowerCase().replace(/[^a-z0-9\s]/g, '');
                const filter = filterSelect.value;

                stkData.sort((a, b) => {
                    if (a.unavailable !== b.unavailable) return a.unavailable ? 1 : -1;
                    return a.name.localeCompare(b.name);
                });

                grid.innerHTML = '';
                stkData.forEach(stk => {
                    grid.appendChild(stk.card);
                    let matchFilter = filter === 'unlocked' ? !stk.unavailable : true;
                    let matchSearch = stk.name.toLowerCase().replace(/[^a-z0-9\s]/g, '').includes(q);
                    stk.card.style.display = (matchFilter && matchSearch) ? '' : 'none';
                });
            }

            searchInput.addEventListener('input', applyFilters);
            filterSelect.addEventListener('change', applyFilters);

            applyFilters();
        });
    }

